INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circuits'), 'circuits-combination-circuit', 'วงจรผสม', 'วงจรผสมคือการผสมการต่ออนุกรมและขนานในวงจรเดียว วิเคราะห์โดยย่อยให้เหลือความต้านทานรวม แล้วใช้กฎของโอห์มย้อนกลับเพื่อหากระแสและความต่างศักย์ในแต่ละส่วน', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit'), 'youtube', 'https://www.youtube.com/watch?v=ucKBpVl8uBo', 'ucKBpVl8uBo', 'ฟิสิกส์ ม.5 บทที่ 14 ไฟฟ้ากระแส ep.3 (ตัวต้านทาน การต่อตัวต้านทานแบบอนุกรม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit'), 'แบบทดสอบ: วงจรผสม', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit')), 'choice', 'วิธีแรกในการวิเคราะห์วงจรผสมที่ถูกต้องคือข้อใด', '["หาความต้านทานรวมของส่วนที่ต่อขนานก่อน แล้วรวมกับส่วนอนุกรม","หากระแสแต่ละจุดก่อนโดยไม่ยุบความต้านทาน","ตัดตัวต้านทานส่วนใหญ่ทิ้ง","ใช้กฎข้อหนึ่งของนิวตันแทน"]', '0', 'การวิเคราะห์วงจรผสมเริ่มจากยุบส่วนที่ขนานรวมเป็นหนึ่ง แล้วรวมกับอนุกรมให้ได้ Rรวม จากนั้นจึงหากระแสรวมและย้อนกลับไปแต่ละส่วน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit')), 'choice', 'ในวงจรผสม ถ้ายุบความต้านทานขนาน 6 โอห์ม กับ 12 โอห์ม เป็นตัวเดียว ความต้านทานรวมของส่วนขนานนี้เท่ากับกี่โอห์ม', '["9 โอห์ม","4 โอห์ม","2 โอห์ม","18 โอห์ม"]', '1', '1/R = 1/6 + 1/12 = 3/12 = 1/4 ดังนั้น R = 4 โอห์ม', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit')), 'choice', 'กระแสไฟฟ้าที่ไหลเข้าจุดแยกของวงจรขนาน มีความสัมพันธ์กับกระแสที่ไหลออกจากจุดแยกอย่างไร', '["ไม่มีกฎเกี่ยวข้อง","กระแสเข้าต่างจากกระแสออกเสมอ","กระแสเข้าทั้งหมดเท่ากับผลรวมกระแสออก","กระแสเข้าดีกว่ากระแสออก"]', '2', 'ประจุไม่สูญหาย ณ จุดแยก กระแสเข้าทั้งหมดจึงเท่ากับผลรวมกระแสที่ไหลออก (ตามกฎข้อหนึ่งของเคอร์ชอฟฟ์)', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit')), 'number', 'วงจรผสมประกอบด้วยตัวต้านทาน 6 โอห์ม และ 12 โอห์ม ต่อขนานกัน แล้วต่ออนุกรมกับตัวต้านทาน 5 โอห์ม ความต้านทานรวมของวงจรเท่ากับกี่โอห์ม (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":9,"tolerance":0.5}', 'ส่วนขนาน R = (6×12)/(6+12) = 72/18 = 4 โอห์ม แล้วรวมอนุกรมกับ 5 โอห์ม ได้ Rรวม = 4 + 5 = 9 โอห์ม', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit')), 'number', 'จากวงจรข้อก่อนหน้า ถ้าต่อแบตเตอรี่ 18 โวลต์ คร่อมวงจร กระแสไฟฟ้ารวมเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'I = V/Rรวม = 18 / 9 = 2 แอมแปร์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circuits'), 'circuits-current-voltage-resistance', 'กระแสไฟฟ้า ความต่างศักย์ ความต้านทาน', 'กระแสไฟฟ้าคือการไหลของประจุในวงจรปิด มีหน่วยแอมแปร์ ความต่างศักย์ผลักดันให้ประจุไหล และความต้านทานขัดขวางการไหล หน่วยความต้านทานคือโอห์ม', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance'), 'youtube', 'https://www.youtube.com/watch?v=Ja4k6PCjDsM', 'Ja4k6PCjDsM', 'ฟิสิกส์ ม.5 บทที่ 14 ไฟฟ้ากระแส ep.2 (กฎของโอห์ม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
