INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance'), 'แบบทดสอบ: กระแสไฟฟ้า ความต่างศักย์ ความต้านทาน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance')), 'choice', 'กระแสไฟฟ้าในวงจรหมายถึงข้อใด', '["อัตราการไหลของประจุไฟฟ้าผ่านจุดหนึ่งต่อหน่วยเวลา","ปริมาณพลังงานที่ใช้ต่อหน่วยเวลา","ความต่างศักย์ระหว่างปลายสองจุด","จำนวนความต้านทานในวงจร"]', '0', 'กระแสไฟฟ้า I คือ อัตราการเคลื่อนที่ของประจุผ่านจุดหนึ่งต่อหน่วยเวลา I = q/t หน่วยแอมแปร์ (คูลอมบ์/วินาที)', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance')), 'choice', 'หน่วยของความต่างศักย์ และความต้านทาน คือข้อใดตามลำดับ', '["โอห์ม และ แอมแปร์","โวลต์ และ โอห์ม","แอมแปร์ และ โวลต์","คูลอมบ์ และ โอห์ม"]', '1', 'ความต่างศักย์มีหน่วยโวลต์ (V) ความต้านทานมีหน่วยโอห์ม (Ω) กระแสมีหน่วยแอมแปร์ ประจุมีหน่วยคูลอมบ์', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance')), 'choice', 'ถ้าความต่างศักย์คงที่ แต่เพิ่มความต้านทานของวงจร กระแสไฟฟ้าจะเป็นอย่างไร', '["เท่าเดิม","เป็นศูนย์เสมอ","เพิ่มขึ้น","ลดลง"]', '3', 'จาก I = V/R เมื่อ V คงที่และ R เพิ่มขึ้น กระแส I จะลดลง เพราะความต้านทานขัดขวางการไหลของประจุ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance')), 'number', 'ประจุ 15 คูลอมบ์ ไหลผ่านจุดหนึ่งในเส้นลวดใช้เวลา 5 วินาที กระแสไฟฟ้าเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'I = q/t = 15 / 5 = 3 แอมแปร์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance')), 'number', 'กระแสไฟฟ้า 2 แอมแปร์ ไหลในวงจรเป็นเวลา 10 วินาที ประจุไฟฟ้าทั้งหมดที่ไหลผ่านจุดหนึ่งเท่ากับกี่คูลอมบ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', 'q = It = 2 × 10 = 20 คูลอมบ์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circuits'), 'circuits-kirchhoff-battery', 'กฎของเคอร์ชอฟฟ์และแบตเตอรี', 'กฎข้อหนึ่งของเคอร์ชอฟฟ์ว่าประจุเข้าจุดเท่ากับประจุออก กฎข้อสองว่าผลรวมความต่างศักย์รอบวงรอบเป็นศูนย์ และแบตเตอรีมีแรงเคลื่อนไฟฟ้ากับความต้านทานภายใน', 'senior', 7, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery'), 'youtube', 'https://www.youtube.com/watch?v=Ei-GN8iqJ4g', 'Ei-GN8iqJ4g', 'ฟิสิกส์ ม.5 บทที่ 14 ไฟฟ้ากระแส ep.7(แรงเคลื่อนไฟฟ้า, ค่า emf)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery'), 'แบบทดสอบ: กฎของเคอร์ชอฟฟ์และแบตเตอรี', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery')), 'choice', 'กฎข้อหนึ่งของเคอร์ชอฟฟ์ (กฎกระแส) กล่าวว่าอย่างไร', '["ผลรวมกระแสเข้าจุดใดจุดหนึ่งเท่ากับผลรวมกระแสออกจากจุดนั้น","กระแสเข้าต้องมากกว่ากระแสออกเสมอ","กระแสลดลงตามระยะทาง","กระแสในวงจรขนานเท่ากันทุกแขน"]', '0', 'เนื่องจากการอนุรักษ์ประจุ ประจุไม่สะสม ณ จุดเชื่อม ผลรวมกระแสเข้าจึงเท่ากับผลรวมกระแสออกเสมอ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery')), 'choice', 'แรงเคลื่อนไฟฟ้า (emf) ของแบตเตอรี หมายถึงข้อใด', '["ความต้านทานภายในของแบตเตอรี","ความต่างศักย์ที่ขั้วแบตเตอรีเมื่อมีกระแสไหล","งานที่แบตเตอรีทำต่อหนึ่งหน่วยประจุที่เคลื่อนครบวงจร","กำลังไฟฟ้าของแบตเตอรี"]', '2', 'emf คือพลังงานที่แบตเตอรีให้ต่อหนึ่งหน่วยประจุ (จูล/คูลอมบ์ หรือโวลต์) ความต่างศักย์ที่ขั้ว V = emf − Ir เมื่อมีกระแสไหล จึงอาจน้อยกว่า emf เนื่องจากความต้านทานภายใน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery')), 'choice', 'แบตเตอรีมีความต้านทานภายใน เมื่อมีกระแสไหล ความต่างศักย์ที่ขั้วแบตเตอรีเทียบกับ emf เป็นอย่างไร', '["มากกว่า emf","เป็นศูนย์","เท่ากันเสมอ","น้อยกว่า emf"]', '3', 'V = emf − Ir ความต่างศักย์ขั้วน้อยกว่า emf เพราะแรงดันส่วนหนึ่งตกคร่อมความต้านทานภายใน r', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery')), 'number', 'แบตเตอรี emf 12 โวลต์ มีความต้านทานภายใน 0.5 โอห์ม ต่อกับความต้านทานภายนอก 5.5 โอห์ม กระแสไฟฟ้าในวงจรเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'I = emf / (R + r) = 12 / (5.5 + 0.5) = 12 / 6 = 2 แอมแปร์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery')), 'number', 'จากแบตเตอรีข้อก่อนหน้า (emf 12 โวลต์, r = 0.5 โอห์ม) เมื่อมีกระแส 2 แอมแปร์ไหล ความต่างศักย์ที่ขั้วแบตเตอรีเท่ากับกี่โวลต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":11,"tolerance":0.5}', 'V = emf − Ir = 12 − (2 × 0.5) = 12 − 1 = 11 โวลต์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circuits'), 'circuits-ohms-law', 'กฎของโอห์ม', 'กฎของโอห์มกล่าวว่า เมื่ออุณหภูมิคงที่ กระแสไฟฟ้าแปรผันตรงกับความต่างศักย์ และแปรผกผันกับความต้านทาน เขียนเป็น V = IR', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
