INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-ohms-law'), 'แบบทดสอบ: กฎของโอห์ม', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-ohms-law')), 'choice', 'กฎของโอห์มกล่าวถึงความสัมพันธ์ของปริมาณใด', '["มวลกับความเร่ง","ความต่างศักย์ กระแสไฟฟ้า และความต้านทาน","พลังงานกับอุณหภูมิ","แรงกับระยะทาง"]', '1', 'กฎของโอห์ม V = IR เชื่อมความต่างศักย์ (V) กระแสไฟฟ้า (I) และความต้านทาน (R) โดย V = IR', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-ohms-law')), 'choice', 'ตามกฎของโอห์ม ถ้าเพิ่มความต่างศักย์เป็น 2 เท่า โดยความต้านทานคงที่ กระแสไฟฟ้าจะเป็นกี่เท่าของเดิม', '["เท่าเดิม","4 เท่า","2 เท่า","1/2 เท่า"]', '2', 'จาก I = V/R เมื่อ R คงที่ กระแสแปรผันตรงกับความต่างศักย์ V เป็น 2 เท่า I จึงเป็น 2 เท่า', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-ohms-law')), 'choice', 'ตัวต้านทานตัวหนึ่งต่อกับแบตเตอรี่ 6 โวลต์ ทำให้กระแส 2 แอมแปร์ ไหลผ่าน ความต้านทานเท่ากับกี่โอห์ม', '["2 โอห์ม","12 โอห์ม","8 โอห์ม","3 โอห์ม"]', '3', 'R = V/I = 6 / 2 = 3 โอห์ม', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-ohms-law')), 'number', 'ตัวต้านทาน 4 โอห์ม ต่อกับแบตเตอรี่ 12 โวลต์ กระแสไฟฟ้าเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'I = V/R = 12 / 4 = 3 แอมแปร์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-ohms-law')), 'number', 'กระแส 0.5 แอมแปร์ ไหลผ่านตัวต้านทาน 20 โอห์ม ความต่างศักย์คร่อมตัวต้านทานเท่ากับกี่โวลต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":10,"tolerance":0.5}', 'V = IR = 0.5 × 20 = 10 โวลต์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circuits'), 'circuits-power-energy', 'กำลังไฟฟ้าและพลังงานไฟฟ้า', 'กำลังไฟฟ้าคืออัตราการใช้พลังงานไฟฟ้า คำนวณได้จาก P = VI = I²R = V²/R หน่วยวัตต์ ส่วนพลังงานไฟฟ้าที่ใช้คือ P คูณเวลา หน่วยจูลหรือหน่วยกิโลวัตต์-ชั่วโมง', 'senior', 6, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-power-energy'), 'youtube', 'https://www.youtube.com/watch?v=DrSLVCDQpLc', 'DrSLVCDQpLc', 'ฟิสิกส์ ม.5 บทที่ 14 ไฟฟ้ากระแส ep.6(พลังงานไฟฟ้า กำลังไฟฟ้า)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-power-energy'), 'ohm-law', 'ปรับ V และ R แล้วดูกระแสและกำลังไฟฟ้า', '{"voltage":{"min":1,"max":24,"default":12},"resistance":{"min":1,"max":20,"default":6}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-power-energy'), 'match-circuit', 'ปรับวงจรให้ได้กระแสตามเป้าหมาย', '{"tolerance":0.1}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-power-energy'), 'แบบทดสอบ: กำลังไฟฟ้าและพลังงานไฟฟ้า', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-power-energy')), 'choice', 'กำลังไฟฟ้าของวงจรที่ความต่างศักย์ V และกระแส I หาได้จากสูตรใด', '["P = VI","P = I/V","P = ½VI²","P = V/I"]', '0', 'กำลังไฟฟ้า P = VI หน่วยวัตต์ (จูล/วินาที) และสามารถเขียนได้เป็น P = I²R หรือ P = V²/R', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-power-energy')), 'choice', 'หน่วยของพลังงานไฟฟ้าตามบิลค่าไฟที่การไฟฟ้าเรียกเก็บ คือข้อใด', '["โวลต์","กิโลวัตต์-ชั่วโมง","แอมแปร์","โอห์ม"]', '1', 'พลังงานไฟฟ้าคิดในหน่วยกิโลวัตต์-ชั่วโมง (หน่วย) ซึ่งเท่ากับกำลังไฟฟ้าเป็นกิโลวัตต์คูณเวลาเป็นชั่วโมง ส่วนแอมแปร์คือหน่วยกระแส โอห์มคือความต้านทาน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-power-energy')), 'choice', 'หลอดไฟมีกำลัง 100 วัตต์ ใช้ไฟฟ้านาน 10 ชั่วโมง พลังงานไฟฟ้าที่ใช้คิดเป็นกี่หน่วย', '["100 หน่วย","0.1 หน่วย","1 หน่วย","10 หน่วย"]', '2', 'พลังงาน = P × t = 0.1 กิโลวัตต์ × 10 ชั่วโมง = 1 กิโลวัตต์-ชั่วโมง = 1 หน่วย', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-power-energy')), 'number', 'หลอดไฟต่อกับความต่างศักย์ 220 โวลต์ มีกระแสไหลผ่าน 0.5 แอมแปร์ กำลังไฟฟ้าของหลอดเท่ากับกี่วัตต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":110,"tolerance":0.5}', 'P = VI = 220 × 0.5 = 110 วัตต์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-power-energy')), 'number', 'เครื่องทำน้ำอุ่นใช้กำลัง 2 กิโลวัตต์ เปิดนาน 3 ชั่วโมง พลังงานไฟฟ้าที่ใช้เท่ากับกี่หน่วย (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":6,"tolerance":0.5}', 'พลังงาน = P × t = 2 กิโลวัตต์ × 3 ชั่วโมง = 6 กิโลวัตต์-ชั่วโมง = 6 หน่วย', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circuits'), 'circuits-resistors-parallel', 'ตัวต้านทานต่อขนาน', 'การต่อตัวต้านทานแบบขนาน ความต่างศักย์คร่อมแต่ละแขนเท่ากัน กระแสไฟฟ้าแบ่งไหลตามแต่ละแขน และส่วนกลับของความต้านทานรวมเท่ากับผลบวกส่วนกลับของความต้านทานแต่ละตัว', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel'), 'youtube', 'https://www.youtube.com/watch?v=ucKBpVl8uBo', 'ucKBpVl8uBo', 'ฟิสิกส์ ม.5 บทที่ 14 ไฟฟ้ากระแส ep.3 (ตัวต้านทาน การต่อตัวต้านทานแบบอนุกรม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel'), 'แบบทดสอบ: ตัวต้านทานต่อขนาน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel')), 'choice', 'ตัวต้านทานที่ต่อขนานกัน ความต่างศักย์คร่อมแต่ละตัวเป็นอย่างไร', '["เท่ากันทุกตัว","ต่างกันตามความต้านทาน","รวมกันเท่ากับศูนย์","มีเฉพาะตัวแรกเท่านั้น"]', '0', 'การต่อขนาน ปลายของทุกแขนต่ออยู่ที่จุดเดียวกัน ความต่างศักย์คร่อมทุกตัวจึงเท่ากันทั้งหมด', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel')), 'choice', 'ต่อตัวต้านทาน 6 โอห์ม และ 3 โอห์ม แบบขนาน ความต้านทานรวมเท่ากับกี่โอห์ม', '["4.5 โอห์ม","2 โอห์ม","18 โอห์ม","9 โอห์ม"]', '1', '1/Rรวม = 1/6 + 1/3 = 1/6 + 2/6 = 3/6 = 1/2 ดังนั้น Rรวม = 2 โอห์ม', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel')), 'choice', 'การต่อความต้านทานแบบขนาน ความต้านทานรวมเมื่อเทียบกับตัวต้านทานตัวใดตัวหนึ่งเป็นอย่างไร', '["เท่ากับผลบวกทุกตัว","มากกว่าตัวที่ใหญ่ที่สุด","เท่ากับตัวที่เล็กที่สุด","น้อยกว่าตัวที่เล็กที่สุด"]', '3', 'ความต้านทานรวมของการต่อขนานจะน้อยกว่าความต้านทานที่น้อยที่สุดเสมอ เพราะมีช่องทางให้กระแสไหลได้หลายทาง', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel')), 'number', 'ต่อตัวต้านทาน 12 โอห์ม และ 4 โอห์ม แบบขนาน ความต้านทานรวมเท่ากับกี่โอห์ม (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', '1/Rรวม = 1/12 + 1/4 = 1/12 + 3/12 = 4/12 = 1/3 ดังนั้น Rรวม = 3 โอห์ม', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel')), 'number', 'แบตเตอรี่ 12 โวลต์ ต่อขนานกับตัวต้านทาน 4 โอห์ม และ 12 โอห์ม กระแสไฟฟ้ารวมที่ไหลจากแบตเตอรี่เท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 'Rรวม: 1/R = 1/4 + 1/12 = 4/12 จึง R = 3 โอห์ม แล้ว I = V/R = 12/3 = 4 แอมแปร์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circuits'), 'circuits-resistors-series', 'ตัวต้านทานต่ออนุกรม', 'การต่อตัวต้านทานแบบอนุกรม กระแสไฟฟ้าผ่านแต่ละตัวเท่ากัน และความต้านทานรวมเท่ากับผลบวกของความต้านทานทุกตัว ความต่างศักย์รวมเท่ากับผลบวกของความต่างศักย์แต่ละตัว', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-resistors-series'), 'youtube', 'https://www.youtube.com/watch?v=ucKBpVl8uBo', 'ucKBpVl8uBo', 'ฟิสิกส์ ม.5 บทที่ 14 ไฟฟ้ากระแส ep.3 (ตัวต้านทาน การต่อตัวต้านทานแบบอนุกรม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-resistors-series'), 'แบบทดสอบ: ตัวต้านทานต่ออนุกรม', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-series')), 'choice', 'กระแสไฟฟ้าที่ไหลผ่านตัวต้านทานแต่ละตัวที่ต่อกันแบบอนุกรม มีค่าเป็นอย่างไร', '["เท่ากันทุกตัว","ไม่แน่นอนขึ้นกับแบตเตอรี่","เป็นศูนย์","ต่างกันตามค่าความต้านทาน"]', '0', 'ในวงจรอนุกรมมีทางเดียวที่กระแสไหล กระแสจึงเท่ากันทุกจุดและทุกตัวต้านทาน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-series')), 'choice', 'ต่อตัวต้านทาน 4 โอห์ม และ 6 โอห์ม แบบอนุกรม ความต้านทานรวมเท่ากับกี่โอห์ม', '["24 โอห์ม","2.4 โอห์ม","10 โอห์ม","8 โอห์ม"]', '2', 'ความต้านทานรวมอนุกรม Rรวม = R₁ + R₂ = 4 + 6 = 10 โอห์ม', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-series')), 'choice', 'ความต่างศักย์รวมของวงจรอนุกรมที่ประกอบด้วยตัวต้านทานหลายตัว มีค่าเท่ากับอะไร', '["ความต่างศักย์ของตัวที่มากที่สุดเท่านั้น","ครึ่งหนึ่งของผลรวม","ผลต่างของความต่างศักย์แต่ละตัว","ผลรวมของความต่างศักย์คร่อมแต่ละตัว"]', '3', 'ในวงจรอนุกรม ความต่างศักย์รวม Vรวม = V₁ + V₂ + ... คือผลรวมของความต่างศักย์คร่อมตัวต้านทานแต่ละตัว', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-series')), 'number', 'ต่อตัวต้านทาน 2 โอห์ม, 3 โอห์ม และ 5 โอห์ม แบบอนุกรม เข้ากับแบตเตอรี่ ความต้านทานรวมเท่ากับกี่โอห์ม (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":10,"tolerance":0.5}', 'Rรวม = 2 + 3 + 5 = 10 โอห์ม', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-series')), 'number', 'แบตเตอรี่ 12 โวลต์ ต่ออนุกรมกับตัวต้านทาน 2 ตัวคือ 2 โอห์ม และ 4 โอห์ม กระแสไฟฟ้าในวงจรเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'Rรวม = 2 + 4 = 6 โอห์ม แล้ว I = V/R = 12/6 = 2 แอมแปร์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circular-motion'), 'circular-motion-angular-velocity', 'ความเร็วเชิงมุม คาบ และความถี่', 'การเคลื่อนที่แบบวงกลมสม่ำเสมอมีคาบ ความถี่ และความเร็วเชิงมุมคงตัว โดยความเร็วเชิงมุมสัมพันธ์กับคาบและความถี่', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity'), 'youtube', 'https://www.youtube.com/watch?v=1cY1UBryLGk', '1cY1UBryLGk', 'ฟิสิกส์ ม.4 บทที่ 7 การเคลื่อนที่แนวโค้ง ep.4 (การเคลื่อนที่แบบวงกลม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity'), 'แบบทดสอบ: ความเร็วเชิงมุม คาบ และความถี่', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity')), 'choice', 'ในการเคลื่อนที่แบบวงกลมสม่ำเสมอ ความเร็วเชิงมุม ω มีความสัมพันธ์กับคาบ T ตามข้อใด', '["ω = 2π/T","ω = 2πT","ω = T/2π","ω = T"]', '0', 'ในเวลาหนึ่งคาบวัตถุหมุนครบรอบ คิดเป็นมุม 2π เรเดียน ความเร็วเชิงมุมจึงเท่ากับ 2π/T', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity')), 'choice', 'ถ้าวัตถุหมุนครบ 1 รอบในเวลา 2 วินาที ความถี่ f ของการหมุนมีค่าเท่าใด', '["0.5 รอบต่อวินาที","2 รอบต่อวินาที","0.25 รอบต่อวินาที","4 รอบต่อวินาที"]', '0', 'ความถี่คือจำนวนรอบต่อหน่วยเวลา f = 1/T = 1/2 = 0.5 รอบต่อวินาที (เฮิรตซ์)', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity')), 'choice', 'อัตราเร็วเชิงเส้น v ที่ขอบของวัตถุที่หมุนด้วยความเร็วเชิงมุม ω และรัศมี r มีค่าตามข้อใด', '["v = ω/r","v = ωr","v = r/ω","v = 1/(ωr)"]', '1', 'อัตราเร็วเชิงเส้นสัมพันธ์กับความเร็วเชิงมุมด้วย v = ωr นั่นคือผลคูณของความเร็วเชิงมุมกับรัศมี', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity')), 'number', 'วงล้อหมุนครบ 200 รอบในเวลา 50 วินาที ความถี่การหมุนมีค่ากี่รอบต่อวินาที', NULL, '{"value":4,"tolerance":0.5}', 'ความถี่ f = จำนวนรอบ/เวลา = 200/50 = 4 รอบต่อวินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity')), 'number', 'วงล้อรัศมี 0.5 เมตร หมุนด้วยความเร็วเชิงมุม 4 เรเดียน/วินาที อัตราเร็วเชิงเส้นที่ขอบวงล้อมีค่ากี่เมตร/วินาที', NULL, '{"value":2,"tolerance":0.5}', 'v = ωr = 4 × 0.5 = 2 เมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circular-motion'), 'circular-motion-applications', 'ตัวอย่างประยุกต์การเคลื่อนที่วงกลม', 'การประยุกต์แรงสู่ศูนย์กลางในชีวิตจริง เช่น ถนนโค้งเอียงช่วยให้เลี้ยวปลอดภัย และลูกตุ้มกรวยที่แรงตึงเชือกให้แรงสู่ศูนย์กลาง', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-applications'), 'youtube', 'https://www.youtube.com/watch?v=bDC4CCDx4zg', 'bDC4CCDx4zg', 'ฟิสิกส์ ม.4 บทที่ 7 การเคลื่อนที่แนวโค้ง ep.6 (การเคลื่อนที่แบบวงกลม, การเลี้ยวโค้ง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-applications'), 'แบบทดสอบ: ตัวอย่างประยุกต์การเคลื่อนที่วงกลม', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-applications')), 'choice', 'ถนนโค้งที่ลาดเอียงเข้าหาใจกลางโค้งมีประโยชน์อย่างไร', '["ช่วยให้แรงปฏิกิริยาตั้งฉากมีองค์ประกอบที่ให้แรงสู่ศูนย์กลาง","ทำให้รถหยุดได้เร็วขึ้นเท่านั้น","ลดแรงโน้มถ่วงของรถ","ไม่ส่งผลต่อการเลี้ยว"]', '0', 'การเอียงถนนทำให้แรงปฏิกิริยาตั้งฉากมีองค์ประกอบพุ่งเข้าศูนย์กลาง ช่วยให้รถเลี้ยวโค้งได้โดยพึ่งแรงเสียดทานน้อยลง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-applications')), 'choice', 'ลูกตุ้มกรวยซึ่งเป็นวัตถุผูกเชือกแล้วหมุนเป็นวงกลมในแนวระนาบ แรงใดที่ให้แรงสู่ศูนย์กลาง', '["น้ำหนักของวัตถุ","แรงตึงเชือกที่มีองค์ประกอบพุ่งเข้าศูนย์กลาง","แรงเสียดทานระหว่างเชือกกับมือ","แรงลอยตัวในอากาศ"]', '1', 'แรงตึงเชือกเอียงทำมุมกับแนวตั้ง จึงมีองค์ประกอบในแนวราบพุ่งเข้าหาจุดศูนย์กลางของวงกลมทำหน้าที่เป็นแรงสู่ศูนย์กลาง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-applications')), 'choice', 'รถยนต์ในโค้งจะเป็นอันตรายที่สุดถ้าแรงเสียดทานที่ให้แรงสู่ศูนย์กลางไม่เพียงพอ ผลคืออย่างไร', '["รถหมุนออกนอกวิถีวงกลมตรง","รถหยุดนิ่งทันที","รถเร่งความเร็วขึ้น","รถลอยขึ้นจากถนนเสมอ"]', '2', 'เมื่อแรงเสียดทานให้แรงสู่ศูนย์กลางไม่พอ รถจะเคลื่อนออกนอกเส้นทางโค้งตามแนวเส้นสัมผัส จึงเกิดอุบัติเหตุได้', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-applications')), 'number', 'รถเลี้ยวโค้งรัศมี 20 เมตร ด้วยอัตราเร็ว 10 เมตร/วินาที ความเร่งสู่ศูนย์กลางของรถมีค่ากี่เมตร/วินาที²', NULL, '{"value":5,"tolerance":0.5}', 'a = v²/r = 10²/20 = 100/20 = 5 เมตร/วินาที²', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-applications')), 'number', 'ลูกตุ้มกรวยมวล 1 กิโลกรัม หมุนเป็นวงกลมรัศมี 1 เมตร ด้วยอัตราเร็ว 3 เมตร/วินาที แรงสู่ศูนย์กลางที่ต้องให้มีขนาดกี่นิวตัน', NULL, '{"value":9,"tolerance":0.5}', 'F = mv²/r = 1 × 3²/1 = 9 นิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circular-motion'), 'circular-motion-centripetal-acceleration', 'ความเร่งสู่ศูนย์กลาง', 'วัตถุที่เคลื่อนที่เป็นวงกลมสม่ำเสมอมีความเร่งพุ่งเข้าหาจุดศูนย์กลางเสมอ ขนาดเท่ากับ v²/r แม้อัตราเร็วคงที่เพราะทิศของความเร็วเปลี่ยนตลอดเวลา', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration'), 'youtube', 'https://www.youtube.com/watch?v=2WT7rGM57oo', '2WT7rGM57oo', 'ฟิสิกส์ ม.4 บทที่ 7 การเคลื่อนที่แนวโค้ง ep.5 (การเคลื่อนที่แบบวงกลม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration'), 'แบบทดสอบ: ความเร่งสู่ศูนย์กลาง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration')), 'choice', 'ทิศของความเร่งสู่ศูนย์กลางในการเคลื่อนที่แบบวงกลมสม่ำเสมอเป็นอย่างไร', '["พุ่งออกจากจุดศูนย์กลาง","พุ่งเข้าหาจุดศูนย์กลางเสมอ","ตามแนวเส้นสัมผัสวงกลม","ขึ้นกับทิศการหมุนเป็นกรณีไป"]', '1', 'ความเร่งสู่ศูนย์กลางมีทิศพุ่งเข้าหาจุดศูนย์กลางของวงกลมเสมอ เพราะต้องเปลี่ยนทิศของความเร็วให้โค้งตามวงกลม', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration')), 'choice', 'ความเร่งสู่ศูนย์กลาง a ของวัตถุที่เคลื่อนที่วงกลมรัศมี r ด้วยอัตราเร็ว v มีขนาดตามข้อใด', '["a = v/r","a = v²/r","a = vr","a = r/v²"]', '1', 'ขนาดความเร่งสู่ศูนย์กลางเท่ากับ v²/r ในวงกลมสม่ำเสมอขนาดจะคงที่แต่ทิศเปลี่ยนตลอดเวลา', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration')), 'choice', 'ถ้ารัศมีวงกลมเพิ่มขึ้นเป็น 2 เท่า โดยอัตราเร็ว v คงที่ ความเร่งสู่ศูนย์กลางจะเป็นเท่าใดของเดิม', '["เท่าเดิม","เป็น 2 เท่า","เป็นครึ่งหนึ่ง","เป็น 4 เท่า"]', '2', 'จาก a = v²/r เมื่อ r เพิ่มเป็น 2 เท่าและ v คงที่ ความเร่งจึงลดลงเป็นครึ่งหนึ่งของเดิม', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration')), 'number', 'วัตถุเคลื่อนที่เป็นวงกลมรัศมี 2 เมตร ด้วยอัตราเร็ว 4 เมตร/วินาที ความเร่งสู่ศูนย์กลางมีค่ากี่เมตร/วินาที²', NULL, '{"value":8,"tolerance":0.5}', 'a = v²/r = 4²/2 = 16/2 = 8 เมตร/วินาที²', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration')), 'number', 'รถคันหนึ่งวิ่งเป็นวงกลมรัศมี 10 เมตร ด้วยอัตราเร็ว 5 เมตร/วินาที ความเร่งสู่ศูนย์กลางมีค่ากี่เมตร/วินาที² (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":2.5,"tolerance":0.05}', 'a = v²/r = 5²/10 = 25/10 = 2.5 เมตร/วินาที²', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circular-motion'), 'circular-motion-centripetal-force', 'แรงสู่ศูนย์กลาง', 'แรงลัพธ์ที่ทำให้วัตถุเคลื่อนที่เป็นวงกลมเรียกว่าแรงสู่ศูนย์กลาง มีทิศเข้าหาจุดศูนย์กลาง ขนาดเท่ากับ mv²/r โดยอาจมาจากแรงดึงเชือก แรงเสียดทาน หรือแรงโน้มถ่วงแล้วแต่สถานการณ์', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force'), 'youtube', 'https://www.youtube.com/watch?v=2WT7rGM57oo', '2WT7rGM57oo', 'ฟิสิกส์ ม.4 บทที่ 7 การเคลื่อนที่แนวโค้ง ep.5 (การเคลื่อนที่แบบวงกลม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force'), 'แบบทดสอบ: แรงสู่ศูนย์กลาง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force')), 'choice', 'แรงสู่ศูนย์กลางที่กระทำต่อวัตถุเคลื่อนที่วงกลมรัศมี r อัตราเร็ว v มวล m มีขนาดตามข้อใด', '["F = m v r","F = m v² / r","F = m r / v","F = m v / r"]', '1', 'แรงสู่ศูนย์กลาง F = mv²/r หรือเทียบเท่า mω²r โดยเป็นแรงที่ทำให้วัตถุเปลี่ยนทิศเข้าหาจุดศูนย์กลาง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force')), 'choice', 'การเคลื่อนที่แบบวงกลม แรงสู่ศูนย์กลางเป็นแรงชนิดใด', '["แรงชนิดใหม่พิเศษที่เกิดแค่ในการหมุน","แรงลัพธ์ที่พุ่งเข้าหาจุดศูนย์กลาง","แรงที่พุ่งออกจากศูนย์กลางเสมอ","แรงโน้มถ่วงเท่านั้น"]', '1', 'แรงสู่ศูนย์กลางไม่ใช่แรงชนิดใหม่ แต่คือแรงลัพธ์ที่พุ่งเข้าหาจุดศูนย์กลาง อาจมาจากแรงจริงชนิดใดก็ได้ตามสถานการณ์', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force')), 'choice', 'ทิศของแรงสู่ศูนย์กลางที่ต้องกระทำต่อวัตถุที่หมุนเป็นวงกลมเป็นอย่างไร', '["พุ่งออกจากศูนย์กลาง","ตามแนวเส้นสัมผัส","พุ่งเข้าหาจุดศูนย์กลาง","เฉียง 45 องศาเข้าหาศูนย์กลาง"]', '2', 'แรงสู่ศูนย์กลางมีทิศเข้าหาจุดศูนย์กลางเสมอ เพื่อให้ความเร่งเข้าหาศูนย์กลางและวัตถุเคลื่อนที่ตามวิถีวงกลม', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force')), 'number', 'วัตถุมวล 2 กิโลกรัม เคลื่อนที่วงกลมรัศมี 3 เมตร ด้วยอัตราเร็ว 6 เมตร/วินาที แรงสู่ศูนย์กลางมีขนาดกี่นิวตัน', NULL, '{"value":24,"tolerance":0.5}', 'F = mv²/r = 2 × 6²/3 = 2 × 36/3 = 24 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force')), 'number', 'วัตถุมวล 0.5 กิโลกรัม เคลื่อนที่วงกลมรัศมี 2 เมตร ด้วยอัตราเร็ว 4 เมตร/วินาที แรงสู่ศูนย์กลางมีขนาดกี่นิวตัน', NULL, '{"value":4,"tolerance":0.5}', 'F = mv²/r = 0.5 × 4²/2 = 0.5 × 16/2 = 4 นิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'momentum-collisions'), 'collision-elastic', 'การชนแบบยืดหยุ่น', 'การชนแบบยืดหยุ่นสมบูรณ์พลังงานจลน์รวมคงที่ โมเมนตัมรวมคงที่ และมวลเท่ากันจะแลกความเร็วกัน', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'collision-elastic'), 'youtube', 'https://www.youtube.com/watch?v=AIpDktoEgVc', 'AIpDktoEgVc', 'ฟิสิกส์ ม.4 บทที่ 6 โมเมนตัมและการชน ep.5(การชนแบบยืดหยุ่น, การชนแบบไม่ยืดหยุ่น)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'collision-elastic'), 'youtube', 'https://www.youtube.com/watch?v=WSmiSrPYGnA', 'WSmiSrPYGnA', 'ฟิสิกส์ ม.4 บทที่ 6 โมเมนตัมและการชน ep.4 (การชน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'collision-elastic'), 'แบบทดสอบ: การชนแบบยืดหยุ่น', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'collision-elastic')), 'choice', 'การชนแบบยืดหยุ่นสมบูรณ์มีลักษณะสำคัญอย่างไร', '["พลังงานจลน์รวมคงที่ และโมเมนตัมรวมคงที่","วัตถุติดกันหลังชน","พลังงานจลน์บางส่วนกลายเป็นความร้อน","โมเมนตัมรวมไม่คงที่"]', '0', 'การชนยืดหยุ่นสมบูรณ์ ทั้งพลังงานจลน์รวมและโมเมนตัมรวมคงที่ ไม่มีการสูญเสียพลังงาน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'collision-elastic')), 'choice', 'วัตถุมวลเท่ากันสองก้อน ชนกันแบบยืดหยุ่นสมบูรณ์ในแนวตรง หลังชนเป็นอย่างไร (ก้อนหนึ่งวิ่งมาก่อน อีกก้อนนิ่ง)', '["ทั้งสองติดกันเคลื่อนที่ต่อไป","ก้อนที่วิ่งมาหยุด และก้อนที่นิ่งวิ่งต่อด้วยความเร็วเท่ากับความเร็วต้นของก้อนแรก","ทั้งสองหยุดนิ่ง","ก้อนแรกเด้งกลับไปทิศเดิม"]', '1', 'เมื่อมวลเท่ากันชนยืดหยุ่นสมบูรณ์ในแนวตรง ก้อนแรกจะแลกความเร็วให้ก้อนที่นิ่ง จึงหยุดเอง และก้อนที่นิ่งวิ่งต่อด้วยความเร็วเดิม', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'collision-elastic')), 'choice', 'ในการชนแบบยืดหยุ่นสมบูรณ์ ข้อใดถูกต้องเสมอ', '["โมเมนตัมรวมก่อนชนเท่ากับโมเมนตัมรวมหลังชน","พลังงานจลน์รวมเพิ่มขึ้น","ความเร็วของวัตถุไม่เปลี่ยนแปลง","มีแรงเสียดทานมากระทำ"]', '1', 'ตลอดการชน โมเมนตัมรวมอนุรักษ์เสมอ พลังงานจลน์ก็คงที่ด้วยในกรณียืดหยุ่นสมบูรณ์', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'collision-elastic')), 'number', 'วัตถุมวล 1 กิโลกรัม วิ่งด้วยความเร็ว 6 เมตร/วินาที ไปชนวัตถุมวล 1 กิโลกรัมที่หยุดนิ่ง แบบยืดหยุ่นสมบูรณ์ในแนวตรง ความเร็วของวัตถุที่เดิมนิ่งหลังชนมีค่ากี่เมตร/วินาที', NULL, '{"value":6,"tolerance":0.5}', 'มวลเท่ากันชนยืดหยุ่นสมบูรณ์ แลกความเร็วกัน วัตถุที่เดิมนิ่งจึงวิ่งต่อด้วยความเร็ว 6 เมตร/วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'collision-elastic')), 'number', 'วัตถุมวล 2 กิโลกรัม วิ่งด้วยความเร็ว 4 เมตร/วินาที ชนวัตถุมวล 2 กิโลกรัมที่หยุดนิ่ง แบบยืดหยุ่นสมบูรณ์ในแนวตรง ความเร็วของวัตถุที่เดิมนิ่งหลังชนมีค่ากี่เมตร/วินาที', NULL, '{"value":4,"tolerance":0.5}', 'มวลเท่ากันชนยืดหยุ่นสมบูรณ์แลกความเร็วกัน วัตถุที่เดิมนิ่งจึงวิ่งด้วยความเร็ว 4 เมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'momentum-collisions'), 'collision-inelastic', 'การชนแบบไม่ยืดหยุ่น', 'การชนแบบไม่ยืดหยุ่นสมบูรณ์วัตถุติดกันหลังชน พลังงานจลน์บางส่วนสูญหายแต่โมเมนตัมรวมยังคงที่', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'collision-inelastic'), 'youtube', 'https://www.youtube.com/watch?v=AIpDktoEgVc', 'AIpDktoEgVc', 'ฟิสิกส์ ม.4 บทที่ 6 โมเมนตัมและการชน ep.5(การชนแบบยืดหยุ่น, การชนแบบไม่ยืดหยุ่น)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'collision-inelastic'), 'แบบทดสอบ: การชนแบบไม่ยืดหยุ่น', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'collision-inelastic')), 'choice', 'การชนแบบไม่ยืดหยุ่นสมบูรณ์มีลักษณะสำคัญอย่างไร', '["วัตถุติดกันไปด้วยกันหลังชนและพลังงานจลน์บางส่วนสูญหาย","พลังงานจลน์รวมคงที่","วัตถุแยกกันโดยไม่ติดกัน","โมเมนตัมรวมไม่คงที่"]', '0', 'การชนไม่ยืดหยุ่นสมบูรณ์ วัตถุจะติดกันหลังชน มีพลังงานจลน์บางส่วนเปลี่ยนไปเป็นพลังงานรูปอื่น แต่โมเมนตัมรวมคงที่', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'collision-inelastic')), 'choice', 'ในการชนแบบไม่ยืดหยุ่น ปริมาณใดที่ยังอนุรักษ์อยู่', '["พลังงานจลน์รวม","โมเมนตัมรวม","พลังงานศักย์","ความเร็วทุกด้าน"]', '1', 'โมเมนตัมรวมอนุรักษ์เสมอในการชน แต่พลังงานจลน์รวมอาจลดลงในการชนแบบไม่ยืดหยุ่น', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'collision-inelastic')), 'choice', 'พลังงานจลน์ที่หายไปในการชนแบบไม่ยืดหยุ่นเปลี่ยนไปเป็นพลังงานรูปใดเป็นหลัก', '["พลังงานจลน์เพิ่มขึ้น","ความร้อน เสียง และการเปลี่ยนรูปถาวร","พลังงานนิวเคลียร์","พลังงานแม่เหล็ก"]', '1', 'พลังงานจลน์บางส่วนกลายเป็นความร้อน เสียง และพลังงานที่ทำให้วัตถุผิดรูปถาวร จึงถือว่าสูญหายจากพลังงานกล', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'collision-inelastic')), 'number', 'วัตถุมวล 2 กิโลกรัม วิ่งด้วยความเร็ว 5 เมตร/วินาที ไปชนวัตถุมวล 3 กิโลกรัมที่หยุดนิ่ง แล้วติดกันไปด้วยกัน ความเร็วหลังชนมีค่ากี่เมตร/วินาที', NULL, '{"value":2,"tolerance":0.5}', 'โมเมนตัมรวมอนุรักษ์ m1v1 = (m1+m2)v'' ได้ v'' = 2×5/(2+3) = 10/5 = 2 เมตร/วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'collision-inelastic')), 'number', 'วัตถุมวล 4 กิโลกรัม วิ่งด้วยความเร็ว 6 เมตร/วินาที ไปชนวัตถุมวล 2 กิโลกรัมที่หยุดนิ่ง แล้วติดกัน ความเร็วหลังชนมีค่ากี่เมตร/วินาที', NULL, '{"value":4,"tolerance":0.5}', 'm1v1 = (m1+m2)v'' ได้ v'' = 4×6/(4+2) = 24/6 = 4 เมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'momentum-collisions'), 'collision-recoil', 'การระเบิดและการถอยหลัง', 'การระเบิดและการถอยหลังเป็นผลของกฎการอนุรักษ์โมเมนตัม วัตถุแยกออกหลายชิ้นโดยผลรวมโมเมนตัมก่อนและหลังเท่ากัน วัตถุเริ่มนิ่งแล้วแยก ทิศก็สวนกัน', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'collision-recoil'), 'youtube', 'https://www.youtube.com/watch?v=LeXPLcFG-74', 'LeXPLcFG-74', 'ฟิสิกส์ ม.4 บทที่ 6 โมเมนตัมและการชน ep.6(การชน กฎการอนุรักษ์โมเมนตัม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'collision-recoil'), 'แบบทดสอบ: การระเบิดและการถอยหลัง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'collision-recoil')), 'choice', 'วัตถุระเบิดที่เดิมนิ่ง แยกเป็น 2 ชิ้น โมเมนตัมของทั้งสองชิ้นหลังระเบิดสัมพันธ์กันอย่างไร', '["ขนาดเท่ากัน ทิศเดียวกัน","ขนาดเท่ากัน ทิศตรงข้ามกัน","ขนาดไม่เท่ากัน ทิศเดียวกัน","ไม่มีความสัมพันธ์"]', '1', 'เดิมโมเมนตัมรวมเป็นศูนย์ หลังระเบิดต้องรวมเป็นศูนย์ ชิ้นทั้งสองจึงมีโมเมนตัมขนาดเท่ากันและทิศตรงข้าม', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'collision-recoil')), 'choice', 'ปืนยิงกระสุนออกไป มือที่ถือปืนรู้สึกได้ถึงแรงถอยหลัง เพราะเหตุใด', '["แรงโน้มถ่วงดึงปืน","โมเมนตัมของปืนมีขนาดเท่ากับของกระสุนแต่ทิศตรงข้าม","อากาศดันปืน","กระสุนดูดปืน"]', '1', 'โมเมนตัมรวมก่อนยิงเป็นศูนย์หลังยิงปืนและกระสุนต้องรวมเป็นศูนย์ ปืนจึงถอยหลังด้วยโมเมนตัมเท่ากระสุนแต่ทิศตรงข้าม', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'collision-recoil')), 'choice', 'มวลยิ่งมาก ถ้าโมเมนตัมของชิ้นเดียวกันเท่ากัน ชิ้นนั้นจะมีความเร็วอย่างไร', '["ยิ่งน้อย","ยิ่งมาก","เท่าเดิมเสมอ","เป็นศูนย์"]', '2', 'จาก p = mv ถ้ามวลมากโดยโมเมนตัมเท่าเดิม ความเร็วจะน้อยลง จึงเป็นเหตุให้ปืนหนักถอยหลังช้ากว่ากระสุนเบา', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'collision-recoil')), 'number', 'ปืนมวล 3 กิโลกรัม ยิงกระสุนมวล 0.02 กิโลกรัม ออกไปด้วยความเร็ว 300 เมตร/วินาที ปืนถอยหลังด้วยความเร็วกี่เมตร/วินาที', NULL, '{"value":2,"tolerance":0.5}', 'อนุรักษ์โมเมนตัม m_b v_b = m_p v_p ได้ v_p = 0.02×300/3 = 6/3 = 2 เมตร/วินาที ทิศตรงข้ามกระสุน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'collision-recoil')), 'number', 'ระเบิดที่เดิมนิ่งแตกเป็นสองชิ้น ชิ้น A มวล 2 กิโลกรัม วิ่งด้วยความเร็ว 6 เมตร/วินาที ชิ้น B มวล 4 กิโลกรัม วิ่งด้วยความเร็วกี่เมตร/วินาที (ทิศตรงข้ามกัน)', NULL, '{"value":3,"tolerance":0.5}', 'm_A v_A = m_B v_B ได้ v_B = 2×6/4 = 12/4 = 3 เมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'electrostatics'), 'coulomb-law', 'กฎของคูลอมบ์: แรงระหว่างประจุไฟฟ้า', 'แรงระหว่างประจุจุดสองประจุแปรผันตามผลคูณของขนาดประจุ และแปรผกผันกับกำลังสองของระยะห่าง', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'coulomb-law'), 'youtube', 'https://www.youtube.com/watch?v=u0nVk4FLAz8', 'u0nVk4FLAz8', 'ฟิสิกส์ ม.5 บทที่ 13 ไฟฟ้าสถิต ep.2 (แรงไฟฟ้าและกฎของคูลอมบ์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'coulomb-law'), 'coulomb', 'ปรับประจุและระยะห่าง แล้วดูแรง', '{}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'coulomb-law'), 'แบบทดสอบ: กฎของคูลอมบ์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'coulomb-law')), 'choice', 'ถ้าระยะห่างระหว่างประจุสองประจุเพิ่มขึ้นเป็น 2 เท่า แรงระหว่างประจุเปลี่ยนเป็นกี่เท่าของเดิม', '["2 เท่า","1/2 เท่า","4 เท่า","1/4 เท่า"]', '3', 'แรงแปรผกผันกับกำลังสองของระยะห่าง F ∝ 1/r² เมื่อ r เป็น 2 เท่า F จึงเป็น 1/4 เท่า', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'coulomb-law')), 'choice', 'ประจุ +2 ไมโครคูลอมบ์ กับ −3 ไมโครคูลอมบ์ วางห่างกัน แรงระหว่างประจุเป็นแบบใด', '["ผลักกัน","ดึงดูดกัน","ไม่มีแรง","ผลักกันที่ระยะใกล้ ดึงดูดที่ระยะไกล"]', '1', 'ประจุต่างชนิดกันดึงดูดกัน ประจุชนิดเดียวกันผลักกัน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'coulomb-law')), 'number', 'ประจุ 2 ไมโครคูลอมบ์ สองประจุ วางห่างกัน 0.3 เมตร ในสุญญากาศ แรงระหว่างประจุมีขนาดกี่นิวตัน (ใช้ k = 9 × 10⁹ นิวตัน·เมตร²/คูลอมบ์²)', NULL, '{"value":0.4,"tolerance":0.01}', 'F = k q1 q2 / r² = 9×10⁹ × (2×10⁻⁶)² / 0.3² = 0.036 / 0.09 = 0.4 นิวตัน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'coulomb-law')), 'choice', 'ถ้าเพิ่มประจุตัวหนึ่งเป็น 3 เท่า โดยระยะห่างเท่าเดิม แรงระหว่างประจุเป็นกี่เท่าของเดิม', '["3 เท่า","9 เท่า","1/3 เท่า","เท่าเดิม"]', '0', 'แรงแปรผันตรงกับผลคูณของประจุ F ∝ q1 q2 เมื่อประจุหนึ่งเป็น 3 เท่า แรงจึงเป็น 3 เท่า', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'coulomb-law')), 'choice', 'แรงที่ประจุ A กระทำต่อประจุ B กับแรงที่ B กระทำต่อ A มีความสัมพันธ์กันอย่างไร', '["ขนาดไม่เท่ากัน","ขนาดเท่ากัน ทิศตรงข้ามกัน","ขนาดเท่ากัน ทิศเดียวกัน","ขึ้นกับขนาดของประจุที่มากกว่า"]', '1', 'เป็นแรงคู่กิริยา-ปฏิกิริยาตามกฎข้อที่ 3 ของนิวตัน ขนาดเท่ากันและทิศตรงข้าม', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'electrostatics'), 'electrostatics-capacitor', 'ตัวเก็บประจุ', 'ตัวเก็บประจุเก็บประจุไฟฟ้าได้โดยอาศัยความต่างศักย์ระหว่างแผ่นนำไฟฟ้า ความจุคำนวณได้จาก C = Q/V และเมื่อต่ออนุกรมความจุรวมลดลง แต่เมื่อต่อขนานความจุรวมเพิ่มขึ้น', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-capacitor'), 'youtube', 'https://www.youtube.com/watch?v=w6Mm1uvSzmk', 'w6Mm1uvSzmk', 'ฟิสิกส์ ม.5 บทที่ 13 ไฟฟ้าสถิต ep.8(ตัวเก็บประจุและการต่อตัวเก็บประจุแบบอนุกรม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-capacitor'), 'youtube', 'https://www.youtube.com/watch?v=Jb67ht00wco', 'Jb67ht00wco', 'ฟิสิกส์ ม.5 บทที่ 13 ไฟฟ้าสถิต ep.9 (การต่อตัวเก็บประจุแบบขนาน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-capacitor'), 'แบบทดสอบ: ตัวเก็บประจุ', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-capacitor')), 'choice', 'ความจุไฟฟ้า C ของตัวเก็บประจุ นิยามด้วยสูตรใด', '["C = V/Q","C = Q/V","C = ½QV","C = QV"]', '1', 'ความจุ C = Q/V โดย Q คือประจุที่เก็บได้และ V คือความต่างศักย์ระหว่างแผ่น หน่วยฟารัด C = ½QV คือสูตรพลังงานสะสมในตัวเก็บประจุ ไม่ใช่ความจุ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-capacitor')), 'choice', 'ต่อตัวเก็บประจุความจุเท่ากัน 2 ตัวแบบอนุกรม ความจุรวมจะต่างจากตัวเก็บประจุตัวเดียวอย่างไร', '["ค่าเป็น 2 เท่า","ค่าเป็น 4 เท่า","ค่าน้อยลง","ค่าเท่าเดิม"]', '2', 'การต่ออนุกรม ความจุรวม 1/C = 1/C₁ + 1/C₂ เมื่อ C₁ = C₂ = C จะได้ Cรวม = C/2 จึงน้อยกว่าตัวเดี่ยว ส่วนการต่อขนานความจุรวมจะมากกว่า', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-capacitor')), 'choice', 'การต่อตัวเก็บประจุแบบใดที่ทำให้ความจุรวมมีค่าเท่ากับผลบวกของความจุแต่ละตัว', '["ต่อแบบผสมแล้วใส่ฉนวน","ไม่มีวิธีใด","ต่ออนุกรม","ต่อขนาน"]', '3', 'เมื่อต่อขนาน ประจุรวม Q = Q₁ + Q₂ และความต่างศักย์เท่ากัน จึง Cรวม = C₁ + C₂ หรือเท่ากับผลบวกความจุแต่ละตัว', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-capacitor')), 'number', 'ตัวเก็บประจุความจุ 20 ไมโครฟารัด ต่อกับความต่างศักย์ 12 โวลต์ ประจุที่สะสมบนแผ่นตัวนำเป็นกี่ไมโครคูลอมบ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":240,"tolerance":0.5}', 'Q = CV = 20 × 12 = 240 ไมโครคูลอมบ์ ใช้หน่วยไมโครตรงกัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-capacitor')), 'number', 'ตัวเก็บประจุความจุ 10 ไมโครฟารัด ต่อกับความต่างศักย์ 6 โวลต์ ประจุที่สะสมเป็นกี่ไมโครคูลอมบ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":60,"tolerance":0.5}', 'Q = CV = 10 × 6 = 60 ไมโครคูลอมบ์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'electrostatics'), 'electrostatics-charge-electrification', 'ประจุไฟฟ้าและการทำให้เป็นไฟฟ้า', 'ประจุไฟฟ้ามีสองชนิดคือประจุบวกและประจุลบ วัตถุที่ไม่มีประจุสุทธิเรียกว่าเป็นกลาง และประจุจะถ่ายโอนได้ด้วยการเสียดสี การสัมผัส และการเหนี่ยวนำ โดยประจุสุทธิทั้งหมดถูกรักษาไว้เสมอ', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-charge-electrification'), 'youtube', 'https://www.youtube.com/watch?v=KWRoq4zckv4', 'KWRoq4zckv4', 'ฟิสิกส์ ม.5 บทที่ 13 ไฟฟ้าสถิต ep.1(การเสียดสีและการเหนี่ยวนำทางไฟฟ้า)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-charge-electrification'), 'แบบทดสอบ: ประจุไฟฟ้าและการทำให้เป็นไฟฟ้า', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-electrification')), 'choice', 'การทำให้แท่งแก้วเป็นไฟฟ้าด้วยการถูด้วยผ้าไหม เกิดจากกระบวนการใดเป็นหลัก', '["อิเล็กตรอนเคลื่อนที่จากแก้วไปยังผ้าไหม","โปรตอนเคลื่อนที่จากผ้าไหมไปยังแก้ว","นิวตรอนถูกสร้างขึ้นใหม่ที่ผิวแก้ว","ประจุบวกถูกสร้างขึ้นจากความร้อนของการถู"]', '0', 'การถูทำให้อิเล็กตรอน (ประจุลบ) เคลื่อนที่ระหว่างวัตถุ แก้วเสียอิเล็กตรอนจึงมีประจุบวก ส่วนโปรตอนยึดแน่นในนิวเคลียสไม่เคลื่อนที่ วัตถุที่เป็นกลางเกิดประจุได้จากการถ่ายโอนอิเล็กตรอน ไม่ใช่การสร้างประจุใหม่', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-electrification')), 'choice', 'วิธีใดทำให้วัตถุมีประจุโดยไม่ต้องสัมผัสกับวัตถุที่มีประจุโดยตรง', '["การเสียดสี","การเหนี่ยวนำ","การสัมผัส","การละลาย"]', '1', 'การเหนี่ยวนำทำให้ประจุในตัวนำถูกจัดเรียงใหม่เมื่อมีประจุภายนอกมาใกล้ โดยไม่มีการสัมผัส เมื่อต่อลงดินแล้วถอนสายดิน ตัวนำจะเหลือประจุสุทธิ ส่วนการเสียดสีและสัมผัสต้องมีการถ่ายโอนประจุโดยตรง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-electrification')), 'choice', 'วัตถุ A มีประจุ +3 ไมโครคูลอมบ์ วัตถุ B มีประจุ −5 ไมโครคูลอมบ์ นำทั้งสองมาสัมผัสกันแล้วแยกออกจากกัน แต่ละวัตถุจะมีประจุเท่าใด', '["+3 และ −5 ไมโครคูลอมบ์","+4 และ −4 ไมโครคูลอมบ์","−1 และ −1 ไมโครคูลอมบ์","0 และ −2 ไมโครคูลอมบ์"]', '2', 'เมื่อนำตัวนำสองอันมาสัมผัสกัน ประจุรวม = +3 + (−5) = −2 ไมโครคูลอมบ์ จะกระจายเท่าๆ กัน แล้วแต่ละอันได้ −1 ไมโครคูลอมบ์ ตามหลักการอนุรักษ์ประจุ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-electrification')), 'number', 'แท่งวัตถุหนึ่งสูญเสียอิเล็กตรอนไป ทำให้มีประจุสุทธิ 8 ไมโครคูลอมบ์ ถ้าประจุอิเล็กตรอนหนึ่งตัวคือ 1.6 คูณ 10 ยกกำลัง −19 คูลอมบ์ (เขียนเป็น 0.00000000000000000016 คูลอมบ์) จำนวนอิเล็กตรอนที่สูญเสียเป็นกี่ล้านล้านตัว (สูตร n = Q หารประจุต่อตัว ตอบเป็นจำนวนเต็ม)', NULL, '{"value":50,"tolerance":0.5}', 'n = Q/e = 0.000008/0.00000000000000000016 = 50000000000000 ตัว = 50 ล้านล้านตัว', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-electrification')), 'number', 'วัตถุ A มีประจุ +6 ไมโครคูลอมบ์ วัตถุ B ไม่มีประจุ นำ A สัมผัสกับ B แล้วแยกออกจากกัน A จะมีประจุกี่ไมโครคูลอมบ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'ประจุรวมก่อนสัมผัส = +6 ไมโครคูลอมบ์ เมื่อตัวนำเท่ากันสัมผัสกัน ประจุจะกระจายเท่าๆ กัน A จึงเหลือครึ่งหนึ่ง คือ 3 ไมโครคูลอมบ์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'electrostatics'), 'electrostatics-charge-motion-uniform-field', 'การเคลื่อนที่ของประจุในสนามไฟฟ้าสม่ำเสมอ', 'ประจุที่เคลื่อนที่ในสนามไฟฟ้าสม่ำเสมอได้รับแรงคงตัว F = qE ทำให้มีความเร่งคงที่ คล้ายการเคลื่อนที่แบบมีแรงโน้มถ่วง จึงวิเคราะห์การเคลื่อนที่ในแนวขนานและแนวตั้งฉากกับสนามได้แยกกัน', 'senior', 6, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field'), 'youtube', 'https://www.youtube.com/watch?v=xM8_XG37xqY', 'xM8_XG37xqY', 'ฟิสิกส์ ม.5 บทที่ 13 ไฟฟ้าสถิต ep.5 (สนามไฟฟ้า)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field'), 'แบบทดสอบ: การเคลื่อนที่ของประจุในสนามไฟฟ้าสม่ำเสมอ', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field')), 'choice', 'โปรตอนวางนิ่งในสนามไฟฟ้าสม่ำเสมอ ทิศของแรงที่กระทำต่อโปรตอนเป็นอย่างไร', '["ทิศเดียวกับสนามไฟฟ้า","ทิศตรงข้ามกับสนามไฟฟ้า","ตั้งฉากกับสนามไฟฟ้า","ไม่มีแรงกระทำ"]', '0', 'F = qE โปรตอนมีประจุบวก จึงมีแรงทิศเดียวกับสนามไฟฟ้า ส่วนอิเล็กตรอน (ประจุลบ) จะได้แรงทิศตรงข้ามสนาม', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field')), 'choice', 'ประจุประจุหนึ่งเคลื่อนที่เข้าไปในสนามไฟฟ้าสม่ำเสมอในทิศตั้งฉากกับสนาม วิถีการเคลื่อนที่ของประจุจะเป็นแนวใด (ไม่คิดแรงโน้มถ่วง)', '["เส้นตรงแนวตั้งฉาก","เส้นโค้งคล้ายพาราโบลา","วงกลม","เส้นตรงแนวนอน"]', '1', 'ในทิศตั้งฉากกับสนามประจุไม่มีความเร่ง ส่วนทิศตามสนามมีแรงคงตัวและความเร่งคงที่ คล้ายการเคลื่อนที่แบบโพรเจกไทล์ จึงได้วิถีพาราโบลา', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field')), 'choice', 'ประจุประจุหนึ่งวางนิ่งอยู่ในสนามไฟฟ้าสม่ำเสมอ ความเร่งของประจุขึ้นกับปริมาณใด', '["มวลคูณสนาม (mE)","ระยะทางคูณสนาม","เฉพาะสนามไฟฟ้าเท่านั้น","ประจุคูณสนามหารด้วยมวล (qE/m)"]', '3', 'จาก F = qE = ma จะได้ความเร่ง a = qE/m จึงขึ้นกับขนาดประจุ ขนาดสนาม และมวลของประจุ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field')), 'number', 'ประจุ 3 ไมโครคูลอมบ์ วางในสนามไฟฟ้าสม่ำเสมอ 5000 นิวตัน/คูลอมบ์ แรงที่กระทำต่อประจุมีขนาดกี่นิวตัน (ตอบเป็นทศนิยม 3 ตำแหน่ง)', NULL, '{"value":0.015,"tolerance":0.005}', 'F = qE = 0.000003 × 5000 = 0.015 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field')), 'number', 'สนามไฟฟ้าสม่ำเสมอ 1000 นิวตัน/คูลอมบ์ ประจุ 2 ไมโครคูลอมบ์ แรงที่กระทำต่อประจุมีขนาดกี่นิวตัน (ตอบเป็นทศนิยม 3 ตำแหน่ง)', NULL, '{"value":0.002,"tolerance":0.0005}', 'F = qE = 0.000002 × 1000 = 0.002 นิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'electrostatics'), 'electrostatics-electric-field', 'สนามไฟฟ้า', 'สนามไฟฟ้าคือบริเวณโดยรอบประจุที่แรงไฟฟ้ากระทำต่อประจุทดสอบ ความเข้มสนามไฟฟ้าคำนวณได้จาก E = F/q และ E = kQ/r²', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-electric-field'), 'youtube', 'https://www.youtube.com/watch?v=J8Q9uyJaMNc', 'J8Q9uyJaMNc', 'ฟิสิกส์ ม.5 บทที่ 13 ไฟฟ้าสถิต ep.4 (สนามไฟฟ้า)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-electric-field'), 'youtube', 'https://www.youtube.com/watch?v=xM8_XG37xqY', 'xM8_XG37xqY', 'ฟิสิกส์ ม.5 บทที่ 13 ไฟฟ้าสถิต ep.5 (สนามไฟฟ้า)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-electric-field'), 'แบบทดสอบ: สนามไฟฟ้า', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-electric-field')), 'choice', 'ความเข้มสนามไฟฟ้าที่จุดหนึ่งกำหนดได้ด้วยสูตรใด เมื่อมีประจุทดสอบ q วางที่จุดนั้นและมีแรง F กระทำ', '["E = F/q","E = qF","E = kQ²/r","E = ½mv²"]', '0', 'ความเข้มสนามไฟฟ้า E เท่ากับแรงไฟฟ้าที่กระทำต่อประจุทดสอบหารด้วยขนาดประจุทดสอบ คือ E = F/q หน่วยนิวตัน/คูลอมบ์ หรือโวลต์/เมตร ตัวเลือกอื่นเป็นสูตรความเร็วหรือพลังงาน จึงไม่ถูกต้อง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-electric-field')), 'choice', 'ประจุจุด Q เป็นประจุบวก ความเข้มสนามไฟฟ้าที่จุดห่างจาก Q ออกไปจะชี้ในทิศใด', '["เป็นศูนย์เสมอ","เข้าหาประจุ Q","พุ่งออกจากประจุ Q","ตั้งฉากกับเส้นเชื่อมประจุ"]', '2', 'สนามไฟฟ้าจากประจุบวกชี้พุ่งออกจากประจุ ตามทิศแรงที่กระทำต่อประจุทดสอบบวก ส่วนสนามจากประจุลบจะชี้เข้าหาประจุ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-electric-field')), 'choice', 'ถ้าระยะทางจากประจุจุดเพิ่มขึ้นเป็น 2 เท่า ความเข้มสนามไฟฟ้าจะเปลี่ยนเป็นกี่เท่าของเดิม', '["2 เท่า","1/2 เท่า","4 เท่า","1/4 เท่า"]', '3', 'E = kQ/r² เข้มสนามไฟฟ้าแปรผกผันกับกำลังสองของระยะทาง เมื่อ r เป็น 2 เท่า E จึงเป็น 1/4 เท่า', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-electric-field')), 'number', 'ประจุจุด 1 ไมโครคูลอมบ์ และประจุจุด 2 ไมโครคูลอมบ์ วางห่างกัน 0.3 เมตร แรงคูลอมบ์ระหว่างประจุ 0.2 นิวตัน ความเข้มสนามไฟฟ้าที่ตำแหน่งของประจุขนาด 2 ไมโครคูลอมบ์ เท่ากับกี่นิวตัน/คูลอมบ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":100000,"tolerance":500}', 'E = F/q = 0.2 / 0.000002 = 100000 นิวตัน/คูลอมบ์ แปลง 2 ไมโครคูลอมบ์เป็นคูลอมบ์ก่อนแทนค่า', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-electric-field')), 'number', 'ความเข้มสนามไฟฟ้าที่จุดหนึ่งจากประจุ 2 ไมโครคูลอมบ์ เป็น 50000 นิวตัน/คูลอมบ์ ถ้าเพิ่มประจุเป็น 6 ไมโครคูลอมบ์ ที่จุดเดิมความเข้มสนามไฟฟ้าเป็นกี่นิวตัน/คูลอมบ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":150000,"tolerance":500}', 'E แปรผันตรงกับประจุ 6/2 = 3 เท่า จึงเป็น 3 × 50000 = 150000 นิวตัน/คูลอมบ์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'electrostatics'), 'electrostatics-electric-potential', 'ศักย์ไฟฟ้าและพลังงานศักย์ไฟฟ้า', 'ศักย์ไฟฟ้าที่จุดใดคืองานที่ใช้เคลื่อนประจุหนึ่งหน่วยจากจุดอ้างอิงมาที่จุดนั้น พลังงานศักย์ไฟฟ้าคำนวณได้จากผลคูณของประจุกับศักย์ไฟฟ้า และงานเท่ากับประจุคูณความต่างศักย์', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-electric-potential'), 'youtube', 'https://www.youtube.com/watch?v=GBXuB4u1yEo', 'GBXuB4u1yEo', 'ฟิสิกส์ ม.5 บทที่ 13 ไฟฟ้าสถิต ep. 6(ศักย์ไฟฟ้า)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-electric-potential'), 'แบบทดสอบ: ศักย์ไฟฟ้าและพลังงานศักย์ไฟฟ้า', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-electric-potential')), 'choice', 'ศักย์ไฟฟ้าที่จุดหนึ่ง หมายถึงข้อใดถูกต้องที่สุด', '["แรงที่กระทำต่อประจุหนึ่งหน่วยที่จุดนั้น","งานที่ใช้เคลื่อนประจุหนึ่งหน่วยจากอนันต์หรือจุดอ้างอิงมาที่จุดนั้น","พลังงานจลน์ของประจุที่สุดนั้น","ความเร็วของประจุที่สุดนั้น"]', '1', 'ศักย์ไฟฟ้า V คือ งานที่ใช้เคลื่อนประจุ +1 หน่วยจากจุดอ้างอิง (เช่น อนันต์) มาที่จุดนั้น หน่วยโวลต์ ส่วน E ที่จุดนั้นคือแรงต่อประจุหนึ่งหน่วย ไม่ใช่ศักย์ไฟฟ้า', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-electric-potential')), 'choice', 'เมื่อเคลื่อนประจุบวกจากจุดที่มีศักย์สูงไปยังจุดที่มีศักย์ต่ำ พลังงานศักย์ไฟฟ้าของประจุเปลี่ยนอย่างไร ถ้าไม่คิดแรงอื่น', '["คงที่","เป็นศูนย์","เพิ่มขึ้น","ลดลง"]', '3', 'ประจุบวกเคลื่อนที่ตามสนามจากศักย์สูงไปศักย์ต่ำ แรงไฟฟ้าทำงานให้ จึงพลังงานศักย์ไฟฟ้าลดลงและเปลี่ยนเป็นพลังงานจลน์', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-electric-potential')), 'choice', 'ศักย์ไฟฟ้าที่จุดหนึ่งจากประจุจุดบวก Q มีค่าเป็นบวก ถ้าเพิ่มระยะห่างจากประจุเป็น 2 เท่า ศักย์ไฟฟ้าจะเปลี่ยนเป็นกี่เท่าของเดิม', '["4 เท่า","1/4 เท่า","2 เท่า","1/2 เท่า"]', '3', 'V = kQ/r ศักย์ไฟฟ้าจากประจุจุดแปรผกผันกับระยะทาง เมื่อ r เป็น 2 เท่า V จึงเป็น 1/2 เท่า (ต่างจากสนามไฟฟ้าที่แปรผกผันกับ r²)', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-electric-potential')), 'number', 'ประจุ 3 ไมโครคูลอมบ์ เคลื่อนที่ในสนามไฟฟ้าจากจุดที่มีศักย์ 20 โวลต์ ไปยังจุดศักย์ 100 โวลต์ งานที่ใช้เป็นกี่ไมโครจูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":240,"tolerance":0.5}', 'W = qΔV = 3 × (100 − 20) = 3 × 80 = 240 ไมโครจูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-electric-potential')), 'number', 'ประจุ 5 ไมโครคูลอมบ์ วางที่จุดศักย์ 600 โวลต์ พลังงานศักย์ไฟฟ้าของประจุเป็นกี่มิลลิจูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'U = qV = 5 × 600 = 3000 ไมโครจูล = 3 มิลลิจูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'equilibrium-rotation'), 'equilibrium-center-of-gravity', 'จุดศูนย์ถ่วงและชนิดของสมดุล', 'จุดศูนย์ถ่วงคือตำแหน่งที่รวมน้ำหนักของวัตถุ วัตถุสมดุลสามชนิดคือมั่นคง ไม่มั่นคง และสะเทิน ขึ้นอยู่กับการเคลื่อนที่ของจุดศูนย์ถ่วงเมื่อถูกรบกวน', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'equilibrium-center-of-gravity'), 'youtube', 'https://www.youtube.com/watch?v=j53fatJFWyo', 'j53fatJFWyo', 'ฟิสิกส์ ม.4 บทที่ 4 สมดุลกล ep.1 (สมดุลกล, ศูนย์กลางมวล, ศูนย์ถ่วง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'equilibrium-center-of-gravity'), 'youtube', 'https://www.youtube.com/watch?v=jss8yvkhijs', 'jss8yvkhijs', 'ฟิสิกส์ ม.4 บทที่ 4 สมดุลกล ep.7 (บานพับ, เสถียรภาพของวัตถุ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'equilibrium-center-of-gravity'), 'แบบทดสอบ: จุดศูนย์ถ่วง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-center-of-gravity')), 'choice', 'สมดุลทั้งสามชนิดคือข้อใด', '["สมดุลมั่นคง สมดุลไม่มั่นคง สมดุลสะเทิน","สมดุลนิ่ง สมดุลเคลื่อนที่ สมดุลหมุน","สมดุลอ่อน สมดุลแข็ง สมดุลดิน","สมดุลเร็ว สมดุลช้า สมดุลปานกลาง"]', '0', 'สมดุลสามชนิดคือสมดุลมั่นคง (ถอนกลับสู่สมดุล) ไม่มั่นคง (ล้มออกจากสมดุล) และสะเทิน (อยู่ในตำแหน่งใหม่)', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-center-of-gravity')), 'choice', 'เหตุใดวัตถุทรงสูงและฐานแคบจึงล้มง่าย', '["จุดศูนย์ถ่วงต่ำมาก","เส้นดิ่งจากจุดศูนย์ถ่วงหลุดออกนอกฐานรองรับได้ง่าย","มีมวลมากเกินไป","แรงดึงของพื้นน้อยเกินไป"]', '1', 'วัตถุจะไม่ล้มตราบใดที่เส้นดิ่งจากจุดศูนย์ถ่วงยังอยู่ในฐานรองรับ ฐานแคบทำให้เส้นดิ่งหลุดออกได้ง่ายจึงล้มง่าย', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-center-of-gravity')), 'choice', 'จุดศูนย์ถ่วงของวัตถุหมายถึงอะไร', '["จุดที่อยู่ตรงศูนย์กลางของวัตถุเสมอ","จุดที่วัตถุเบาที่สุด","จุดที่ถือว่าน้ำหนักทั้งหมดของวัตถุรวมอยู่","จุดที่แรงโน้มถ่วงไม่มีผล"]', '2', 'จุดศูนย์ถ่วงคือตำแหน่งที่เราถือว่าน้ำหนักรวมของวัตถุกระทำที่จุดนั้น ใช้แทนวัตถุทั้งก้อนในการวิเคราะห์สมดุล', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-center-of-gravity')), 'number', 'แท่งตรงสม่ำเสมอยาว 6 เมตร จุดศูนย์ถ่วงอยู่ห่างจากปลายข้างหนึ่งกี่เมตร', NULL, '{"value":3,"tolerance":0.5}', 'แท่งสม่ำเสมอจุดศูนย์ถ่วงอยู่กึ่งกลางความยาว จึงอยู่ห่างปลาย 6/2 = 3 เมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-center-of-gravity')), 'number', 'มวล 3 กิโลกรัม และ 5 กิโลกรัม วางห่างกัน 4 เมตร จุดศูนย์ถ่วงของระบบอยู่ห่างจากมวล 5 กิโลกรัม กี่เมตร (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":1.5,"tolerance":0.05}', 'กำหนดจุดศูนย์ถ่วงห่างจากมวล 5 กิโลกรัม x เมตร จากสมดุลโมเมนต์ 3(4−x) = 5x ได้ x = 12/8 = 1.5 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'equilibrium-rotation'), 'equilibrium-rotational', 'สมดุลต่อการหมุน', 'วัตถุในสมดุลต่อการหมุนหมายถึงผลรวมโมเมนต์ตามเข็มนาฬิกาเท่ากับทวนเข็มนาฬิกา ทำให้ไม่มีความเร่งเชิงมุม', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'equilibrium-rotational'), 'youtube', 'https://www.youtube.com/watch?v=f1MCasKV3R4', 'f1MCasKV3R4', 'ฟิสิกส์ ม.4 บทที่ 4 สมดุลกล ep.5 (สมดุลต่อการหมุน, โมเมนต์แรงคู่ควบ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'equilibrium-rotational'), 'แบบทดสอบ: สมดุลต่อการหมุน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-rotational')), 'choice', 'เงื่อนไขของสมดุลต่อการหมุนคือข้อใด', '["ผลรวมโมเมนต์ทวนเข็มนาฬิกาเท่ากับตามเข็มนาฬิกา","ผลรวมแรงเป็นศูนย์เพียงอย่างเดียว","ความเร็วเชิงมุมเป็นศูนย์เสมอ","พลังงานจลน์เป็นศูนย์"]', '0', 'สมดุลต่อการหมุนเกิดขึ้นเมื่อโมเมนต์รวมรอบจุดหมุนเป็นศูนย์ นั่นคือโมเมนต์ตามเข็มเท่ากับทวนเข็ม', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-rotational')), 'choice', 'สำหรับไม้บรรทัดที่วางอยู่บนจุดหมุนกลางแล้วสมดุล โมเมนต์รอบจุดหมุนรวมมีค่าเท่าใด', '["มีค่ามากที่สุด","เท่ากับศูนย์","เท่ากับน้ำหนักไม้บรรทัด","เท่ากับแรงกดจุดหมุน"]', '1', 'สมดุลต่อการหมุนทำให้โมเมนต์รวมรอบจุดหมุนเป็นศูนย์ โมเมนต์ทวนเข็มจึงหักล้างกับตามเข็มพอดี', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-rotational')), 'choice', 'การสมดุลของคานที่วางบนจุดหมุน ต้องใช้ปริมาณใดเปรียบเทียบกัน', '["น้ำหนักของแต่ละข้าง","โมเมนต์ของแรงของแต่ละข้างรอบจุดหมุน","ความยาวของคานรวม","ความเร็วของปลายคาน"]', '1', 'คานจะสมดุลเมื่อโมเมนต์ของแรงด้านหนึ่งเท่ากับอีกด้านหนึ่งรอบจุดหมุน ไม่ใช่แค่น้ำหนัก', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-rotational')), 'number', 'กระดานหกจุดหมุนอยู่ตรงกลาง ปลายด้านหนึ่งวางมวล 10 กิโลกรัม ห่างจุดหมุน 1 เมตร ต้องการให้สมดุล ต้องวางมวล 2 กิโลกรัมอีกด้านหนึ่งห่างจากจุดหมุนกี่เมตร', NULL, '{"value":5,"tolerance":0.5}', 'สมดุลต่อการหมุน m1d1 = m2d2 ได้ 10×1 = 2×d2 จึง d2 = 5 เมตร (g หักล้างกันได้)', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-rotational')), 'number', 'คานเบาสมดุลรอบจุดหมุนกลาง วางมวล 4 กิโลกรัม ที่ด้านหนึ่งห่างจุดหมุน 1 เมตร ต้องวางมวล 8 กิโลกรัม อีกด้านหนึ่งห่างจุดหมุนกี่เมตร (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":0.5,"tolerance":0.05}', 'สมดุลโมเมนต์ 4×1 = 8×d2 ได้ d2 = 4/8 = 0.5 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'equilibrium-rotation'), 'equilibrium-torque', 'โมเมนต์ของแรง', 'โมเมนต์ของแรงคือผลคูณของแรงกับแขนโมเมนต์ τ = F × d มีหน่วยนิวตัน·เมตร แสดงความสามารถของแรงในการหมุนวัตถุรอบจุดหมุน', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'equilibrium-torque'), 'youtube', 'https://www.youtube.com/watch?v=dFlVYi8tlh8', 'dFlVYi8tlh8', 'ฟิสิกส์ ม.4 บทที่ 4 สมดุลกล ep.4 (สมดุลต่อการหมุน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'equilibrium-torque'), 'แบบทดสอบ: โมเมนต์ของแรง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-torque')), 'choice', 'โมเมนต์ของแรง τ รอบจุดหมุน หาได้จากสูตรใด โดย F คือแรง และ d คือแขนโมเมนต์', '["τ = F × d","τ = F / d","τ = F + d","τ = ½Fd²"]', '0', 'โมเมนต์ของแรง = แรงคูณกับแขนโมเมนต์ (ระยะตั้งฉากจากจุดหมุนถึงแนวแรง) τ = Fd', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-torque')), 'choice', 'หน่วยของโมเมนต์ของแรงคือข้อใด', '["จูล","นิวตัน·เมตร","วัตต์","เมตร/วินาที"]', '1', 'โมเมนต์แรง = แรง × ระยะทาง จึงมีหน่วยนิวตัน·เมตร แม้ตัวเลขจะเหมือนงานแต่เป็นปริมาณต่างชนิดกัน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-torque')), 'choice', 'แรงกระทำผ่านจุดหมุนพอดี วัตถุจะหมุนหรือไม่', '["หมุนได้มากที่สุด","ไม่ทำให้เกิดโมเมนต์เพราะแขนโมเมนต์เป็นศูนย์","หมุนครึ่งหนึ่งของปกติ","หมุนตามขนาดแรงเสมอ"]', '1', 'ถ้าแนวแรงผ่านจุดหมุน แขนโมเมนต์เป็นศูนย์ โมเมนต์จึงเป็นศูนย์ แรงนั้นไม่ทำให้เกิดการหมุน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-torque')), 'number', 'ใช้แรง 10 นิวตัน กระทำตั้งฉากกับคานที่ห่างจากจุดหมุน 2 เมตร โมเมนต์ของแรงรอบจุดหมุนมีค่ากี่นิวตัน·เมตร', NULL, '{"value":20,"tolerance":0.5}', 'τ = Fd = 10 × 2 = 20 นิวตัน·เมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-torque')), 'number', 'ใช้แรง 30 นิวตัน กระทำตั้งฉากกับคานที่ห่างจากจุดหมุน 0.5 เมตร โมเมนต์ของแรงมีค่ากี่นิวตัน·เมตร', NULL, '{"value":15,"tolerance":0.5}', 'τ = Fd = 30 × 0.5 = 15 นิวตัน·เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'equilibrium-rotation'), 'equilibrium-translational', 'สมดุลต่อการเลื่อนที่', 'วัตถุในสมดุลต่อการเลื่อนที่หมายถึงแรงลัพธ์เป็นศูนย์ วัตถุอาจอยู่นิ่งหรือเคลื่อนที่ด้วยความเร็วคงที่ก็ได้', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
