INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'gravitation-newton-law')), 'choice', 'แรงโน้มถ่วงระหว่างมวล m₁ และ m₂ ห่างกัน r มีขนาดตามข้อใด', '["F = G m₁ m₂ / r²","F = G m₁ m₂ r²","F = G r² / (m₁ m₂)","F = G m₁ m₂ / r"]', '0', 'กฎความโน้มถ่วงสากล F = Gm₁m₂/r² แรงแปรผกผันกับกำลังสองของระยะห่าง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'gravitation-newton-law')), 'choice', 'ทิศทางของแรงโน้มถ่วงระหว่างวัตถุสองก้อนเป็นอย่างไร', '["ผลักกันเสมอ","ดึงดูดกันเสมอ","ผลักหรือดึงขึ้นกับชนิดมวล","ไม่มีแรงระหว่างวัตถุใดๆ"]', '1', 'แรงโน้มถ่วงเป็นแรงดึงดูดระหว่างมวลเสมอ ไม่มีแรงผลักโน้มถ่วง ทิศเข้าหากัน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'gravitation-newton-law')), 'choice', 'ถ้าเพิ่มระยะห่างระหว่างมวลสองก้อนเป็น 2 เท่า แรงโน้มถ่วงเปลี่ยนเป็นกี่เท่าของเดิม', '["2 เท่า","4 เท่า","1/4 เท่า","1/2 เท่า"]', '2', 'F แปรผกผันกับ r² เมื่อ r เป็น 2 เท่า F จึงเป็น 1/4 เท่า', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'gravitation-newton-law')), 'number', 'วัตถุมวล 5 กิโลกรัม วางบนผิวโลก แรงโน้มถ่วงที่โลกกระทำต่อวัตถุมีค่ากี่นิวตัน (ใช้ g = 10 เมตร/วินาที²)', NULL, '{"value":50,"tolerance":0.5}', 'แรงโน้มถ่วงที่ผิวโลกเท่ากับน้ำหนักของวัตถุ F = mg = 5 × 10 = 50 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'gravitation-newton-law')), 'number', 'วัตถุมวล 3 กิโลกรัม วางบนผิวโลก แรงโน้มถ่วงที่โลกกระทำต่อวัตถุมีค่ากี่นิวตัน (ใช้ g = 10 เมตร/วินาที²)', NULL, '{"value":30,"tolerance":0.5}', 'F = mg = 3 × 10 = 30 นิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'oscillation-gravity'), 'gravitation-satellite-field', 'สนามโน้มถ่วงและดาวเทียม', 'สนามโน้มถ่วง g = GM/r² ความเร็วของดาวเทียมที่โคจรไม่ขึ้นกับมวลดาวเทียม โดยได้จากสมดุลของแรงโน้มถ่วงและแรงสู่ศูนย์กลาง', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
