INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-ac-rms'), 'แบบทดสอบ: ไฟฟ้ากระแสสลับและค่า rms', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-ac-rms')), 'choice', 'ค่า rms ของแรงดันไฟฟ้ากระแสสลับ มีความหมายตรงกับข้อใด', '["ค่าแรงดันที่ให้กำลังเฉลี่ยเท่ากับกระแสตรง","ค่าแรงดันเป็นศูนย์","ค่าเฉลี่ยเลขคณิตของแรงดัน","ค่าแรงดันสูงสุดในครึ่งรอบ"]', '0', 'ค่า rms (ค่าประสิทธิผล) คือค่าแรงดันกระแสตรงที่ให้กำลังเฉลี่ยเท่ากัน ความสัมพันธ์ V_rms = V_max/√2 เพราะกำลังแปรผันกับกำลังสองของแรงดัน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-ac-rms')), 'choice', 'ค่าแรงดันสูงสุด V_max กับค่า rms V_rms ของกระแสสลับไซน์ มีความสัมพันธ์กันอย่างไร', '["V_rms = V_max × √2","V_rms = V_max/√2","V_max = 2V_rms","V_max = V_rms"]', '1', 'สำหรับคลื่นไซน์ V_rms = V_max/√2 ดังนั้นค่า rms จึงน้อยกว่าค่าแรงดันสูงสุดประมาณ 0.707 เท่า', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-ac-rms')), 'choice', 'แรงดันไฟฟ้า 220 โวลต์ ที่ใช้ในบ้าน เป็นค่าแบบใด', '["ค่าแรงดันทันที ณ เวลาใดเวลาหนึ่ง","ค่าแรงดันสูงสุด","ค่า rms","ค่าเฉลี่ย"]', '2', 'แรงดันไฟบ้าน 220 โวลต์เป็นค่า rms (ค่าประสิทธิผล) ซึ่งเครื่องวัดไฟฟ้าทั่วไปอ่านค่า rms ส่วนค่าแรงดันสูงสุดจริงคือ 220×√2 ≈ 311 โวลต์', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-ac-rms')), 'number', 'แรงดันไฟฟ้ากระแสสลับมีค่าสูงสุด 311 โวลต์ ค่า rms ของแรงดันนี้เท่ากับกี่โวลต์ (ใช้ √2 ≈ 1.414 ตอบเป็นจำนวนเต็ม)', NULL, '{"value":220,"tolerance":0.5}', 'V_rms = V_max/√2 = 311/1.414 ≈ 220 โวลต์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-ac-rms')), 'number', 'ค่ากระแส rms ในวงจรคือ 5 แอมแปร์ ค่ากระแสสูงสุดของกระแสสลับไซน์เท่ากับกี่แอมแปร์ (ใช้ √2 ≈ 1.41 ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":7.1,"tolerance":0.05}', 'I_max = I_rms × √2 = 5 × 1.41 = 7.05 ≈ 7.1 แอมแปร์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'induction-ac'), 'induction-ac-faraday-flux', 'ฟลักซ์แม่เหล็กและกฎของฟาราเดย์', 'ฟลักซ์แม่เหล็กคือปริมาณเส้นสนามแม่เหล็กที่ผ่านพื้นที่ และเมื่อฟลักซ์เปลี่ยนจะเกิดแรงเคลื่อนไฟฟ้าเหนี่ยวนำตามกฎของฟาราเดย์ emf = −NΔΦ/Δt', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux'), 'youtube', 'https://www.youtube.com/watch?v=7bqyfKKZrnk', '7bqyfKKZrnk', 'ฟิสิกส์ ม.6 บทที่ 15 แม่เหล็กและไฟฟ้า ep.5 (แรงเคลื่อนไฟฟ้าเหนี่ยวนำ,emf, กระแสเหนี่ยวนำและหม้อแปลง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux'), 'แบบทดสอบ: ฟลักซ์แม่เหล็กและกฎของฟาราเดย์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux')), 'choice', 'ฟลักซ์แม่เหล็กที่ผ่านขดลวดที่มีพื้นที่ A ในสนามแม่เหล็กสม่ำเสมอ B ที่ตั้งฉากกับพื้นที่ หาได้จากสูตรใด', '["Φ = BA","Φ = A/B","Φ = ½BA²","Φ = B/A"]', '0', 'ฟลักซ์แม่เหล็ก Φ = B·A·cos θ เมื่อสนามตั้งฉากกับพื้นที่ θ = 0 องศา cos θ = 1 จึง Φ = BA หน่วยเวเบอร์', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux')), 'choice', 'กฎของฟาราเดย์กล่าวว่าอะไร ทำให้เกิดแรงเคลื่อนไฟฟ้าเหนี่ยวนำในขดลวด', '["การมีกระแสไหลผ่านขดลวด","การเปลี่ยนแปลงของฟลักซ์แม่เหล็กที่ผ่านขดลวด","อุณหภูมิของขดลวดเพิ่มขึ้น","ความต้านทานของขดลวดน้อยลง"]', '1', 'แรงเคลื่อนไฟฟ้าเหนี่ยวนำ (emf) เกิดเมื่อฟลักซ์แม่เหล็กที่ผ่านขดลวดเปลี่ยนไปตามเวลาตามกฎ faraday emf = −NΔΦ/Δt ไม่ใช่เกิดจากกระแสคงที่', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux')), 'choice', 'ถ้าเพิ่มจำนวนรอบของขดลวดเป็น 2 เท่า โดยอัตราการเปลี่ยนแปลงฟลักซ์คงที่ แรงเคลื่อนไฟฟ้าเหนี่ยวนำจะเป็นกี่เท่า', '["1/2 เท่า","4 เท่า","เท่าเดิม","2 เท่า"]', '3', 'emf = −NΔΦ/Δt แรงเคลื่อนไฟฟ้าเหนี่ยวนำแปรผันตรงกับจำนวนรอบ N เมื่อ N เป็น 2 เท่า emf จึงเป็น 2 เท่า', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux')), 'number', 'ขดลวด 100 รอบ มีฟลักซ์แม่เหล็กเปลี่ยนจาก 0.02 เวเบอร์ เป็น 0.08 เวเบอร์ ในเวลา 0.5 วินาที แรงเคลื่อนไฟฟ้าเหนี่ยวนำเฉลี่ยเท่ากับกี่โวลต์ (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":12,"tolerance":0.05}', 'emf = NΔΦ/Δt = 100 × (0.08 − 0.02)/0.5 = 100 × 0.06/0.5 = 100 × 0.12 = 12 โวลต์ (ใช้ขนาด ไม่ใส่เครื่องหมายลบ)', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux')), 'number', 'ขดลวด 200 รอบ มีฟลักซ์ผ่านลดลงจาก 0.05 เวเบอร์ เป็น 0.01 เวเบอร์ ในเวลา 0.4 วินาที แรงเคลื่อนไฟฟ้าเหนี่ยวนำเฉลี่ยเท่ากับกี่โวลต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', 'emf = NΔΦ/Δt = 200 × (0.05 − 0.01)/0.4 = 200 × 0.04/0.4 = 200 × 0.1 = 20 โวลต์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'induction-ac'), 'induction-ac-lenz-law', 'กฎของเลนซ์', 'กฎของเลนซ์กล่าวว่ากระแสเหนี่ยวนำมีทิศทางที่ต้านการเปลี่ยนแปลงของฟลักซ์แม่เหล็กที่ทำให้เกิดกระแสนั้น ซึ่งใช้กำหนดทิศของแรงเคลื่อนไฟฟ้าเหนี่ยวนำ', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-lenz-law'), 'youtube', 'https://www.youtube.com/watch?v=7bqyfKKZrnk', '7bqyfKKZrnk', 'ฟิสิกส์ ม.6 บทที่ 15 แม่เหล็กและไฟฟ้า ep.5 (แรงเคลื่อนไฟฟ้าเหนี่ยวนำ,emf, กระแสเหนี่ยวนำและหม้อแปลง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-lenz-law'), 'แบบทดสอบ: กฎของเลนซ์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-lenz-law')), 'choice', 'กฎของเลนซ์ใช้กำหนดอะไร', '["ทิศทางของกระแสเหนี่ยวนำ","ขนาดของมวล","ความเร็วของแสง","ขนาดของความต้านทาน"]', '0', 'กฎของเลนซ์กำหนดทิศทางของกระแสเหนี่ยวนำและแรงเคลื่อนไฟฟ้าเหนี่ยวนำ โดยกระแสเหนี่ยวนำจะมีทิศต้านการเปลี่ยนแปลงของฟลักซ์ที่ทำให้เกิดมัน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-lenz-law')), 'choice', 'เมื่อแท่งแม่เหล็กขั้วเหนือเคลื่อนเข้าหาขดลวด กระแสเหนี่ยวนำในขดลวดจะสร้างขั้วแม่เหล็กอย่างไรที่ด้านใกล้แท่ง', '["ไม่มีขั้ว","สลับไปสลับมา","ขั้วเหนือ","ขั้วใต้"]', '2', 'เพื่อทำงานต้านการเข้าใกล้ของขั้วเหนือ กระแสเหนี่ยวนำจะสร้างขั้วเหนือที่ด้านใกล้แท่ง (ขั้วเหมือนกันผลักกัน) ตามกฎของเลนซ์ที่ว่ากระแสตอบโต้การเปลี่ยนแปลงฟลักซ์', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-lenz-law')), 'choice', 'กฎของเลนซ์สอดคล้องกับหลักการอนุรักษ์พลังงานอย่างไร', '["พลังงานถูกทำลาย","ไม่เกี่ยวข้องกับพลังงาน","กระแสเหนี่ยวนำสร้างพลังงานจากความว่างเปล่า","พลังงานที่ใช้ถูกรักษาไว้โดยงานต้านแรงแม่เหล็ก"]', '3', 'กระแสเหนี่ยวนำที่ต้านการเปลี่ยนแปลงฟลักซ์ทำให้ต้องทำงานต้านแรงแม่เหล็ก ซึ่งพลังงานส่วนนี้คือพลังงานที่ถูกเปลี่ยน ถ้ากระแสไม่ต้าน พลังงานก็จะถูกสร้างจากสิ่งไม่มีที่มา ละเมิดการอนุรักษ์พลังงาน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-lenz-law')), 'number', 'ขดลวดมีฟลักซ์แม่เหล็กเพิ่มขึ้น 0.3 เวเบอร์ ในเวลา 0.2 วินาที ขดลวดมี 50 รอบ แรงเคลื่อนไฟฟ้าเหนี่ยวนำเฉลี่ยเท่ากับกี่โวลต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":75,"tolerance":0.5}', 'emf = NΔΦ/Δt = 50 × 0.3/0.2 = 50 × 1.5 = 75 โวลต์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-lenz-law')), 'number', 'วงจรหนึ่งมีฟลักซ์แม่เหล็กลดลง 0.4 เวเบอร์ ในเวลา 0.4 วินาที ทำให้เกิดแรงเคลื่อนไฟฟ้าเหนี่ยวนำ 20 โวลต์ จำนวนรอบของขดลวดเท่ากับกี่รอบ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', 'N = emf×Δt/ΔΦ = 20 × 0.4/0.4 = 20 รอบ', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'induction-ac'), 'induction-ac-transformer', 'หม้อแปลง', 'หม้อแปลงเปลี่ยนขนาดแรงดันไฟฟ้ากระแสสลับโดยอาศัยการเหนี่ยวนำแม่เหล็ก อัตราส่วนแรงดันเท่ากับอัตราส่วนจำนวนรอบ และกำลังไฟฟ้าอุดมคติขาเข้าขาเท่ากับขาออก', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-transformer'), 'youtube', 'https://www.youtube.com/watch?v=P6hSs4q9wzk', 'P6hSs4q9wzk', 'ฟิสิกส์ ม.6 บทที่ 15 แม่เหล็กและไฟฟ้า ep.6(หม้อแปลงไฟฟ้า)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-transformer'), 'แบบทดสอบ: หม้อแปลง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-transformer')), 'choice', 'หม้อแปลงทำงานได้กับไฟฟ้าชนิดใด', '["กระแสตรงเท่านั้น","กระแสสลับเท่านั้น","ทั้งกระแสตรงและสลับ","ไม่ใช้ไฟฟ้า"]', '1', 'หม้อแปลงต้องอาศัยฟลักซ์แม่เหล็กที่เปลี่ยนแปลงตามเวลา จึงทำงานด้วยไฟฟ้ากระแสสลับ กระแสตรงให้ฟลักซ์คงที่จึงเกิดการเหนี่ยวนำไม่ได้', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-transformer')), 'choice', 'ในหม้อแปลงอุดมคติ อัตราส่วนของแรงดันขาออกต่อขาเข้า เท่ากับอัตราส่วนของอะไร', '["ความต้านทานขดปฐมภูมิ","ความยาวของแกนเหล็ก","จำนวนรอบขดทุติยภูมิต่อขดปฐมภูมิ","จำนวนรอบขดปฐมภูมิต่อทุติยภูมิ"]', '2', 'V₂/V₁ = N₂/N₁ แรงดันแปรผันตรงกับจำนวนรอบ ดังนั้นหม้อแปลงเพิ่มแรงดัน (step-up) จึงมีรอบขดทุติยภูมิมากกว่าปฐมภูมิ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-transformer')), 'choice', 'หม้อแปลงอุดมคติที่มีกำลังไฟฟ้าขาเข้าเท่ากับขาออก ถ้าแรงดันเพิ่มขึ้นเป็น 10 เท่า กระแสจะเปลี่ยนอย่างไร', '["เท่าเดิม","กลายเป็นศูนย์","เพิ่มขึ้น 10 เท่า","ลดลง 10 เท่า"]', '3', 'กำลัง P = VI คงที่ในหม้อแปลงอุดมคติ ถ้า V เพิ่ม 10 เท่า I ต้องลดลง 10 เท่า เพื่อให้ผลคูณ VI คงที่ นี่คือหลักการส่งไฟฟ้าแรงสูงเพื่อลดกระแสและความสูญเสีย', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-transformer')), 'number', 'หม้อแปลงมีขดปฐมภูมิ 400 รอบ ขดทุติยภูมิ 2000 รอบ ต่อแรงดันปฐมภูมิ 220 โวลต์ แรงดันขาออกที่ขดทุติยภูมิเท่ากับกี่โวลต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":1100,"tolerance":0.5}', 'V₂ = V₁ × N₂/N₁ = 220 × 2000/400 = 220 × 5 = 1100 โวลต์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-transformer')), 'number', 'หม้อแปลงอุดมคติขดปฐมภูมิแรงดัน 220 โวลต์ กระแส 5 แอมแปร์ ขดทุติยภูมิแรงดัน 1100 โวลต์ กระแสที่ขดทุติยภูมิเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":1,"tolerance":0.5}', 'กำลังคงที่: V₁I₁ = V₂I₂ → I₂ = V₁I₁/V₂ = 220×5/1100 = 1100/1100 = 1 แอมแปร์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-electricity'), 'jr-electricity-circuits', 'วงจรไฟฟ้า', 'วงจรไฟฟ้าที่สมบูรณ์ต้องต่อเป็นวงปิด ในวงจรอนุกรมกระแสไหลผ่านทีละหลอดและมีค่าเท่ากัน ส่วนวงจรขนานแต่ละเส้นทางมีกระแสของตัวเอง', 'junior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits'), 'youtube', 'https://www.youtube.com/watch?v=jtpSa88iihg', 'jtpSa88iihg', 'วงจรไฟฟ้าแบบอนุกรม (วิทยาศาสตร์ ม. 3 เล่ม 2 หน่วยที่ 6 บทที่ 1 วงจรไฟฟ้าอย่างง่าย)', 'Proj14 ม.3', 'https://www.youtube.com/channel/UCEDTSRW-0iUxL_45MR3ESPg', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits'), 'youtube', 'https://www.youtube.com/watch?v=iKE8PComPWY', 'iKE8PComPWY', 'วงจรไฟฟ้าแบบขนาน (วิทยาศาสตร์ ม. 3 เล่ม 2 หน่วยที่ 6 บทที่ 1 วงจรไฟฟ้าอย่างง่าย)', 'Proj14 ม.3', 'https://www.youtube.com/channel/UCEDTSRW-0iUxL_45MR3ESPg', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits'), 'แบบทดสอบ: วงจรไฟฟ้า', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits')), 'choice', 'วงจรไฟฟ้าที่สมบูรณ์ต้องประกอบด้วยอะไร', '["แหล่งพลังงาน ตัวนำ สายไฟ และอุปกรณ์ไฟฟ้า ต่อเป็นวงปิด","แหล่งพลังงานเท่านั้น","เฉพาะสายไฟ","แบตเตอรี่และสวิตช์เท่านั้น"]', '0', 'วงจรไฟฟ้าสมบูรณ์ต้องมีแหล่งพลังงาน สายไฟ อุปกรณ์ใช้ไฟ และสวิตช์ ต่อกันเป็นวงปิดให้กระแสไหลครบวงจร', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits')), 'choice', 'ในวงจรอนุกรม ถ้าหลอดไฟหลอดหนึ่งขาด หลอดอื่นจะเป็นอย่างไร', '["สว่างมากขึ้น","ไม่เปลี่ยนแปลง","สว่างเท่าเดิม","ดับทั้งหมด เพราะกระแสไหลผ่านทีละหลอด"]', '3', 'วงจรอนุกรมกระแสไหลผ่านหลอดทีละหลอดต่อเนื่องกัน ถ้าหลอดหนึ่งขาดวงจรขาด กระแสไหลไม่ได้ หลอดทั้งหมดจึงดับ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits')), 'choice', 'ข้อใดกล่าวถูกต้องเกี่ยวกับวงจรขนาน', '["กระแสไหลผ่านหลอดเดียวเท่านั้น","ถ้าหลอดหนึ่งขาด หลอดอื่นยังติดอยู่ เพราะแต่ละเส้นทางเป็นอิสระต่อกัน","หลอดทุกหลอดต้องติดหรือดับพร้อมกันเสมอ","วงจรขนานใช้กับแบตเตอรี่ไม่ได้"]', '1', 'วงจรขนานแต่ละเส้นทางเป็นอิสระต่อกัน หลอดหนึ่งขาดจึงไม่ตัดวงจรของหลอดอื่น', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits')), 'number', 'กระแสไฟฟ้าในวงจรอนุกรมมีค่า 2 แอมแปร์ กระแสที่ไหลผ่านหลอดแต่ละหลอดในวงจรนี้เท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'ในวงจรอนุกรมกระแสมีค่าเท่ากันทุกจุด จึงไหลผ่านหลอดแต่ละหลอดเท่ากับ 2 แอมแปร์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits')), 'number', 'วงจรขนานมีกระแสรวม 6 แอมแปร์ แบ่งไหลผ่านหลอดสองเส้นทางเท่ากัน กระแสในแต่ละเส้นทางเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'กระแสรวมแบ่งไปตามเส้นทาง 6 ÷ 2 = 3 แอมแปร์ในแต่ละเส้นทาง', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-electricity'), 'jr-electricity-current-voltage-resistance', 'กระแส ความต่างศักย์ ความต้านทาน', 'กระแสไฟฟ้าคือการไหลของประจุต่อหน่วยเวลา ความต่างศักย์มีหน่วยเป็นโวลต์ ส่วนความต้านทานขึ้นกับชนิด ขนาด และความยาวของตัวนำ', 'junior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
