INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-current-voltage-resistance')), 'choice', 'กระแสไฟฟ้าคือปริมาณใด', '["การเคลื่อนที่ของโปรตอนในตัวนำ","การไหลของประจุไฟฟ้าในตัวนำต่อหน่วยเวลา","แรงดันไฟฟ้าที่มีในวงจร","พลังงานไฟฟ้าที่ใช้ทั้งหมด"]', '1', 'กระแสไฟฟ้าคือปริมาณประจุที่ไหลผ่านจุดหนึ่งในหนึ่งหน่วยเวลา มีหน่วยเป็นแอมแปร์', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-current-voltage-resistance')), 'choice', 'หน่วยของความต่างศักย์ไฟฟ้า (แรงดันไฟฟ้า) คือข้อใด', '["แอมแปร์","โอห์ม","โวลต์","วัตต์"]', '2', 'ความต่างศักย์หรือแรงดันไฟฟ้ามีหน่วยเป็นโวลต์ แอมแปร์เป็นหน่วยกระแส โอห์มเป็นหน่วยความต้านทาน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-current-voltage-resistance')), 'choice', 'ความต้านทานไฟฟ้าของตัวนำตัวหนึ่งขึ้นกับสมบัติใดเป็นหลัก', '["สีของฉนวนหุ้มสายไฟ","ความยาวรอบของตัวนำเท่านั้น","อุณหภูมิอากาศภายนอก","ชนิดของวัสดุ ขนาด และความยาวของตัวนำ"]', '3', 'ความต้านทานขึ้นกับชนิดของวัสดุ พื้นที่หน้าตัด และความยาวของตัวนำ ตัวนำยาวและเล็กจะมีความต้านทานมาก', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-current-voltage-resistance')), 'number', 'ประจุ 12 คูลอมบ์ไหลผ่านจุดหนึ่งในเวลา 3 วินาที กระแสไฟฟ้าเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 'I = Q / t = 12 ÷ 3 = 4 แอมแปร์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-current-voltage-resistance')), 'number', 'ประจุ 20 คูลอมบ์ไหลผ่านจุดหนึ่งในเวลา 4 วินาที กระแสไฟฟ้าเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":5,"tolerance":0.5}', 'I = Q / t = 20 ÷ 4 = 5 แอมแปร์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-electricity'), 'jr-electricity-electric-power', 'พลังงานไฟฟ้า', 'กำลังไฟฟ้าคือพลังงานไฟฟ้าที่ใช้ในหนึ่งหน่วยเวลา มีหน่วยเป็นวัตต์ และหน่วยไฟฟ้าตามมิเตอร์ 1 หน่วยเท่ากับ 1 กิโลวัตต์ชั่วโมง', 'junior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
