INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-electric-power')), 'choice', 'กำลังไฟฟ้าคือปริมาณใด', '["พลังงานที่สะสมอยู่ในแบตเตอรี่","ความต่างศักย์ของวงจร","กระแสที่ไหลผ่านวงจร","พลังงานไฟฟ้าที่ใช้ในหนึ่งหน่วยเวลา"]', '3', 'กำลังไฟฟ้าคือพลังงานไฟฟ้าที่ใช้ต่อหน่วยเวลา คำนวณจาก P = W / t หรือ P = VI มีหน่วยเป็นวัตต์', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-electric-power')), 'choice', 'หน่วยของกำลังไฟฟ้าคือข้อใด', '["วัตต์ (W)","โวลต์ (V)","แอมแปร์ (A)","โอห์ม (Ω)"]', '0', 'กำลังไฟฟ้ามีหน่วยเป็นวัตต์ ส่วนโวลต์เป็นหน่วยความต่างศักย์ แอมแปร์เป็นหน่วยกระแส โอห์มเป็นหน่วยความต้านทาน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-electric-power')), 'choice', 'การคิดค่าไฟฟ้า หน่วยไฟฟ้า 1 หน่วย (ยูนิต) เท่ากับพลังงานปริมาณใด', '["1 วัตต์ชั่วโมง","1 จูล","1 กิโลวัตต์ชั่วโมง","1 โวลต์แอมแปร์"]', '2', 'หน่วยไฟฟ้า 1 หน่วยตามมิเตอร์เท่ากับพลังงาน 1 กิโลวัตต์ชั่วโมง (1 kWh)', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-electric-power')), 'number', 'เครื่องใช้ไฟฟ้ามีกำลัง 1000 วัตต์ ใช้เป็นเวลา 2 ชั่วโมง ใช้พลังงานไฟฟ้ากี่กิโลวัตต์ชั่วโมง (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', '1000 วัตต์ = 1 กิโลวัตต์ พลังงาน = 1 × 2 = 2 กิโลวัตต์ชั่วโมง', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-electric-power')), 'number', 'หลอดไฟ 60 วัตต์เปิดนาน 3 ชั่วโมง ใช้พลังงานไฟฟ้ากี่วัตต์ชั่วโมง (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":180,"tolerance":0.5}', 'พลังงาน = กำลัง × เวลา = 60 × 3 = 180 วัตต์ชั่วโมง', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-electricity'), 'jr-electricity-ohms-law', 'กฎของโอห์ม', 'กฎของโอห์มกล่าวว่า กระแสไฟฟ้าแปรผันตรงกับความต่างศักย์ และแปรผกผันกับความต้านทาน คำนวณได้จาก V = IR', 'junior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-electricity-ohms-law'), 'youtube', 'https://www.youtube.com/watch?v=ixbKrdrpWbI', 'ixbKrdrpWbI', 'วิทยาศาสตร์  ม.3 กฎของโอห์ม ( การหาค่า กระแสไฟฟ้า ความต่างศักย์ และความต้านทาน )', 'เรียนวิทย์ กับครูอ้อย', 'https://www.youtube.com/channel/UCptM8_BRHOXQfCDoqnBSdCQ', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-electricity-ohms-law'), 'youtube', 'https://www.youtube.com/watch?v=C5iRkBbjn0k', 'C5iRkBbjn0k', 'ติวสอบวิทย์ม.3 | กฎของโอห์ม | มีตัวอย่างโจทย์คำนวณ', 'ครูสิงห์ สอนวิทย์', 'https://www.youtube.com/channel/UClZ7GG1I94BduUnibpRU_CQ', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-electricity-ohms-law'), 'ohm-law', 'ปรับ V และ R แล้วดูกระแสและกำลังไฟฟ้า', '{"voltage":{"min":1,"max":24,"default":12},"resistance":{"min":1,"max":20,"default":6}}');
