INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-acceleration')), 'choice', 'ความเร่งมีความหมายตรงกับข้อใด', '["ความเร็วหารด้วยเวลา","ระยะทางต่อเวลา","อัตราการเปลี่ยนความเร็วต่อเวลา","แรงที่กระทำต่อวัตถุ"]', '2', 'ความเร่งคืออัตราการเปลี่ยนความเร็วต่อเวลา มีหน่วยเมตร/วินาที² ไม่ใช่ระยะทางต่อเวลาซึ่งคืออัตราเร็ว', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-acceleration')), 'choice', 'รถเร่งจากหยุดนิ่งเป็นความเร็ว 10 เมตร/วินาทีในเวลา 5 วินาที ความเร่งเป็นเท่าใด', '["5 เมตร/วินาที²","10 เมตร/วินาที²","0.5 เมตร/วินาที²","2 เมตร/วินาที²"]', '3', 'a = (v - u)/t = (10 - 0)/5 = 2 เมตร/วินาที² อย่าลืมหารด้วยเวลา', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-acceleration')), 'choice', 'เมื่อรถเบรกจนช้าลง ความเร่งมีทิศทางใดเมื่อเทียบกับทิศเคลื่อนที่', '["เดียวกับทิศการเคลื่อนที่","ตั้งฉากกับการเคลื่อนที่","เป็นศูนย์เสมอ","ตรงข้ามกับทิศการเคลื่อนที่"]', '0', 'เมื่อความเร็วลดลง ความเร่งมีทิศตรงข้ามกับการเคลื่อนที่ ถ้าเดียวกับการเคลื่อนที่ความเร็วจะเพิ่มขึ้น', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-acceleration')), 'number', 'รถเคลื่อนที่จากความเร็ว 4 เมตร/วินาทีเป็น 10 เมตร/วินาทีในเวลา 3 วินาที ความเร่งเป็นเท่าใด (ตอบเป็นเมตร/วินาที² จำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'a = (v - u)/t = (10 - 4)/3 = 2 เมตร/วินาที²', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-acceleration')), 'number', 'วัตถุเริ่มจากหยุดนิ่งมีความเร่ง 4 เมตร/วินาที² หลังจาก 5 วินาที ความเร็วเป็นเท่าใด (ตอบเป็นเมตร/วินาที จำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', 'v = u + at = 0 + 4 x 5 = 20 เมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-forces-motion'), 'jr-forces-motion-force-effects', 'แรงและผลของแรง', 'แรงคือการดึงหรือผลักที่กระทำต่อวัตถุ มีหน่วยเป็นนิวตัน ผลของแรงทำให้วัตถุเปลี่ยนความเร็วหรือเปลี่ยนรูปร่าง', 'junior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
