INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction'), 'youtube', 'https://www.youtube.com/watch?v=OOMb6NAJ0IA', 'OOMb6NAJ0IA', 'สอนศาสตร์ ฟิสิกส์ ม.ต้น | พี่ลูกตาล : แรงในชีวิตประจำวัน ตอนที่ 2', 'TruePlookpanya Channel', 'https://www.youtube.com/channel/UCjj4VB9nW0zN5reBS0cIf6A', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction'), 'แบบทดสอบ: แรงเสียดทาน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction')), 'choice', 'แรงเสียดทานมีทิศทางใดเมื่อเทียบกับการเคลื่อนที่ของวัตถุ', '["เดียวกับทิศการเคลื่อนที่","ตั้งฉากกับการเคลื่อนที่","ไม่มีทิศทางที่แน่นอน","ตรงข้ามกับทิศการเคลื่อนที่"]', '3', 'แรงเสียดทานต้านการเคลื่อนที่ จึงมีทิศตรงข้ามกับทิศการเคลื่อนที่ของวัตถุ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction')), 'choice', 'ข้อใดทำให้แรงเสียดทานมีค่ามากขึ้น', '["ผิวสัมผัสขรุขระมากขึ้น","ทำให้วัตถุหนักน้อยลง","ลดแรงกดของวัตถุต่อพื้น","ทำให้ผิวสัมผัสลื่นขึ้น"]', '0', 'แรงเสียดทานเพิ่มขึ้นเมื่อผิวขรุขระหรือแรงกดตั้งฉากมากขึ้น การทำให้ลื่นหรือเบาลงจะลดแรงเสียดทาน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction')), 'choice', 'เมื่อผลักกล่องบนพื้นขรุขระ แรงเสียดทานกระทำต่อกล่องอย่างไร', '["ช่วยผลักกล่องไปข้างหน้า","ต้านการไถลของกล่อง","เพิ่มความเร็วให้กล่อง","ไม่มีผลต่อการเคลื่อนที่"]', '1', 'แรงเสียดทานต้านการไถลของกล่อง ทำให้กล่องเคลื่อนที่ช้าลง ไม่ใช่ช่วยผลัก', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction')), 'number', 'มีแรงขับ 14 นิวตันไปข้างหน้า ขณะที่แรงเสียดทาน 6 นิวตันต้าน แรงลัพธ์มีขนาดเท่าใด (ตอบเป็นนิวตัน จำนวนเต็ม)', NULL, '{"value":8,"tolerance":0.5}', 'แรงเสียดทานตรงข้ามกับแรงขับ แรงลัพธ์ = 14 - 6 = 8 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction')), 'number', 'มีแรงขับ 20 นิวตันและแรงเสียดทาน 5 นิวตัน กล่องมวล 5 กิโลกรัมมีความเร่งเท่าใด (ตอบเป็นเมตร/วินาที² จำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'แรงลัพธ์ = 20 - 5 = 15 นิวตัน แล้ว a = F/m = 15 / 5 = 3 เมตร/วินาที²', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-forces-motion'), 'jr-forces-motion-net-force', 'แรงลัพธ์และการรวมแรง', 'แรงลัพธ์คือแรงรวมของทุกแรงที่กระทำต่อวัตถุ แรงที่ไปทางเดียวกันรวมกัน ส่วนแรงที่ตรงข้ามกันหักล้างกัน', 'junior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
