INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-heat-temperature'), 'แบบทดสอบ: ความร้อนและอุณหภูมิ', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-temperature')), 'choice', 'อุณหภูมิคือปริมาณใด', '["ค่าที่บอกระดับความร้อนหรือเย็นของวัตถุ","ปริมาณความร้อนทั้งหมดที่วัตถุมีอยู่","การสั่นสะเทือนของโมเลกุลภายในวัตถุ","พลังงานความร้อนรวมของทั้งวัตถุ"]', '0', 'อุณหภูมิบอกระดับความร้อนหรือเย็น ใช้วัดด้วยเทอร์โมมิเตอร์ ส่วนความร้อนเป็นพลังงานที่ถ่ายโอน ซึ่งต่างกันแม้ว่ามักใช้คู่กัน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-temperature')), 'choice', 'ความร้อนคือปริมาณใด', '["ระดับความร้อนของวัตถุ","พลังงานความร้อนที่ถ่ายโอนจากที่ร้อนไปยังที่เย็น","หน่วยในการวัดอุณหภูมิ","อุณหภูมิสูงสุดที่วัตถุรับได้"]', '1', 'ความร้อนคือพลังงานที่ถ่ายโอนระหว่างวัตถุที่มีอุณหภูมิต่างกัน จากที่ร้อนไปสู่ที่เย็น ไม่ใช่ค่าที่วัดระดับความร้อนโดยตรง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-temperature')), 'choice', 'วางแก้วน้ำร้อนแตะกับแก้วน้ำเย็น ความร้อนจะถ่ายโอนอย่างไร', '["จากน้ำเย็นไปยังน้ำร้อน","ไม่มีการถ่ายโอนความร้อน","ถ่ายโอนไปทั้งสองทางเท่ากัน","จากน้ำร้อนไปยังน้ำเย็น"]', '3', 'ความร้อนไหลจากวัตถุที่ร้อนกว่าไปยังวัตถุที่เย็นกว่าเสมอ จนกระทั่งอุณหภูมิทั้งสองเท่ากัน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-temperature')), 'number', 'อุณหภูมิเพิ่มขึ้นจาก 20 องศาเซลเซียส เป็น 45 องศาเซลเซียส อุณหภูมิเพิ่มขึ้นทั้งหมดกี่องศาเซลเซียส (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":25,"tolerance":0.5}', 'อุณหภูมิที่เพิ่มขึ้น = 45 − 20 = 25 องศาเซลเซียส', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-temperature')), 'number', 'น้ำมวล 1 กิโลกรัมมีอุณหภูมิ 30 องศาเซลเซียส รับความร้อนจนอุณหภูมิเป็น 50 องศาเซลเซียส อุณหภูมิเพิ่มขึ้นกี่องศาเซลเซียส (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', 'อุณหภูมิที่เพิ่มขึ้น = 50 − 30 = 20 องศาเซลเซียส ไม่ขึ้นกับมวลของน้ำ', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-heat'), 'jr-heat-transfer', 'การถ่ายโอนความร้อน (การนำ พา แผ่รังสี)', 'ความร้อนถ่ายโอนได้สามวิธี คือการนำผ่านของแข็ง การพาในของเหลวและก๊าซ และการแผ่รังสีที่ผ่านสุญญากาศได้ เช่น ความร้อนจากดวงอาทิตย์', 'junior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
