INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-light-lenses-mirrors'), 'แบบทดสอบ: เลนส์และกระจก', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-lenses-mirrors')), 'choice', 'เลนส์นูนใช้เป็นแว่นขยาย เมื่อมองวัตถุที่อยู่ใกล้เลนส์ ภาพที่เห็นเป็นอย่างไร', '["ภาพจริงหัวกลับ","ภาพขนาดเท่าวัตถุ","ภาพเสมือนหัวตั้งและใหญ่กว่าวัตถุ","ภาพเสมือนหัวกลับ"]', '2', 'เลนส์นูนใช้เป็นแว่นขยาย เมื่อวางวัตถุใกล้เลนส์กว่าจุดโฟกัส จะได้ภาพเสมือนหัวตั้งและใหญ่กว่าวัตถุ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-lenses-mirrors')), 'choice', 'ภาพของคนที่มองจากกระจกเงาราบเป็นภาพแบบใด', '["ภาพเสมือน หัวตั้ง ขนาดเท่าวัตถุ","ภาพจริงหัวกลับ","ภาพเล็กกว่าวัตถุเสมอ","ไม่มีภาพเกิดขึ้น"]', '0', 'กระจกเงาราบให้ภาพเสมือน หัวตั้ง มีขนาดเท่าวัตถุ และซ้ายขวาสลับกัน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-lenses-mirrors')), 'choice', 'เลนส์เว้า (เลนส์กระจายแสง) มีลักษณะสำคัญอย่างไร', '["ตรงกลางหนากว่าขอบ","ไม่ทำให้แสงหักเหเลย","รวมแสงเข้ามาที่จุดเดียว","ตรงกลางบางกว่าขอบ"]', '3', 'เลนส์เว้าตรงกลางบางกว่าขอบ ทำให้แสงที่ผ่านหักเหกระจายออกจากกัน จึงเรียกว่าเลนส์กระจายแสง', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-lenses-mirrors')), 'number', 'แว่นขยายมีกำลังขยาย 2 เท่า เมื่อมองมดที่ยาว 1 เซนติเมตร ภาพของมดที่เห็นยาวกี่เซนติเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'กำลังขยาย = ความสูงภาพ ÷ ความสูงวัตถุ ดังนั้นความสูงภาพ = 2 × 1 = 2 เซนติเมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-lenses-mirrors')), 'number', 'ภาพจากเลนส์นูนสูง 8 เซนติเมตร เกิดจากวัตถุสูง 4 เซนติเมตร กำลังขยายของเลนส์เท่ากับเท่าใด (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'กำลังขยาย = ความสูงภาพ ÷ ความสูงวัตถุ = 8 ÷ 4 = 2 เท่า', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-light'), 'jr-light-reflection', 'การสะท้อนของแสง', 'เมื่อแสงตกกระทบผิวสะท้อน มุมตกกระทบจะเท่ากับมุมสะท้อนเสมอ โดยวัดจากเส้นปกติ ภาพจากกระจกเงาราบเป็นภาพเสมือนหัวตั้งและซ้ายขวาสลับกัน', 'junior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
