INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-sources-propagation')), 'choice', 'ข้อใดเป็นแหล่งกำเนิดแสง', '["ดวงจันทร์","กระจกเงา","หนังสือเรียน","ดวงอาทิตย์"]', '3', 'ดวงอาทิตย์เป็นแหล่งกำเนิดแสงที่เปล่งแสงเอง ส่วนดวงจันทร์ กระจก และหนังสือเป็นเพียงวัตถุที่สะท้อนแสงจากแหล่งอื่น', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-sources-propagation')), 'choice', 'แสงเดินทางในตัวกลางโปร่งใสชนิดเดียวกันได้อย่างไร (โดยประมาณ)', '["เดินทางเป็นเส้นโค้ง","เดินทางเป็นเส้นตรง","เดินทางเป็นวงกลม","หยุดนิ่งไม่เคลื่อนที่"]', '1', 'แสงเดินทางเป็นเส้นตรงในตัวกลางโปร่งใสเดียวกัน ถ้าตัวกลางต่างกันหรืองอไปตามสภาพ แสงอาจหักเหหรือโค้งได้', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-sources-propagation')), 'choice', 'เมื่อแสงตกกระทบวัตถุทึบแสง เกิดเงาที่ด้านตรงข้าม เพราะเหตุใด', '["แสงเดินทางเป็นเส้นตรง จึงอ้อมผ่านวัตถุทึบไม่ได้","แสงสะท้อนจากวัตถุทึบทั้งหมด","แสงหักเหเมื่อผ่านวัตถุทึบ","แสงมีหลายสี"]', '0', 'เพราะแสงเดินทางเป็นเส้นตรง จึงไม่อ้อมผ่านวัตถุทึบแสง ด้านตรงข้ามจึงไม่มีแสงตกถึงและเกิดเงา', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-sources-propagation')), 'number', 'แสงจากดวงอาทิตย์เดินทางมายังโลกด้วยอัตราเร็ว 300000 กิโลเมตร/วินาที และใช้เวลาประมาณ 500 วินาที ระยะทางจากโลกถึงดวงอาทิตย์ประมาณกี่กิโลเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":150000000,"tolerance":0.5}', 'ระยะทาง = อัตราเร็ว × เวลา = 300000 × 500 = 150000000 กิโลเมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-sources-propagation')), 'number', 'แสงเดินทางด้วยอัตราเร็ว 300000 กิโลเมตร/วินาที ถ้าระยะทางจากโลกถึงดวงอาทิตย์เป็น 150000000 กิโลเมตร แสงใช้เวลาเดินทางกี่วินาที (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":500,"tolerance":0.5}', 'เวลา = ระยะทาง ÷ อัตราเร็ว = 150000000 ÷ 300000 = 500 วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-magnetism'), 'jr-magnetism-electromagnet', 'แม่เหล็กไฟฟ้าและการใช้ประโยชน์', 'แม่เหล็กไฟฟ้าเกิดจากกระแสไฟฟ้าไหลผ่านขดลวดที่พันรอบแกนเหล็ก ยิ่งเพิ่มจำนวนรอบหรือเพิ่มกระแสยิ่งแม่เหล็กแรงขึ้น นำไปใช้ในกระดิ่งไฟฟ้าและรถเครนยกเหล็ก', 'junior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
