INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-magnetism-electromagnet'), 'แบบทดสอบ: แม่เหล็กไฟฟ้าและการใช้ประโยชน์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-electromagnet')), 'choice', 'แม่เหล็กไฟฟ้าเกิดขึ้นจากหลักการใด', '["การถูแม่เหล็กซ้ำๆ หลายครั้ง","การให้ความร้อนแก่แม่เหล็กถาวร","กระแสไฟฟ้าไหลผ่านขดลวดที่พันรอบแกนเหล็ก","การผสมโลหะชนิดต่างๆ เข้าด้วยกัน"]', '2', 'เมื่อกระแสไฟฟ้าไหลผ่านขดลวดที่พันรอบแกนเหล็ก จะเกิดสนามแม่เหล็กขึ้นบริเวณโดยรอบ เรียกว่าแม่เหล็กไฟฟ้า', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-electromagnet')), 'choice', 'จะทำให้แม่เหล็กไฟฟ้าแรงขึ้นได้อย่างไร', '["ลดจำนวนรอบของขดลวด","เพิ่มจำนวนรอบของขดลวดหรือเพิ่มกระแสไฟฟ้า","ใช้แกนพลาสติกแทนแกนเหล็ก","ลดกระแสไฟฟ้าที่ไหลผ่าน"]', '1', 'ความแรงของแม่เหล็กไฟฟ้าเพิ่มขึ้นเมื่อมีจำนวนรอบของขดลวดมากขึ้นหรือกระแสไฟฟ้ามากขึ้น และใช้แกนเหล็กช่วยรวมสนาม', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-electromagnet')), 'choice', 'ข้อใดเป็นการใช้ประโยชน์จากแม่เหล็กไฟฟ้า', '["เข็มทิศ","แม่เหล็กติดตู้เย็น","หินแม่เหล็กธรรมชาติ","กระดิ่งไฟฟ้า ลำโพง และรถเครนยกเหล็ก"]', '3', 'แม่เหล็กไฟฟ้าที่เปิดปิดได้ตามกระแส นำไปใช้ในกระดิ่งไฟฟ้า ลำโพง และรถเครนยกเหล็ก ซึ่งต่างจากแม่เหล็กถาวรที่เปิดปิดไม่ได้', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-electromagnet')), 'number', 'ขดลวดของแม่เหล็กไฟฟ้ามี 50 รอบ เพิ่มเป็น 100 รอบโดยกระแสคงที่ ความแรงของแม่เหล็กไฟฟ้าเพิ่มขึ้นเป็นกี่เท่า (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'จำนวนรอบเพิ่มเป็น 100 ÷ 50 = 2 เท่า ความแรงของแม่เหล็กไฟฟ้าจึงเพิ่มประมาณ 2 เท่า', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-electromagnet')), 'number', 'เพิ่มกระแสไฟฟ้าจาก 1 แอมแปร์เป็น 3 แอมแปร์โดยจำนวนรอบคงที่ ความแรงของแม่เหล็กไฟฟ้าเพิ่มขึ้นเป็นกี่เท่า (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'กระแสเพิ่มจาก 1 เป็น 3 ต่อ 1 = 3 เท่า ความแรงของแม่เหล็กไฟฟ้าจึงเพิ่มประมาณ 3 เท่า', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-magnetism'), 'jr-magnetism-magnetic-field', 'สนามแม่เหล็ก', 'สนามแม่เหล็กคือบริเวณรอบแม่เหล็กที่มีแรงแม่เหล็กกระทำต่อวัตถุแม่เหล็ก เส้นแรงแม่เหล็กหนาแน่นที่สุดที่ขั้ว และมีทิศจากเหนือไปใต้ภายนอกแท่ง', 'junior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
