INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-properties')), 'choice', 'แม่เหล็กมีขั้วทั้งหมดกี่ขั้ว และเรียกว่าอะไร', '["2 ขั้ว คือขั้วเหนือและขั้วใต้","1 ขั้ว คือขั้วเดียวเท่านั้น","3 ขั้ว คือ เหนือ ใต้ และกลาง","4 ขั้ว คือสองขั้วแต่ละด้าน"]', '0', 'แม่เหล็กทุกแท่งมีสองขั้วเสมอ คือขั้วเหนือ (N) และขั้วใต้ (S) แม้จะหักออกเป็นชิ้นก็ยังมีสองขั้วในทุกชิ้น', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-properties')), 'choice', 'นำขั้วแม่เหล็กชนิดเดียวกันมาใกล้กัน จะเกิดอะไร', '["ดูดกัน","ไม่ทำปฏิกิริยากัน","ผลักกัน","ดูดแล้วผลักสลับกัน"]', '2', 'ขั้วชนิดเดียวกัน เช่น เหนือกับเหนือ หรือใต้กับใต้ จะผลักกัน ส่วนขั้วต่างชนิดกันจะดูดกัน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-properties')), 'choice', 'วัสดุในข้อใดถูกแม่เหล็กดูดได้', '["ทองแดง","แก้ว","พลาสติก","เหล็ก"]', '3', 'แม่เหล็กดูดวัสดุที่เป็นเหล็ก (และโลหะแม่เหล็กบางชนิด) ส่วนทองแดง แก้ว และพลาสติกไม่ถูกดูด', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-properties')), 'number', 'แม่เหล็กแท่งหนึ่งถูกหักออกเป็น 2 ชิ้น แต่ละชิ้นยังเป็นแม่เหล็กมี 2 ขั้ว ขั้วแม่เหล็กทั้งหมดจาก 2 ชิ้นรวมกันมีกี่ขั้ว (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 'ชิ้นละ 2 ขั้ว จำนวน 2 ชิ้นรวมเป็น 4 ขั้ว เพราะแม่เหล็กแต่ละชิ้นมีขั้วเหนือและขั้วใต้ครบเสมอ', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-properties')), 'number', 'แม่เหล็กยาวหนึ่งแท่งถูกตัดเป็น 3 ชิ้นเท่ากัน แต่ละชิ้นมี 2 ขั้ว ขั้วแม่เหล็กทั้งหมดรวมกันมีกี่ขั้ว (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":6,"tolerance":0.5}', 'ชิ้นละ 2 ขั้ว จำนวน 3 ชิ้นรวมเป็น 6 ขั้ว การหักตัดแม่เหล็กไม่ได้ทำให้ขาดเสียขั้วไป', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-pressure-fluids'), 'jr-pressure-fluids-buoyancy', 'แรงลอยตัวและหลักของอาร์คิมิดีส', 'ของเหลวหรือก๊าซดันวัตถุที่แช่อยู่ให้ลอยขึ้นด้วยแรงลอยตัว ซึ่งเท่ากับน้ำหนักของของเหลวที่ถูกแทนที่ตามหลักของอาร์คิมิดีส', 'junior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
