INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-buoyancy'), 'แบบทดสอบ: แรงลอยตัวและหลักของอาร์คิมิดีส', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-buoyancy')), 'choice', 'แรงลอยตัว (แรงพยุง) คือแรงที่', '["ของแข็งดันของเหลวให้สูงขึ้น","ของเหลวหรือก๊าซดันวัตถุที่แช่อยู่ให้ลอยขึ้น","แรงโน้มถ่วงดึงวัตถุลงสู่พื้น","แรงเสียดทานระหว่างผิววัตถุกับของเหลว"]', '1', 'แรงลอยตัวเป็นแรงจากของไหลที่ดันวัตถุขึ้นในทิศตรงข้ามกับน้ำหนัก ทำให้วัตถุลอยหรือเบาลงเมื่ออยู่ในน้ำ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-buoyancy')), 'choice', 'ตามหลักของอาร์คิมิดีส แรงลอยตัวที่กระทำต่อวัตถุที่แช่ในของเหลวมีค่าเท่ากับข้อใด', '["น้ำหนักของของเหลวที่ถูกแทนที่","น้ำหนักของวัตถุเสมอ","ความหนาแน่นของวัตถุ","ปริมาตรรวมของของเหลวทั้งก้อน"]', '0', 'แรงลอยตัวเท่ากับน้ำหนักของของเหลวที่ถูกแทนที่ด้วยส่วนที่จมของวัตถุ นี่คือหลักของอาร์คิมิดีส', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-buoyancy')), 'choice', 'วัตถุที่จะลอยน้ำได้ ต้องมีสมบัติตามข้อใด', '["ความหนาแน่นมากกว่าน้ำ","มีน้ำหนักมาก","ความหนาแน่นน้อยกว่าน้ำ","มีขนาดเล็กมาก"]', '2', 'วัตถุที่มีความหนาแน่นน้อยกว่าน้ำจะมีแรงลอยตัวมากกว่าน้ำหนัก จึงลอยได้ ส่วนวัตถุหนาแน่นกว่าน้ำจะจม', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-buoyancy')), 'number', 'ก้อนหินปริมาตร 0.2 ลูกบาศก์เมตรแช่อยู่ในน้ำ (ความหนาแน่นน้ำ 1000 กิโลกรัม/ลูกบาศก์เมตร) แรงลอยตัวที่กระทำต่อหินเท่ากับกี่นิวตัน (ใช้ g = 10 เมตร/วินาที² ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2000,"tolerance":0.5}', 'แรงลอยตัว = น้ำหนักของน้ำที่ถูกแทนที่ = ρVg = 1000 × 0.2 × 10 = 2000 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-buoyancy')), 'number', 'วัตถุชิ้นหนึ่งแทนที่น้ำได้ 3 นิวตัน แรงลอยตัวที่กระทำต่อวัตถุเท่ากับกี่นิวตัน (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'ตามหลักของอาร์คิมิดีส แรงลอยตัวเท่ากับน้ำหนักของของเหลวที่ถูกแทนที่ ซึ่งเท่ากับ 3 นิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-pressure-fluids'), 'jr-pressure-fluids-liquid-pressure', 'ความดันในของเหลว', 'ความดันในของเหลวเพิ่มขึ้นตามความลึก และขึ้นกับความหนาแน่นของของเหลว ยิ่งดำน้ำลึกหรือฐานเขื่อนยิ่งลึก ความดันยิ่งมาก', 'junior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-liquid-pressure'), 'youtube', 'https://www.youtube.com/watch?v=bQUAC7CjS-0', 'bQUAC7CjS-0', 'แรงและความดันของของเหลว (วิทยาศาสตร์ ม. 2 เล่ม 1 หน่วยที่ 4 บทที่ 2 แรง)', 'Proj14 ม.2', 'https://www.youtube.com/channel/UCkGQRzlwZFWkOin9SiP7JUQ', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-liquid-pressure'), 'แบบทดสอบ: ความดันในของเหลว', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-liquid-pressure')), 'choice', 'ความดันภายในของเหลวที่จุดใดจุดหนึ่งขึ้นกับข้อใดเป็นหลัก', '["ขนาดของภาชนะเท่านั้น","ปริมาตรทั้งหมดของของเหลวเท่านั้น","ความลึกและความหนาแน่นของของเหลว รวมทั้งค่า g","รูปร่างของภาชนะ"]', '2', 'ความดันในของเหลวคำนวณจาก P = ρgh จึงขึ้นกับความหนาแน่น ความลึก และค่า g ไม่ขึ้นกับรูปร่างของภาชนะ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-liquid-pressure')), 'choice', 'เมื่อดำน้ำลึกลงไป ความดันที่หูได้รับจะเปลี่ยนแปลงอย่างไร', '["ลดลง","เพิ่มขึ้น","เท่าเดิม","หายไป"]', '1', 'ยิ่งลึกลงไป ความดันของน้ำยิ่งมาก เพราะมีน้ำกดทับมากขึ้นตามความลึกที่มากขึ้น', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-liquid-pressure')), 'choice', 'เขื่อนที่กั้นน้ำต้องสร้างฐานให้หนาและแข็งแรง เพราะเหตุใด', '["ฐานของเขื่อนต้องจมอยู่ในน้ำเสมอ","ความดันของน้ำที่ระดับผิวน้ำมีค่ามากที่สุด","ช่วยลดการระเหยของน้ำในเขื่อน","ความดันของน้ำเพิ่มขึ้นตามความลึก ฐานจึงต้องรับแรงมากที่สุด"]', '3', 'ความดันของน้ำเพิ่มขึ้นตามความลึก จุดลึกที่สุดอยู่ที่ฐานเขื่อนจึงต้องรับแรงมากที่สุด ต้องสร้างฐานให้หนาเพื่อความแข็งแรง', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-liquid-pressure')), 'number', 'ของเหลวมีความหนาแน่น 1000 กิโลกรัม/ลูกบาศก์เมตร ณ ความลึก 0.5 เมตร ความดันของของเหลวเท่ากับกี่พาสคัล (ใช้ g = 10 เมตร/วินาที² ตอบเป็นจำนวนเต็ม)', NULL, '{"value":5000,"tolerance":0.5}', 'P = ρgh = 1000 × 10 × 0.5 = 5000 พาสคัล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-liquid-pressure')), 'number', 'ของเหลวความหนาแน่น 1000 กิโลกรัม/ลูกบาศก์เมตร ณ ความลึก 2 เมตร ความดันของของเหลวเท่ากับกี่พาสคัล (ใช้ g = 10 เมตร/วินาที² ตอบเป็นจำนวนเต็ม)', NULL, '{"value":20000,"tolerance":0.5}', 'P = ρgh = 1000 × 10 × 2 = 20000 พาสคัล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-pressure-fluids'), 'jr-pressure-fluids-pascal-atmosphere', 'หลักของพาสคัลและความดันบรรยากาศ', 'ความดันที่เพิ่มขึ้นในของเหลวที่ปิดสนิทจะถ่ายทอดไปทุกทิศทุกทางเท่ากัน ใช้ในแม่แรงไฮดรอลิก ส่วนความดันบรรยากาศเกิดจากน้ำหนักของอากาศกดลงมา', 'junior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pascal-atmosphere'), 'youtube', 'https://www.youtube.com/watch?v=gxMPoyhqo3Q', 'gxMPoyhqo3Q', 'I know PHYSICS ep.14 - ของไหล (Part 3.1 : กฎของปาสคาล และ แรงลอยตัว)', 'I know PHYSICs a little', 'https://www.youtube.com/channel/UC0qWWV4YLpxnAQGJ8ednXlA', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pascal-atmosphere'), 'แบบทดสอบ: หลักของพาสคัลและความดันบรรยากาศ', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pascal-atmosphere')), 'choice', 'หลักของพาสคัลกล่าวว่า เมื่อกดของเหลวในภาชนะปิดสนิท ความดันที่เพิ่มขึ้นจะ', '["เกิดขึ้นเฉพาะจุดที่กดเท่านั้น","เกิดขึ้นเฉพาะที่ก้นภาชนะ","ลดลงตามระยะทางที่ไกลออกไป","ถ่ายทอดไปทุกทิศทุกทางด้วยขนาดเท่ากัน"]', '3', 'ความดันที่เพิ่มขึ้นในของเหลวที่ปิดสนิทถ่ายทอดเท่ากันทุกทิศทุกทาง จึงใช้หลักการนี้ในแม่แรงไฮดรอลิก', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pascal-atmosphere')), 'choice', 'อุปกรณ์ในข้อใดใช้หลักของพาสคัล', '["บันไดเลื่อน","พัดลม","แม่แรงไฮดรอลิก","ถังเก็บน้ำ"]', '2', 'แม่แรงไฮดรอลิกใช้หลักของพาสคัล ออกแรงเล็กที่ลูกสูบเล็ก แล้วความดันถ่ายทอดไปดันลูกสูบใหญ่ให้เกิดแรงมาก', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pascal-atmosphere')), 'choice', 'ความดันบรรยากาศเกิดจากสาเหตุใด', '["น้ำหนักของอากาศกดลงบนพื้นโลก","แสงจากดวงอาทิตย์","แรงดึงดูดของดวงจันทร์","การหมุนรอบตัวเองของโลก"]', '0', 'อากาศมีน้ำหนักและกดทับทุกสิ่งที่อยู่ใต้ชั้นบรรยากาศ ทำให้เกิดความดันบรรยากาศที่กระทำต่อวัตถุทุกด้าน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pascal-atmosphere')), 'number', 'แม่แรงไฮดรอลิกมีพื้นที่ลูกสูบเล็ก 0.02 ตารางเมตร ออกแรงกด 40 นิวตัน ความดันที่เกิดขึ้นในของเหลวเท่ากับกี่พาสคัล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2000,"tolerance":0.5}', 'P = F / A = 40 ÷ 0.02 = 2000 พาสคัล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pascal-atmosphere')), 'number', 'ความดันในระบบไฮดรอลิก 500 พาสคัล กระทำบนพื้นที่ลูกสูบใหญ่ 0.1 ตารางเมตร จะเกิดแรงดันเท่ากับกี่นิวตัน (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":50,"tolerance":0.5}', 'F = P × A = 500 × 0.1 = 50 นิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-pressure-fluids'), 'jr-pressure-fluids-pressure', 'ความดัน', 'ความดันคือแรงที่กระทำตั้งฉากต่อพื้นที่หนึ่งหน่วย ความดันเพิ่มขึ้นเมื่อแรงมากขึ้น หรือพื้นที่สัมผัสเล็กลง มีหน่วยเป็นพาสคัล', 'junior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
