INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pressure'), 'แบบทดสอบ: ความดัน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pressure')), 'choice', 'ความดันคือปริมาณใด', '["แรงที่กระทำตั้งฉากต่อพื้นที่หนึ่งหน่วย","แรงรวมทั้งหมดที่กระทำต่อวัตถุ","มวลต่อหนึ่งหน่วยปริมาตร","ระยะทางที่แรงกระทำไปได้"]', '0', 'ความดัน P = F / A คือแรงตั้งฉากต่อพื้นที่หนึ่งหน่วย ยิ่งแรงมากหรือพื้นที่น้อย ความดันยิ่งสูง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pressure')), 'choice', 'ออกแรงเท่าเดิมแต่เพิ่มพื้นที่สัมผัส ความดันจะเปลี่ยนแปลงอย่างไร', '["เพิ่มขึ้น","เท่าเดิม","เพิ่มขึ้นเป็นสองเท่า","ลดลง"]', '3', 'จาก P = F / A เมื่อพื้นที่ A มากขึ้นโดยแรง F คงที่ ความดันจึงลดลง เช่น คนเดินบนหิมะหรือทรายจะจมน้อยกว่าเมื่อสวมรองเท้ากว้าง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pressure')), 'choice', 'หน่วยของความดันในระบบ SI คือข้อใด', '["นิวตัน (N)","พาสคัล (Pa)","จูล (J)","วัตต์ (W)"]', '1', 'ความดันมีหน่วยเป็นพาสคัล โดย 1 พาสคัลเท่ากับแรง 1 นิวตันต่อพื้นที่ 1 ตารางเมตร', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pressure')), 'number', 'ออกแรง 100 นิวตันกดตั้งฉากบนพื้นที่ 2 ตารางเมตร ความดันเท่ากับกี่พาสคัล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":50,"tolerance":0.5}', 'P = F / A = 100 ÷ 2 = 50 พาสคัล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pressure')), 'number', 'ออกแรง 60 นิวตันกดตั้งฉากบนพื้นที่ 3 ตารางเมตร ความดันเท่ากับกี่พาสคัล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', 'P = F / A = 60 ÷ 3 = 20 พาสคัล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-sound'), 'jr-sound-echo-hearing', 'เสียงสะท้อนและการได้ยิน', 'เสียงสะท้อนเกิดจากเสียงสะท้อนกลับมาถึงผู้ฟังจากผิวสะท้อน ใช้ประโยชน์ในการวัดระยะทาง เช่น โซนาร์วัดความลึกทะเล', 'junior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
