INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-frequency-amplitude')), 'choice', 'ความถี่ของเสียงสัมพันธ์กับสมบัติของเสียงข้อใด', '["ความดัง","ระดับเสียงสูง-ต่ำ","คุณภาพของเสียง","ทิศทางการเคลื่อนที่"]', '1', 'ความถี่สูง เสียงแหลม (เสียงสูง) ความถี่ต่ำ เสียงทุ้ม (เสียงต่ำ) ความถี่จึงกำหนดระดับเสียง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-frequency-amplitude')), 'choice', 'ความดังของเสียงขึ้นกับปริมาณใดเป็นหลัก', '["แอมพลิจูดของการสั่น","ความถี่เท่านั้น","ความยาวคลื่นเท่านั้น","ทิศทางของเสียง"]', '0', 'แอมพลิจูดมาก เสียงดังมาก แอมพลิจูดน้อย เสียงเบา แอมพลิจูดจึงกำหนดความดัง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-frequency-amplitude')), 'choice', 'เสียงที่มีความถี่สูงกว่าจะมีลักษณะอย่างไร', '["ดังกว่า","เบากว่า","ก้องกว่า","แหลมหรือสูงกว่า"]', '3', 'ความถี่สูงหมายถึงการสั่นครบรอบจำนวนมากในหนึ่งหน่วยเวลา ทำให้เสียงแหลมหรือสูงกว่า', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-frequency-amplitude')), 'number', 'คลื่นเสียงครบ 3 ลูกคลื่นในเวลา 1 วินาที ความถี่ของคลื่นเท่ากับกี่เฮิรตซ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'ความถี่คือจำนวนรอบต่อวินาที = 3 รอบ ÷ 1 วินาที = 3 เฮิรตซ์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-frequency-amplitude')), 'number', 'ถ้าเสียงมีความถี่ 60 เฮิรตซ์ แปลว่าในเวลา 1 วินาทีเสียงสั่นครบกี่รอบ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":60,"tolerance":0.5}', '1 เฮิรตซ์เท่ากับการสั่น 1 รอบต่อวินาที ความถี่ 60 เฮิรตซ์จึงสั่น 60 รอบต่อวินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-sound'), 'jr-sound-production-propagation', 'การเกิดและการเคลื่อนที่ของเสียง', 'เสียงเกิดจากการสั่นสะเทือนของวัตถุและต้องอาศัยตัวกลางในการเดินทาง เสียงเดินทางผ่านของแข็งได้ดีที่สุดและไม่สามารถเดินทางในสุญญากาศได้', 'junior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
