INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-production-propagation')), 'choice', 'เสียงเกิดขึ้นจากสาเหตุใด', '["การสั่นสะเทือนของแหล่งกำเนิดเสียง","การไหลของอากาศอย่างเดียว","แสงที่มากระทบวัตถุ","การหมุนของโลก"]', '0', 'เสียงเกิดจากการสั่นสะเทือนของวัตถุ แล้วสั่นถ่ายทอดผ่านตัวกลางไปยังหู เช่น สายกีตาร์สั่นสะเทือนเมื่อดีด', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-production-propagation')), 'choice', 'เสียงเดินทางผ่านตัวกลางชนิดใดได้ดีที่สุด', '["สุญญากาศ","อากาศที่บางมาก","ของแข็ง","เสียงไม่ต้องใช้ตัวกลาง"]', '2', 'เสียงเดินทางผ่านของแข็งได้ดีที่สุด เพราะอนุภาคอยู่ชิดกันถ่ายทอดการสั่นได้ดี อัตราเร็วเสียงในของแข็งจึงสูงที่สุด', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-production-propagation')), 'choice', 'เสียงไม่สามารถเดินทางในสุญญากาศได้ เพราะเหตุใด', '["แสงบังการเคลื่อนที่ของเสียง","สุญญากาศมีอุณหภูมิสูงเกินไป","ความดันในสุญญากาศสูงเกินไป","ไม่มีตัวกลางให้การสั่นถ่ายทอด"]', '3', 'เสียงต้องอาศัยตัวกลางในการสั่นถ่ายทอด ในสุญญากาศไม่มีอนุภาคให้สั่นต่อกัน เสียงจึงเดินทางไม่ได้', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-production-propagation')), 'number', 'เสียงเดินทางในอากาศด้วยอัตราเร็วประมาณ 340 เมตร/วินาที ถ้าได้ยินเสียงฟ้าร้องหลังเห็นฟ้าแลบ 3 วินาที ฟ้าผ่าอยู่ห่างประมาณกี่เมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":1020,"tolerance":0.5}', 'ระยะทาง = อัตราเร็ว × เวลา = 340 × 3 = 1020 เมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-production-propagation')), 'number', 'เสียงเดินทางในอากาศได้ระยะ 680 เมตรในเวลา 2 วินาที อัตราเร็วของเสียงเท่ากับกี่เมตร/วินาที (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":340,"tolerance":0.5}', 'อัตราเร็ว = ระยะทาง ÷ เวลา = 680 ÷ 2 = 340 เมตร/วินาที', 5);
