INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-conservation')), 'choice', 'กฎการอนุรักษ์พลังงานกล่าวว่าอย่างไร', '["พลังงานไม่สูญหายและไม่เกิดขึ้นใหม่ แต่เปลี่ยนรูปไปได้","พลังงานถูกสร้างขึ้นมาใหม่ได้เสมอ","พลังงานทั้งหมดจะหายไปเมื่อทำงาน","พลังงานไม่สามารถเปลี่ยนรูปได้"]', '0', 'พลังงานรวมของระบบคงที่ เพียงเปลี่ยนรูปไปมา พลังงานจลน์อาจเปลี่ยนเป็นพลังงานศักย์ พลังงานความร้อน หรือพลังงานรูปอื่นได้', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-conservation')), 'choice', 'ลูกตุ้มแกว่งจากจุดสูงสุด จุดใดมีพลังงานจลน์มากที่สุด', '["จุดสูงสุดทั้งสองด้าน","ทุกจุดเท่ากัน","จุดต่ำสุด (จุดศูนย์กลางการแกว่ง)","จุดเริ่มต้น"]', '2', 'ที่จุดต่ำสุดลูกตุ้มเคลื่อนที่เร็วที่สุดจึงมีพลังงานจลน์มากที่สุด ขณะที่พลังงานศักย์น้อยที่สุด ส่วนที่จุดสูงสุดพลังงานจลน์เป็นศูนย์', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-conservation')), 'choice', 'เมื่อรถเบรกจนหยุดนิ่ง พลังงานจลน์ของรถส่วนใหญ่เปลี่ยนไปเป็นพลังงานรูปใด', '["พลังงานนิวเคลียร์","พลังงานไฟฟ้า","พลังงานลม","พลังงานความร้อนเนื่องจากการเสียดสี"]', '3', 'การเบรกทำให้ผ้าเบรกกับล้อเสียดสีกัน พลังงานจลน์จึงเปลี่ยนเป็นพลังงานความร้อนตามกฎการอนุรักษ์พลังงาน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-conservation')), 'number', 'ลูกบอลมวล 1 กิโลกรัมตกลงมาจากความสูง 5 เมตร (ไม่คิดแรงต้านอากาศ ใช้ g = 10 เมตร/วินาที²) เมื่อถึงพื้นลูกบอลมีพลังงานจลน์เท่ากับกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":50,"tolerance":0.5}', 'ที่จุดสูงสุดมี Ep = mgh = 1 × 10 × 5 = 50 จูล เมื่อถึงพื้นพลังงานศักย์เปลี่ยนเป็นพลังงานจลน์ทั้งหมด จึงได้ 50 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-conservation')), 'number', 'ถ้าพลังงานศักย์โน้มถ่วง 100 จูลถูกเปลี่ยนเป็นพลังงานจลน์ทั้งหมด วัตถุจะได้รับพลังงานจลน์เท่ากับกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":100,"tolerance":0.5}', 'ตามกฎการอนุรักษ์พลังงาน พลังงานรวมคงที่ 100 จูล เมื่อเปลี่ยนเป็นพลังงานจลน์ทั้งหมดจึงเท่ากับ 100 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-work-energy'), 'jr-work-energy-kinetic-potential', 'พลังงานจลน์และพลังงานศักย์', 'พลังงานจลน์เป็นพลังงานของวัตถุที่กำลังเคลื่อนที่ ส่วนพลังงานศักย์โน้มถ่วงเป็นพลังงานที่สะสมเนื่องจากความสูง พลังงานทั้งสองเปลี่ยนรูปหากันได้', 'junior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-kinetic-potential'), 'youtube', 'https://www.youtube.com/watch?v=5jYaDsv_scE', '5jYaDsv_scE', 'I know PHYSICS ep.5 - งานและพลังงาน (Part 2 : พลังงาน)', 'I know PHYSICs a little', 'https://www.youtube.com/channel/UC0qWWV4YLpxnAQGJ8ednXlA', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-kinetic-potential'), 'youtube', 'https://www.youtube.com/watch?v=rXfqsaTg_n4', 'rXfqsaTg_n4', 'พลังงานกลและกฎการอนุรักษ์พลังงาน (วิทยาศาสตร์ ม. 2 เล่ม 2 หน่วยที่ 5 บทที่ 2)', 'Proj14 ม.2', 'https://www.youtube.com/channel/UCkGQRzlwZFWkOin9SiP7JUQ', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-kinetic-potential'), 'แบบทดสอบ: พลังงานจลน์และพลังงานศักย์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-kinetic-potential')), 'choice', 'พลังงานจลน์คือพลังงานของวัตถุในลักษณะใด', '["วัตถุที่อยู่นิ่ง","วัตถุที่กำลังเคลื่อนที่","วัตถุที่อยู่สูงขึ้นจากพื้น","พลังงานที่เกิดจากความร้อน"]', '1', 'พลังงานจลน์เป็นพลังงานของวัตถุที่เคลื่อนที่ คำนวณจาก Ek = ½mv² วัตถุที่เคลื่อนที่เร็วหรือมีมวลมากจึงมีพลังงานจลน์มาก', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-kinetic-potential')), 'choice', 'พลังงานศักย์โน้มถ่วงของวัตถุขึ้นกับปริมาณใดเป็นหลัก', '["ความเร็วของวัตถุ","มวลและความเร็วเท่านั้น","ขนาดของวัตถุเท่านั้น","มวล ความสูง และความเร่งโน้มถ่วง"]', '3', 'พลังงานศักย์โน้มถ่วงคำนวณจาก Ep = mgh จึงขึ้นกับมวล ความสูง และค่าความเร่งโน้มถ่วง g', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-kinetic-potential')), 'choice', 'ลูกบอลมวลเท่ากันสองลูก ลูกหนึ่งอยู่สูง 2 เมตร อีกลูกอยู่สูง 4 เมตรจากพื้น ข้อใดถูกต้อง', '["ลูกที่สูง 4 เมตรมีพลังงานศักย์มากกว่า","ลูกที่สูง 2 เมตรมีพลังงานศักย์มากกว่า","ลูกทั้งสองมีพลังงานศักย์เท่ากัน","ลูกที่สูง 4 เมตรมีพลังงานจลน์มากกว่า"]', '0', 'Ep = mgh มวลเท่ากันแต่สูงกว่าจึงมีพลังงานศักย์โน้มถ่วงมากกว่า', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-kinetic-potential')), 'number', 'วัตถุมวล 2 กิโลกรัม เคลื่อนที่ด้วยความเร็ว 3 เมตร/วินาที พลังงานจลน์เท่ากับกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":9,"tolerance":0.5}', 'Ek = ½mv² = ½ × 2 × 3² = 9 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-kinetic-potential')), 'number', 'วัตถุมวล 5 กิโลกรัม อยู่สูงจากพื้น 4 เมตร มีพลังงานศักย์โน้มถ่วงกี่จูล (ใช้ g = 10 เมตร/วินาที² ตอบเป็นจำนวนเต็ม)', NULL, '{"value":200,"tolerance":0.5}', 'Ep = mgh = 5 × 10 × 4 = 200 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-work-energy'), 'jr-work-energy-simple-machines', 'เครื่องกลอย่างง่าย', 'เครื่องกลอย่างง่ายช่วยเปลี่ยนแรง ทิศทาง หรือระยะทางให้ทำงานได้สะดวกขึ้น เช่น คาน รอก ล้อและเพลา แต่ไม่ได้ทำให้งานทั้งหมดลดลง', 'junior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
