INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-work-power'), 'แบบทดสอบ: งานและกำลัง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-work-power')), 'choice', 'ในทางฟิสิกส์ งานจะเกิดขึ้นเมื่อใด', '["มีแรงใดก็ได้กระทำต่อวัตถุ","วัตถุเคลื่อนที่โดยไม่มีแรงกระทำ","มีแรงกระทำต่อวัตถุ และวัตถุเคลื่อนที่ในทิศเดียวกับแรง","วัตถุอยู่กับที่แม้มีแรงกระทำ"]', '2', 'งานต้องมีแรงกระทำและวัตถุเคลื่อนที่ในทิศเดียวกับแรง โดยคำนวณจาก W = F × s ถ้ามีเพียงแรงหรือเพียงการเคลื่อนที่อย่างเดียวก็ยังไม่เกิดงาน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-work-power')), 'choice', 'งานมีหน่วยเป็นข้อใด', '["จูล (J)","นิวตัน (N)","วัตต์ (W)","เมตร/วินาที (m/s)"]', '0', 'งาน = แรง × ระยะทาง มีหน่วยนิวตันคูณเมตร ซึ่งเรียกว่าจูล นิวตันเป็นหน่วยของแรง ส่วนวัตต์เป็นหน่วยของกำลัง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-work-power')), 'choice', 'กำลัง (Power) คือปริมาณใด', '["งานทั้งหมดที่ทำได้","งานที่ทำได้ในหนึ่งหน่วยเวลา","แรงคูณระยะทาง","พลังงานที่สะสมในวัตถุ"]', '1', 'กำลังคืองานต่อเวลา P = W / t มีหน่วยเป็นวัตต์ เครื่องจักรที่ทำงานเดียวกันได้ในเวลาน้อยกว่าแสดงว่ามีกำลังสูงกว่า', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-work-power')), 'number', 'ออกแรง 20 นิวตันผลักตู้ให้เคลื่อนที่ตามแนวแรงได้ระยะ 4 เมตร งานที่ทำเท่ากับกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":80,"tolerance":0.5}', 'W = F × s = 20 × 4 = 80 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-work-power')), 'number', 'เครื่องจักรเครื่องหนึ่งทำงานได้ 600 จูลในเวลา 3 วินาที กำลังของเครื่องจักรเท่ากับกี่วัตต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":200,"tolerance":0.5}', 'P = W / t = 600 ÷ 3 = 200 วัตต์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'kinetic-theory'), 'kinetic-theory-gas-equation', 'สมการสถานะของแก๊ส', 'สมการสถานะ PV = nRT เชื่อมความดัน ปริมาตร จำนวนโมล และอุณหภูมิสัมบูรณ์ของแก๊สอุดมคติเข้าด้วยกัน ใช้คำนวณสมบัติของแก๊สเมื่อเปลี่ยนสภาวะ', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'kinetic-theory-gas-equation'), 'youtube', 'https://www.youtube.com/watch?v=k3LUgf2ePME', 'k3LUgf2ePME', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.6(กฎของแก๊ส, สมการสถานะ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'kinetic-theory-gas-equation'), 'youtube', 'https://www.youtube.com/watch?v=By5XRX4bBp0', 'By5XRX4bBp0', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.5(กฎของชาร์ล,กฎของแก๊ส)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'kinetic-theory-gas-equation'), 'แบบทดสอบ: สมการสถานะของแก๊ส', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-gas-equation')), 'choice', 'สัญลักษณ์ R ในสมการ PV = nRT คืออะไร', '["ค่าคงที่ของแก๊ส","รัศมีของโมเลกุล","จำนวนรอบต่อวินาที","ความต้านทานของแก๊ส"]', '0', 'R คือค่าคงที่ของแก๊ส (gas constant) มีค่า 8.3 จูล/โมล·เคลวิน เมื่อใช้หน่วย SI', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-gas-equation')), 'choice', 'ในสมการ PV = nRT อุณหภูมิ T ต้องใช้หน่วยใด', '["องศาเซลเซียส","เคลวิน","องศาฟาเรนไฮต์","หน่วยใดก็ได้"]', '1', 'สมการแก๊สอุดมคติต้องใช้ T เป็นอุณหภูมิสัมบูรณ์ในหน่วยเคลวินเสมอ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-gas-equation')), 'choice', 'เมื่อปริมาตรคงที่ ถ้าเพิ่มจำนวนโมลของแก๊สเป็น 2 เท่า ที่อุณหภูมิคงที่ ความดันจะเปลี่ยนอย่างไร', '["ลดลงครึ่งหนึ่ง","คงเดิม","เพิ่มขึ้นเป็น 2 เท่า","เพิ่มขึ้นเป็น 4 เท่า"]', '2', 'จาก PV = nRT ที่ V และ T คงที่ ความดันแปรผันตรงกับ n เมื่อ n เป็น 2 เท่า P จึงเป็น 2 เท่า', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-gas-equation')), 'number', 'แก๊สอุดมคติจำนวน 2 โมล ที่อุณหภูมิ 300 เคลวิน ในภาชนะปริมาตร 0.1 ลูกบาศก์เมตร R = 8.3 จูล/โมล·เคลวิน จะมีความดันกี่พาสคัล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":49800,"tolerance":0.5}', 'P = nRT/V = 2 × 8.3 × 300/0.1 = 4980/0.1 = 49800 พาสคัล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-gas-equation')), 'number', 'แก๊สอุดมคติ 1 โมล ที่ความดัน 83000 พาสคัล และอุณหภูมิ 300 เคลวิน R = 8.3 จูล/โมล·เคลวิน มีปริมาตรกี่ลูกบาศก์เมตร (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":0.03,"tolerance":0.005}', 'V = nRT/P = 1 × 8.3 × 300/83000 = 2490/83000 = 0.03 ลูกบาศก์เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'kinetic-theory'), 'kinetic-theory-gas-laws', 'กฎของแก๊ส', 'กฎของบอยล์กล่าวว่าความดันแปรผกผันกับปริมาตรที่อุณหภูมิคงที่ กฎของชาร์ลกล่าวว่าปริมาตรแปรผันตรงกับอุณหภูมิสัมบูรณ์ที่ความดันคงที่ และรวมกันเป็นกฎรวมของแก๊ส', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
