INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'kinetic-theory-ideal-gas'), 'youtube', 'https://www.youtube.com/watch?v=5yXbE7ako1A', '5yXbE7ako1A', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.8 (อัตราเร็วเฉลี่ยและพลังงานจลน์เฉลี่ยของแก๊ส)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'kinetic-theory-ideal-gas'), 'แบบทดสอบ: ทฤษฎีจลน์ของแก๊สและแก๊สอุดมคติ', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-ideal-gas')), 'choice', 'ความดันของแก๊สในภาชนะเกิดจากสิ่งใดตามทฤษฎีจลน์ของแก๊ส', '["แรงโน้มถ่วงระหว่างโมเลกุล","โมเลกุลหยุดนิ่งเฉย","โมเลกุลแก๊สชนผนังภาชนะ","การขยายตัวของภาชนะ"]', '2', 'โมเลกุลแก๊สเคลื่อนที่สุ่มตลอดเวลา การชนกับผนังภาชนะทำให้เกิดแรงและความดันต่อผนัง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-ideal-gas')), 'choice', 'สมบัติข้อใดของแก๊สอุดมคติ', '["อนุภาคไม่มีขนาดและไม่มีการดึงดูดระหว่างกัน","อนุภาคมีแรงดึงดูดกันมาก","อนุภาคมีขนาดใหญ่ใกล้เคียงภาชนะ","อนุภาคหยุดนิ่งไม่เคลื่อนที่"]', '0', 'แก๊สอุดมคติสมมติให้โมเลกุลเป็นจุดไม่มีปริมาตร และไม่มีการดึงดูดหรือผลักกันระหว่างโมเลกุล', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-ideal-gas')), 'choice', 'เมื่ออุณหภูมิของแก๊สเพิ่มขึ้น พลังงานจลน์เฉลี่ยของโมเลกุลเป็นอย่างไร', '["ลดลง","เพิ่มขึ้น","คงที่","เพิ่มแล้วลดลงสลับกัน"]', '1', 'พลังงานจลน์เฉลี่ยแปรผันตรงกับอุณหภูมิสัมบูรณ์ของแก๊ส เมื่ออุณหภูมิสูงขึ้นโมเลกุลเคลื่อนที่เร็วขึ้น', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-ideal-gas')), 'number', 'แก๊สอุดมคติมีจำนวนโมล 2 โมล ก๊าซมีค่าคงที่แก๊ส R = 8.3 จูล/โมล·เคลวิน ถ้าอุณหภูมิเป็น 300 เคลวิน พลังงานภายในของแก๊สอะตอมเดี่ยวเป็นกี่จูล (สูตร U = 1.5nRT ตอบเป็นจำนวนเต็ม)', NULL, '{"value":7470,"tolerance":0.5}', 'U = 1.5 × 2 × 8.3 × 300 = 1.5 × 2 × 2490 = 7470 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-ideal-gas')), 'number', 'ถ้าอุณหภูมิสัมบูรณ์ของแก๊สเพิ่มจาก 300 เคลวินเป็น 900 เคลวิน พลังงานจลน์เฉลี่ยของโมเลกุลเพิ่มขึ้นเป็นกี่เท่าของเดิม (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.05}', 'พลังงานจลน์เฉลี่ยแปรผันตรงกับ T 900/300 = 3 เท่า', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'kinetic-theory'), 'kinetic-theory-molecular-energy', 'พลังงานจลน์เฉลี่ยและอัตราเร็ว rms', 'พลังงานจลน์เฉลี่ยของโมเลกุลแก๊สแปรผันตรงกับอัตราสูงสุดสัมบูรณ์ อัตราเร็วเฉลี่ยกำลังสอง (rms) คำนวณจากพลังงานจลน์เฉลี่ย สูตร vrms เท่ากับรากที่สองของ 3kT/m', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'kinetic-theory-molecular-energy'), 'youtube', 'https://www.youtube.com/watch?v=5yXbE7ako1A', '5yXbE7ako1A', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.8 (อัตราเร็วเฉลี่ยและพลังงานจลน์เฉลี่ยของแก๊ส)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'kinetic-theory-molecular-energy'), 'youtube', 'https://www.youtube.com/watch?v=gn3GpEfX08U', 'gn3GpEfX08U', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.7(ทฤษฎีจลน์แก๊ส,แก๊สอุดมคติ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'kinetic-theory-molecular-energy'), 'แบบทดสอบ: พลังงานจลน์เฉลี่ยและอัตราเร็ว rms', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-molecular-energy')), 'choice', 'พลังงานจลน์เฉลี่ยของโมเลกุลแก๊สอุดมคติแปรผันตรงกับปริมาณใด', '["อุณหภูมิสัมบูรณ์","ความดันเท่านั้น","ปริมาตรเท่านั้น","มวลของแก๊ส"]', '0', 'พลังงานจลน์เฉลี่ย EK = 3kT/2 แปรผันตรงกับอุณหภูมิสัมบูรณ์ ไม่ขึ้นกับชนิดของแก๊ส', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-molecular-energy')), 'choice', 'อัตราเร็ว rms หมายถึงอะไร', '["อัตราเร็วสูงสุดที่โมเลกุลทำได้","อัตราเร็วเฉลี่ยเลขคณิต","รากที่สองของค่าเฉลี่ยกำลังสองของอัตราเร็ว","อัตราเร็วของเสียงในแก๊ส"]', '2', 'อัตราเร็ว rms (root mean square) คือรากที่สองของค่าเฉลี่ยของอัตราเร็วกำลังสอง ใช้แทนพลังงานจลน์เฉลี่ยของโมเลกุล', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-molecular-energy')), 'choice', 'แก๊สสองชนิดอุณหภูมิเท่ากัน พลังงานจลน์เฉลี่ยต่อโมเลกุลเป็นอย่างไร', '["แก๊สเบากว่ามีค่ามากกว่า","เท่ากันทั้งสองชนิด","แก๊สหนักกว่ามีค่ามากกว่า","คำนวณไม่ได้"]', '1', 'พลังงานจลน์เฉลี่ย EK = 3kT/2 ขึ้นกับอุณหภูมิเท่ากันเมื่อ T เท่ากัน โดยไม่ขึ้นกับมวลโมเลกุล', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-molecular-energy')), 'number', 'อุณหภูมิสัมบูรณ์ของแก๊สเพิ่มจาก 300 เคลวินเป็น 1200 เคลวิน พลังงานจลน์เฉลี่ยเพิ่มขึ้นเป็นกี่เท่าของเดิม (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.05}', 'EK แปรผันตรงกับ T 1200/300 = 4 เท่า', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-molecular-energy')), 'number', 'โมเลกุลแก๊สมีอัตราเร็วสามค่า คือ 300, 400 และ 500 เมตร/วินาที จงหาอัตราเร็วกำลังสองเฉลี่ย แล้วถอดรากเป็นค่ากี่เมตร/วินาที (ตอบเป็นจำนวนเต็ม โดย rms คือรากของค่าเฉลี่ยกำลังสอง)', NULL, '{"value":408,"tolerance":0.5}', 'ค่าเฉลี่ยกำลังสอง = (300² + 400² + 500²)/3 = (90000 + 160000 + 250000)/3 = 500000/3 = 166666.67 รากที่สอง = 408.2 จึงตอบ 408 เมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'lenses'), 'lenses-convex-concave-images', 'ภาพจากเลนส์นูนและเลนส์เว้า', 'เลนส์นูนให้ภาพจริงหัวกลับเมื่อวัตถุอยู่ไกลกว่าโฟกัส และให้ภาพเสมือนหัวตั้งเมื่อวัตถุอยู่ระหว่างโฟกัสกับเลนส์ ส่วนเลนส์เว้าให้ภาพเสมือนหัวตั้งเล็กกว่าเสมอ กำลังขยาย m = s''/s', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
