INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-convex-concave-images')), 'choice', 'เลนส์เว้าให้ภาพของวัตถุจริงเป็นแบบใดเสมอ', '["ภาพเสมือน หัวตั้ง เล็กกว่าวัตถุ","ภาพจริง หัวกลับ","ภาพจริง ขยายใหญ่","ภาพเสมือน หัวกลับ"]', '0', 'เลนส์เว้าให้ภาพเสมือนหัวตั้ง เล็กกว่าวัตถุเสมอ ไม่ว่าวัตถุจะอยู่ที่ตำแหน่งใด', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-convex-concave-images')), 'choice', 'เลนส์นูนวางวัตถุไว้ระหว่างจุดโฟกัสกับเลนส์ ภาพที่เกิดเป็นแบบใด', '["ภาพจริง หัวกลับ เล็กกว่า","ภาพจริง หัวกลับ ขยายใหญ่","ภาพเสมือน หัวตั้ง เล็กกว่า","ภาพเสมือน หัวตั้ง ขยายใหญ่"]', '3', 'เมื่อวัตถุอยู่ไกลกว่าโฟกัสเลนส์นูนจะให้ภาพเสมือนหัวตั้งและขยายใหญ่ ใช้เป็นแว่นขยาย', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-convex-concave-images')), 'choice', 'กำลังขยาย m ของเลนส์หาจากความสัมพันธ์ใด เมื่อ s'' คือระยะภาพ s คือระยะวัตถุ', '["m = s''/s","m = s/s''","m = s'' + s","m = s × s''"]', '0', 'เมื่อวัตถุอยู่ใกล้กว่าโฟกัสเลนส์นูนจะให้ภาพเสมือนหัวตั้งและขยายใหญ่ ใช้เป็นแว่นขยาย', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-convex-concave-images')), 'number', 'เลนส์นูนให้ระยะภาพ 40 เซนติเมตร ระยะวัตถุ 20 เซนติเมตร กำลังขยายเท่ากับเท่าใด (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'm = s''/s = 40/20 = 2 เท่า', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-convex-concave-images')), 'number', 'เลนส์นูนความยาวโฟกัส 10 เซนติเมตร วางวัตถุไว้หน้าเลนส์ 5 เซนติเมตร ระยะภาพเท่ากับกี่เซนติเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":-10,"tolerance":0.5}', '1/10 = 1/5 + 1/s'' → 1/s'' = 1/10 − 1/5 = −1/10 → s'' = −10 เซนติเมตร ภาพเสมือนอยู่ฝั่งเดียวกับวัตถุ', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'lenses'), 'lenses-eye-vision', 'ตาและการมองเห็น', 'เลนส์ตารวมแสงให้เกิดภาพบนเรตินา สายตาสั้นภาพตกหน้าเรตินาแก้ด้วยเลนส์เว้า สายตายาวภาพตกหลังเรตินาแก้ด้วยเลนส์นูน', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
