INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-eye-vision')), 'choice', 'ภาพที่เกิดบนเรตินาของตาเป็นภาพชนิดใด', '["ภาพเสมือนหัวตั้ง","ภาพจริงหัวกลับ","ภาพจริงหัวตั้ง","ภาพเสมือนหัวกลับ"]', '1', 'เลนส์ตาเป็นเลนส์นูน เมื่อมองวัตถุไกลเกิดภาพจริงเล็กหัวกลับบนเรตินา สมองจึงกลับภาพให้เรารู้สึกตั้งตรง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-eye-vision')), 'choice', 'คนสายตาสั้นมองวัตถุไกลไม่ชัด เพราะภาพตกอยู่บริเวณใด', '["หน้าเรตินา","หลังเรตินา","ที่เรตินาพอดี","ที่กระจกตา"]', '0', 'สายตาสั้นลูกตายาวเกินไป ภาพของวัตถุไกลจึงเกิดหน้าเรตินา ต้องใช้แว่นเลนส์เว้ากระจายแสงให้ภาพถอยหลัง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-eye-vision')), 'choice', 'แว่นตาที่เหมาะกับคนสายตาสั้นคือแว่นชนิดใด', '["แว่นเลนส์นูน","แว่นเลนส์เรียบ","แว่นเลนส์เว้า","แว่นสองชั้นรูปร่างใดก็ได้"]', '2', 'สายตาสั้นภาพเกิดหน้าเรตินา ต้องใช้เลนส์เว้ากระจายรังสีให้ภาพถอยหลัง ตกบนเรตินาพอดี', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-eye-vision')), 'number', 'สายตาสั้นมองไกลสุดชัดที่ 2.5 เมตร ต้องใช้แว่นที่ทำให้วัตถุไกลสุดปรากฏว่าอยู่ห่าง 2.5 เมตร กำลังของเลนส์แว่นเป็นกี่ไดออปเตอร์โดยประมาณ (ตอบทศนิยม 1 ตำแหน่ง ใช้ f = 2.5 เมตร)', NULL, '{"value":0.4,"tolerance":0.05}', 'P = 1/f = 1/2.5 = 0.4 ไดออปเตอร์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-eye-vision')), 'number', 'แว่นสายตายาวมีเลนส์กำลัง +5 ไดออปเตอร์ ความยาวโฟกัสเป็นกี่เมตร (ตอบทศนิยม 2 ตำแหน่ง)', NULL, '{"value":0.2,"tolerance":0.005}', 'f = 1/P = 1/5 = 0.2 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'lenses'), 'lenses-optical-instruments', 'ทัศนอุปกรณ์', 'แว่นตา กล้องจุลทรรศน์ และกล้องโทรทรรศน์ใช้เลนส์หลายชุดรวมกันเพื่อแก้การมองเห็นหรือขยายภาพ ภาพจริงเกิดบนจอหรือเรตินา ส่วนภาพเสมือนใช้สำหรับดูด้วยตา', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments'), 'youtube', 'https://www.youtube.com/watch?v=FfU1_TOUb3I', 'FfU1_TOUb3I', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.8(เลนส์นูนและเลนส์นูน แบบฝึกหัด)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments'), 'youtube', 'https://www.youtube.com/watch?v=kdgiKtv-lCQ', 'kdgiKtv-lCQ', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.9(สรุปสูตรเตรียมสอบ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments'), 'แบบทดสอบ: ทัศนอุปกรณ์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments')), 'choice', 'กล้องจุลทรรศน์ประกอบด้วยเลนส์สำคัญสองชุดใด', '["เลนส์เว้าสองตัวเท่ากัน","เลนส์นูนกับกระจกโค้งเว้า","เลนส์ใกล้วัตถุและเลนส์ใกล้ตา","เลนส์ตาและเลนส์แว่นตา"]', '2', 'กล้องจุลทรรศน์ใช้เลนส์ใกล้วัตถุสร้างภาพกลางขนาดใหญ่ แล้วเลนส์ใกล้ตาขยายอีกครั้ง ความยาว/การขยายจึงยิ่งใหญ่', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments')), 'choice', 'ภาพขั้นกลางของวัตถุที่เกิดจากเลนส์ใกล้วัตถุของกล้องจุลทรรศน์มีลักษณะใด', '["ภาพเสมือนหัวกลับ","ภาพจริงหัวกลับ","ภาพจริงหัวตั้ง","ภาพเสมือนหัวตั้ง"]', '1', 'เลนส์ใกล้วัตถุวางวัตถุไว้เกินความยาวโฟกัสเล็กน้อยให้เกิดภาพจริงหัวกลับขยาย แล้วเลนส์ใกล้ตาขยายต่อ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments')), 'choice', 'คนสายตายาวควรมองวัตถุใกล้ด้วยแว่นตาที่มีเลนส์ชนิดใด', '["เลนส์นูน","เลนส์เว้า","เลนส์ทรงกระบอก","เลนส์แก้วใสธรรมดา"]', '0', 'สายตายาวมองเห็นไกลชัดแต่ใกล้ไม่ชัด แว่นตาที่ใช้คือแว่นเลนส์นูนรวมแสงช่วยรวมรังสีให้ตกบนเรตินาพอดี', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments')), 'number', 'กล้องจุลทรรศน์มีเลนส์ใกล้วัตถุขยาย 20 เท่า และเลนส์ใกล้ตาขยาย 10 เท่า กำลังขยายรวมเป็นกี่เท่า (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":200,"tolerance":0.5}', 'กำลังขยายรวมเท่ากับผลคูณของกำลังขยายทั้งสอง = 20 × 10 = 200 เท่า', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments')), 'number', 'แว่นตาอันหนึ่งมีความยาวโฟกัส 0.5 เมตร กำลังของเลนส์เป็นกี่ไดออปเตอร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.05}', 'กำลังของเลนส์ P = 1/f = 1/0.5 = 2 ไดออปเตอร์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'lenses'), 'lenses-power-diopters', 'กำลังของเลนส์ (ไดออปเตอร์)', 'กำลังของเลนส์คือส่วนกลับของความยาวโฟกัสในหน่วยเมตร P = 1/f หน่วยไดออปเตอร์ เลนส์นูนมีกำลังเป็นบวก เลนส์เว้ามีกำลังเป็นลบ ยิ่งรวมหรือแยกแสงเก่งยิ่งมีค่ากำลังมาก', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
