INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-power-diopters'), 'แบบทดสอบ: กำลังของเลนส์ (ไดออปเตอร์)', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-power-diopters')), 'choice', 'เลนส์นูนมีความยาวโฟกัส 0.5 เมตร กำลังของเลนส์เท่ากับเท่าใด', '["0.5 ไดออปเตอร์","2 ไดออปเตอร์","5 ไดออปเตอร์","20 ไดออปเตอร์"]', '1', 'P = 1/f = 1/0.5 = 2 ไดออปเตอร์', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-power-diopters')), 'choice', 'เลนส์เว้ามีความยาวโฟกัสเป็นลบ กำลังของเลนส์เว้าเป็นแบบใด', '["เป็นบวก","เป็นลบ","เป็นศูนย์","ขึ้นกับขนาดของเลนส์"]', '1', 'เนื่องจากความยาวโฟกัสเลนส์เว้าเป็นลบ กำลัง P = 1/f จึงเป็นลบด้วย', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-power-diopters')), 'choice', 'กำลังของเลนส์ P = 1/f เมื่อ f ต้องมีหน่วยเป็นอะไร', '["เซนติเมตร","มิลลิเมตร","เมตร","กิโลเมตร"]', '2', 'กำลังมีหน่วยไดออปเตอร์เมื่อ f อยู่ในหน่วยเมตร ต้องแปลงความยาวโฟกัสเป็นเมตรเสมอ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-power-diopters')), 'number', 'เลนส์นูนมีความยาวโฟกัส 0.25 เมตร กำลังของเลนส์เท่ากับกี่ไดออปเตอร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 'P = 1/f = 1/0.25 = 4 ไดออปเตอร์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-power-diopters')), 'number', 'เลนส์มีความยาวโฟกัส 0.2 เมตร กำลังของเลนส์เท่ากับกี่ไดออปเตอร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":5,"tolerance":0.5}', 'P = 1/f = 1/0.2 = 5 ไดออปเตอร์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'lenses'), 'lenses-thin-lens', 'เลนส์บางและสมการเลนส์', 'เลนส์บางมีเลนส์นูนรวมแสงและเลนส์เว้าแยกแสง ความสัมพันธ์ระหว่างระยะโฟกัส ระยะวัตถุ และระยะภาพคือ 1/f = 1/s + 1/s'' ความยาวโฟกัสเลนส์นูนเป็นบวก เลนส์เว้าเป็นลบ', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-thin-lens'), 'youtube', 'https://www.youtube.com/watch?v=_MpAHoSyP04', '_MpAHoSyP04', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.7 (เลนส์นูน,เลนส์เว้า)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-thin-lens'), 'youtube', 'https://www.youtube.com/watch?v=FfU1_TOUb3I', 'FfU1_TOUb3I', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.8 (เลนส์นูนและเลนส์นูน แบบฝึกหัด)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-thin-lens'), 'แบบทดสอบ: เลนส์บางและสมการเลนส์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-thin-lens')), 'choice', 'เลนส์นูนมีสมบัติต่อแสงที่ผ่านอย่างไร', '["รวมแสงเข้าหาจุดโฟกัส","แยกแสงออกจากกัน","ดูดกลืนแสง","ไม่เปลี่ยนทิศแสง"]', '0', 'เลนส์นูน (convex/converging lens) รวมแสงคู่ขนานเข้าหาจุดโฟกัสหลังเลนส์ จึงมีความยาวโฟกัสเป็นบวก', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-thin-lens')), 'choice', 'สมการเลนส์บางที่สัมพันธ์ระยะโฟกัส f ระยะวัตถุ s และระยะภาพ s'' คือข้อใด', '["f = s + s''","1/f = 1/s + 1/s''","f = s − s''","1/f = s + s''"]', '1', 'สมการเลนส์บางคือ 1/f = 1/s + 1/s'' ใช้กับเลนส์บางทั้งนูนและเว้าโดยใช้เครื่องหมายตามหลักการ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-thin-lens')), 'choice', 'เลนส์นูนมีความยาวโฟกัส 10 เซนติเมตร วางวัตถุไว้หน้าเลนส์ 30 เซนติเมตร จะได้ระยะภาพเท่าใด', '["7.5 เซนติเมตร","20 เซนติเมตร","15 เซนติเมตร","40 เซนติเมตร"]', '2', '1/10 = 1/30 + 1/s'' → 1/s'' = 1/10 − 1/30 = 2/30 → s'' = 15 เซนติเมตร', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-thin-lens')), 'number', 'เลนส์นูนมีความยาวโฟกัส 15 เซนติเมตร วางวัตถุไว้หน้าเลนส์ 30 เซนติเมตร ระยะภาพเท่ากับกี่เซนติเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":30,"tolerance":0.5}', '1/15 = 1/30 + 1/s'' → 1/s'' = 1/15 − 1/30 = 1/30 → s'' = 30 เซนติเมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-thin-lens')), 'number', 'เลนส์นูนมีความยาวโฟกัส 20 เซนติเมตร วางวัตถุไว้หน้าเลนส์ 60 เซนติเมตร ระยะภาพเท่ากับกี่เซนติเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":30,"tolerance":0.5}', '1/20 = 1/60 + 1/s'' → 1/s'' = 1/20 − 1/60 = 2/60 → s'' = 30 เซนติเมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'reflection-refraction'), 'light-reflection', 'การสะท้อนของแสง: กฎการสะท้อน', 'แสงสะท้อนจากผิวเรียบโดยมุมตกกระทบเท่ากับมุมสะท้อน และรังสีทั้งสองอยู่ในระนาบเดียวกับเส้นปกติ', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
