INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-components')), 'choice', 'ระยะจากแนวสมดุลของคลื่นไปจนถึงยอดคลื่นเรียกว่าอะไร', '["แอมพลิจูด","ความยาวคลื่น","คาบ","เฟส"]', '0', 'แอมพลิจูดคือระยะห่างจากตำแหน่งสมดุลถึงตำแหน่งสูงสุด (ยอดหรือท้อง) ของคลื่น', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-components')), 'choice', 'ความยาวคลื่นวัดจากจุดใดถึงจุดใด', '["จากยอดคลื่นถึงท้องคลื่นถัดไป","จากยอดคลื่นหนึ่งถึงยอดคลื่นถัดไป","จากแนวสมดุลถึงยอดคลื่น","จากจุดเริ่มไปตลอดความยาวเชือก"]', '1', 'ความยาวคลื่นเป็นระยะจากจุดที่มีเฟสเดียวกันต่อเนื่อง เช่น ยอดถึงยอด หรือท้องถึงท้อง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-components')), 'choice', 'ถ้าคลื่นทำการสั่นครบ 4 รอบในเวลา 8 วินาที คาบของคลื่นเป็นเท่าใด', '["4 วินาที","8 วินาที","2 วินาที","32 วินาที"]', '2', 'คาบคือเวลาต่อ 1 รอบ T = 8/4 = 2 วินาที', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-components')), 'number', 'คลื่นที่มีคาบ 0.5 วินาที จะมีความถี่เป็นกี่เฮิรตซ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.05}', 'ความถี่เป็นส่วนกลับของคาบ f = 1/T = 1/0.5 = 2 เฮิรตซ์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-components')), 'number', 'คลื่นหนึ่งมีความถี่ 5 เฮิรตซ์ ใช้เวลากี่วินาทีจึงจะครบ 20 รอบ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.05}', 'เวลาทั้งหมด = จำนวนรอบ/ความถี่ = 20/5 = 4 วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'mechanical-waves'), 'mechanical-waves-definition-types', 'ความหมายและชนิดของคลื่น', 'คลื่นกลคือการรบกวนที่ถ่ายทอดพลังงานผ่านตัวกลางโดยที่ตัวกลางไม่เคลื่อนที่ตามไป แบ่งเป็นคลื่นตามขวางและคลื่นตามยาวตามทิศการสั่นของอนุภาค', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'mechanical-waves-definition-types'), 'youtube', 'https://www.youtube.com/watch?v=SU7c0I48JQ8', 'SU7c0I48JQ8', 'ฟิสิกส์ ม.5 บทที่ 9 คลื่น ep.1', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'mechanical-waves-definition-types'), 'youtube', 'https://www.youtube.com/watch?v=8CNIpCw8vIE', '8CNIpCw8vIE', 'ฟิสิกส์ ม.ปลาย บทที่9 คลื่น แบบเข้าใจง่าย(ฉบับเด็ก Cambridge)', 'Mr.Phoops', 'https://www.youtube.com/channel/UCx5Rw-I8iWy6EcVz2zpwRrw', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'mechanical-waves-definition-types'), 'แบบทดสอบ: ความหมายและชนิดของคลื่น', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-definition-types')), 'choice', 'คลื่นกลที่เคลื่อนที่ผ่านตัวกลาง ถ่ายทอดสิ่งใดจากจุดหนึ่งไปยังอีกจุดหนึ่ง', '["พลังงาน โดยที่ตัวกลางไม่เคลื่อนที่ตามไปด้วย","ตัวกลางไปพร้อมกับคลื่น","มวลของตัวกลางทั้งหมด","ความร้อนเท่านั้น"]', '0', 'คลื่นกลถ่ายทอดพลังงานผ่านตัวกลาง โดยอนุภาคของตัวกลางสั่นอยู่กับที่และไม่เคลื่อนที่ตามคลื่นไปด้วย', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-definition-types')), 'choice', 'คลื่นที่อนุภาคของตัวกลางสั่นในแนวตั้งฉากกับทิศการเคลื่อนที่ของคลื่น เรียกว่าคลื่นชนิดใด', '["คลื่นตามยาว","คลื่นตามขวาง","คลื่นแม่เหล็กไฟฟ้า","คลื่นนิ่ง"]', '1', 'คลื่นตามขวางคือคลื่นที่อนุภาคสั่นตั้งฉากกับทิศทางที่คลื่นเคลื่อนที่ เช่น คลื่นในเส้นเชือก', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-definition-types')), 'choice', 'เสียงในอากาศจัดเป็นคลื่นชนิดใด และเพราะเหตุใด', '["ตามขวาง เพราะเสียงสะท้อนได้","ตามขวาง เพราะอนุภาคสั่นขวางทิศการเคลื่อนที่","ตามยาว เพราะอนุภาคสั่นขนานกับทิศการเคลื่อนที่ของคลื่น","ไม่เป็นคลื่นกลเพราะผ่านสุญญากาศได้"]', '2', 'เสียงเป็นคลื่นตามยาว อนุภาคของตัวกลางสั่นไปตามแนวเดียวกับทิศที่เสียงเคลื่อนที่ ทำให้เกิดช่วงอัดและช่วงขยาย', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-definition-types')), 'number', 'คลื่นน้ำมีความถี่ 2 รอบต่อวินาที และความยาวคลื่น 4 เมตร อัตราเร็วของคลื่นเท่ากับกี่เมตรต่อวินาที (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":8,"tolerance":0.5}', 'v = fλ = 2 × 4 = 8 เมตรต่อวินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-definition-types')), 'number', 'คลื่นลูกหนึ่งมีความยาวคลื่น 5 เมตร และเคลื่อนที่ด้วยอัตราเร็ว 20 เมตรต่อวินาที ความถี่ของคลื่นเท่ากับกี่รอบต่อวินาที (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 'จาก v = fλ จะได้ f = v/λ = 20/5 = 4 รอบต่อวินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'mechanical-waves'), 'mechanical-waves-speed', 'อัตราเร็วของคลื่น v = fλ', 'อัตราเร็วของคลื่นเท่ากับผลคูณของความถี่กับความยาวคลื่น v = fλ เมื่อความยาวคลื่นเปลี่ยน อัตราเร็วจะขึ้นกับสมบัติของตัวกลาง คาบและความถี่แปรผกผันกัน', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
