INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'mechanical-waves-speed'), 'แบบทดสอบ: อัตราเร็วของคลื่น', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-speed')), 'choice', 'ความสัมพันธ์ระหว่างอัตราเร็ว v ความถี่ f และความยาวคลื่น λ ของคลื่นคือข้อใด', '["v = f/λ","v = λ/f","v = fλ","v = f + λ"]', '2', 'อัตราเร็วของคลื่นเท่ากับความถี่คูณความยาวคลื่น v = fλ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-speed')), 'choice', 'ถ้าความถี่ของคลื่นเพิ่มขึ้นเป็น 2 เท่า โดยความยาวคลื่นคงที่ อัตราเร็วของคลื่นเป็นอย่างไร', '["เพิ่มขึ้นเป็น 2 เท่า","ลดลงครึ่งหนึ่ง","ไม่เปลี่ยนแปลง","เพิ่มขึ้นเป็น 4 เท่า"]', '0', 'จาก v = fλ ถ้า f เพิ่มเป็น 2 เท่าและ λ คงที่ อัตราเร็ว v จะเพิ่มเป็น 2 เท่า', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-speed')), 'choice', 'อัตราเร็วของคลื่นในเส้นเชือกขึ้นอยู่กับสมบัติใดของเชือกเป็นหลัก', '["ความถี่ของคลื่น","ความตึงของเชือกและความหนาแน่นเชิงเส้น","แอมพลิจูดของคลื่น","เฟสของคลื่น"]', '1', 'อัตราเร็วคลื่นในเชือก v = √(T/μ) ขึ้นกับความตึงเชือก T และความหนาแน่นเชิงเส้น μ ไม่ใช้ความถี่หรือแอมพลิจูด', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-speed')), 'number', 'คลื่นมีความถี่ 5 รอบต่อวินาที และความยาวคลื่น 2 เมตร อัตราเร็วของคลื่นเท่ากับกี่เมตรต่อวินาที (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":10,"tolerance":0.5}', 'v = fλ = 5 × 2 = 10 เมตรต่อวินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-speed')), 'number', 'คลื่นเคลื่อนที่ด้วยอัตราเร็ว 300 เมตรต่อวินาที และมีความถี่ 1500 เฮิรตซ์ ความยาวคลื่นเท่ากับกี่เมตร (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":0.2,"tolerance":0.05}', 'λ = v/f = 300/1500 = 0.2 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'mechanical-waves'), 'mechanical-waves-superposition', 'การซ้อนทับของคลื่นและคลื่นนิ่ง', 'หลักการซ้อนทับกล่าวว่าการกระจัดลัพธ์ ณ จุดใดเท่ากับผลรวมเชิงพีชคณิตของคลื่นแต่ละขบวน เมื่อคลื่นสองขบวนความถี่เท่ากันเคลื่อนที่สวนทางกันจะเกิดคลื่นนิ่ง', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
