INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'mechanical-waves-surface-string'), 'แบบทดสอบ: คลื่นผิวน้ำและคลื่นในเส้นเชือก', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-surface-string')), 'choice', 'คลื่นที่เคลื่อนที่ไปตามเส้นเชือกที่ถูกสะบัดจัดเป็นคลื่นชนิดใด', '["คลื่นตามยาว","คลื่นตามขวาง","คลื่นเสียง","คลื่นแม่เหล็กไฟฟ้า"]', '1', 'เมื่อสะบัดเชือก อนุภาคของเชือกสั่นในแนวตั้งฉากกับทิศการเคลื่อนที่ของคลื่น จึงเป็นคลื่นตามขวาง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-surface-string')), 'choice', 'ถ้าเพิ่มความตึงของเชือกเป็น 4 เท่าโดยความหนาแน่นเชิงเส้นคงที่ อัตราเร็วของคลื่นในเชือกเป็นอย่างไร', '["เพิ่มขึ้นเป็น 2 เท่า","เพิ่มขึ้นเป็น 4 เท่า","ไม่เปลี่ยนแปลง","ลดลงครึ่งหนึ่ง"]', '0', 'v = √(T/μ) เมื่อ T เพิ่มเป็น 4 เท่าและ μ คงที่ อัตราเร็วจะเพิ่มเป็น √4 = 2 เท่า', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-surface-string')), 'choice', 'คลื่นบนผิวน้ำมีลักษณะการสั่นของอนุภาคเป็นแบบใด', '["สั่นตามยาวล้วน","สั่นตามขวางล้วน","เป็นทั้งคลื่นตามขวางและตามยาวผสมกัน","ไม่ใช่คลื่นกล"]', '2', 'คลื่นผิวน้ำมีอนุภาคเคลื่อนที่เป็นวงรี จึงมีทั้งองค์ประกอบตามขวางและตามยาว เรียกว่าเป็นคลื่นผสม', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-surface-string')), 'number', 'คลื่นในเส้นเชือกเคลื่อนที่ด้วยอัตราเร็ว 8 เมตรต่อวินาที มีความถี่ 4 เฮิรตซ์ ความยาวคลื่นเท่ากับกี่เมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'λ = v/f = 8/4 = 2 เมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-surface-string')), 'number', 'เชือกถูกดึงด้วยความตึง 5 นิวตัน และมีความหนาแน่นเชิงเส้น 0.05 กิโลกรัมต่อเมตร อัตราเร็วของคลื่นในเชือกเท่ากับกี่เมตรต่อวินาที (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":10,"tolerance":0.5}', 'v = √(T/μ) = √(5/0.05) = √100 = 10 เมตรต่อวินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'momentum-collisions'), 'momentum-conservation', 'กฎการอนุรักษ์โมเมนตัม', 'ในระบบที่ไม่มีแรงภายนอกกระทำ โมเมนตัมรวมก่อนและหลังเหตุการณ์มีค่าคงที่ ใช้แก้ปัญหาการชนและการแยกตัว', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'momentum-conservation'), 'youtube', 'https://www.youtube.com/watch?v=a-dC2tb0HfI', 'a-dC2tb0HfI', 'ฟิสิกส์ ม.4 บทที่ 6 โมเมนตัมและการชน ep.3(การเปลี่ยนแปลงโมเมนตัมใน 2 มิติ, กฎการอนุรักษ์โมเนตัม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'momentum-conservation'), 'youtube', 'https://www.youtube.com/watch?v=LeXPLcFG-74', 'LeXPLcFG-74', 'ฟิสิกส์ ม.4 บทที่ 6 โมเมนตัมและการชน ep.6(การชน กฎการอนุรักษ์โมเมนตัม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'momentum-conservation'), 'แบบทดสอบ: กฎการอนุรักษ์โมเมนตัม', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'momentum-conservation')), 'choice', 'กฎการอนุรักษ์โมเมนตัมใช้ได้ในกรณีใด', '["ทุกกรณีเสมอ","ระบบที่ไม่มีแรงภายนอกสุทธิกระทำ","ระบบที่มีแต่แรงโน้มถ่วงเท่านั้น","เฉพาะการชนที่ยืดหยุ่นอย่างเดียว"]', '1', 'โมเมนตัมรวมคงที่เมื่อแรงภายนอกสุทธิเป็นศูนย์ ในกรณีการชนแรงภายนอกมีน้อยจึงอนุรักษ์ได้', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'momentum-conservation')), 'choice', 'กฎการอนุรักษ์โมเมนตัมมีพื้นฐานมาจากกฎข้อใดของนิวตัน', '["กฎข้อที่หนึ่ง","กฎข้อที่สาม (กิริยา-ปฏิกิริยา)","กฎความโน้มถ่วงสากล","ไม่มีกฎใด"]', '1', 'แรงทุกแรงเกิดเป็นคู่กิริยา-ปฏิกิริยาตามกฎข้อที่สาม รวมแรงภายนอกสุทธิเป็นศูนย์ ทำให้โมเมนตัมรวมอนุรักษ์', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'momentum-conservation')), 'choice', 'ระบบปิดหมายถึงระบบแบบใด', '["มีแรงภายนอกมากระทำ","ไม่มีแรงภายนอกมากระทำ แต่สมาชิกภายในแรงระหว่างกันได้","มีมวลเพิ่มเข้าตลอดเวลา","อุณหภูมิคงที่เสมอ"]', '0', 'ระบบปิดคือระบบที่ไม่มีแรงภายนอกสุทธิ มวลและพลังงานอาจเปลี่ยนแปลงระหว่างสมาชิกได้ แต่โมเมนตัมรวมคงที่', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'momentum-conservation')), 'number', 'วัตถุมวล 3 กิโลกรัม วิ่งด้วยความเร็ว 4 เมตร/วินาที ไปชนวัตถุมวล 1 กิโลกรัม ที่หยุดนิ่ง แล้วทั้งสองติดกันเคลื่อนที่ไปด้วยกัน ความเร็วหลังชนมีค่ากี่เมตร/วินาที', NULL, '{"value":3,"tolerance":0.5}', 'อนุรักษ์โมเมนตัม m1v1 = (m1+m2)v'' ได้ v'' = 3×4/(3+1) = 12/4 = 3 เมตร/วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'momentum-conservation')), 'number', 'วัตถุมวล 2 กิโลกรัม วิ่งด้วยความเร็ว 5 เมตร/วินาที ไปชนวัตถุมวล 3 กิโลกรัมที่หยุดนิ่ง แล้วติดกันไปด้วยกัน ความเร็วหลังชนมีค่ากี่เมตร/วินาที', NULL, '{"value":2,"tolerance":0.5}', 'm1v1 = (m1+m2)v'' ได้ v'' = 2×5/(2+3) = 10/5 = 2 เมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'momentum-collisions'), 'momentum-impulse', 'โมเมนตัมและการดล', 'โมเมนตัมคือผลคูณของมวลกับความเร็ว p = mv การดลเท่ากับแรงคูณเวลาและเท่ากับการเปลี่ยนแปลงโมเมนตัม', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'momentum-impulse'), 'youtube', 'https://www.youtube.com/watch?v=l_3L0LBO1Mw', 'l_3L0LBO1Mw', 'ฟิสิกส์ ม.4 บทที่ 6 โมเมนตัมและการชน ep.1(โมเมนตัมและการเปลี่ยนแปลงโมเมนตัม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'momentum-impulse'), 'youtube', 'https://www.youtube.com/watch?v=YmpzRP-Hdxc', 'YmpzRP-Hdxc', 'ฟิสิกส์ ม.4 บทที่ 6 โมเมนตัมและการชน ep.2 (การเปลี่ยนแปลงโมเมนตัม การดล แรงดล)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'momentum-impulse'), 'แบบทดสอบ: โมเมนตัมและการดล', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'momentum-impulse')), 'choice', 'โมเมนตัม p ของวัตถุมวล m เคลื่อนที่ด้วยความเร็ว v มีค่าตามข้อใด', '["p = mv","p = ½mv²","p = mv²","p = m/v"]', '0', 'โมเมนตัมคือผลคูณของมวลกับความเร็ว p = mv เป็นปริมาณเวกเตอร์มีหน่วยกิโลกรัม·เมตร/วินาที', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'momentum-impulse')), 'choice', 'การดล (Impulse) ของแรงคงตัว F ที่กระทำต่อวัตถุเป็นเวลา t มีค่าตามข้อใด', '["F t","F / t","½Ft","Ft²"]', '0', 'การดล = Ft และเท่ากับการเปลี่ยนแปลงโมเมนตัมของวัตถุตามทฤษฎีบทการดล-โมเมนตัม', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'momentum-impulse')), 'choice', 'หน่วยของโมเมนตัมคือข้อใด', '["นิวตัน","จูล","กิโลกรัม·เมตร/วินาที","วัตต์"]', '2', 'โมเมนตัม = มวล × ความเร็ว จึงมีหน่วย กิโลกรัม·เมตร/วินาที ซึ่งเทียบเท่านิวตัน·วินาที', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'momentum-impulse')), 'number', 'วัตถุมวล 2 กิโลกรัม เคลื่อนที่ด้วยความเร็ว 5 เมตร/วินาที มีโมเมนตัมกี่กิโลกรัม·เมตร/วินาที', NULL, '{"value":10,"tolerance":0.5}', 'p = mv = 2 × 5 = 10 กิโลกรัม·เมตร/วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'momentum-impulse')), 'number', 'แรงขนาด 20 นิวตัน กระทำต่อวัตถุเป็นเวลา 3 วินาที การดลที่เกิดขึ้นมีค่ากี่นิวตัน·วินาที', NULL, '{"value":60,"tolerance":0.5}', 'การดล = Ft = 20 × 3 = 60 นิวตัน·วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'newton-laws'), 'newton-laws-application', 'การประยุกต์กฎของนิวตันกับวัตถุบนพื้นราบและแนวดิ่ง', 'นำกฎของนิวตันไปใช้กับวัตถุบนพื้นราบและในแนวดิ่ง เช่น ลิฟต์และพื้นระนาบ โดยใช้แรงลัพธ์ F = ma และแรงปกติ', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-application'), 'youtube', 'https://www.youtube.com/watch?v=49kgcKlI6Zg', '49kgcKlI6Zg', '3.3 แรงและกฎการเคลื่อนที่ของนิวตัน (Newton''s Laws of Motion) | ฟิสิกส์ ม.4 เทอม 1 | ฟิสิกส์ ม.ปลาย', 'ปลาอะคาเดมี', 'https://www.youtube.com/channel/UCtTD069k4v4IAHpf708ykeQ', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-application'), 'youtube', 'https://www.youtube.com/watch?v=snhN5avsrnE', 'snhN5avsrnE', 'ฟิสิกส์ ม.4 บทที่ 3 แรงและกฎการเคลื่อนที่ ep.7(โจทย์กฎการเคลื่อนที่ของนิวตัน, แรงเสียดทาน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-application'), 'แบบทดสอบ: การประยุกต์กฎของนิวตันกับวัตถุบนพื้นราบและแนวดิ่ง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-application')), 'choice', 'คนยืนในลิฟต์ที่เร่งขึ้น น้ำหนักปรากฏ (แรงที่พื้นรองรับ) เป็นอย่างไรเมื่อเทียบกับน้ำหนักปกติ', '["น้อยลง","มากขึ้น","เท่ากันเสมอ","เป็นศูนย์"]', '1', 'ลิฟต์เร่งขึ้น แรงที่พื้นรองรับต้องมากกว่าน้ำหนักจริงเพื่อให้แรงลัพธ์ขึ้น การชั่งได้จึงมากขึ้น', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-application')), 'choice', 'กล่องมวล 4 กิโลกรัมวางบนพื้นลื่น มีแรงลัพธ์ 12 นิวตัน ความเร่งของกล่องเป็นเท่าใด', '["2 เมตร/วินาที²","4 เมตร/วินาที²","3 เมตร/วินาที²","0.33 เมตร/วินาที²"]', '2', 'a = F/m = 12 / 4 = 3 เมตร/วินาที²', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-application')), 'choice', 'ก้อนมวล 2 กิโลกรัมวางนิ่งบนพื้นราบ แรงปกติจากพื้นมีขนาดเท่าใด (ใช้ g = 10 เมตร/วินาที²)', '["0 นิวตัน","10 นิวตัน","40 นิวตัน","20 นิวตัน"]', '3', 'วางนิ่งแนวดิ่งแรงลัพธ์เป็นศูนย์ แรงปกติ = น้ำหนัก mg = 2 x 10 = 20 นิวตัน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-application')), 'number', 'มวล 5 กิโลกรัมวางบนพื้นลื่น ออกแรงลัพธ์ 25 นิวตัน ความเร่งเป็นเท่าใด (ตอบเป็นเมตร/วินาที² จำนวนเต็ม)', NULL, '{"value":5,"tolerance":0.5}', 'a = F/m = 25 / 5 = 5 เมตร/วินาที²', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-application')), 'number', 'มวล 4 กิโลกรัมวางนิ่งบนพื้นราบ แรงปกติจากพื้นเท่ากับน้ำหนัก mg ใช้ g = 10 เมตร/วินาที² แรงปกติมีขนาดเท่าใด (ตอบเป็นนิวตัน จำนวนเต็ม)', NULL, '{"value":40,"tolerance":0.5}', 'N = mg = 4 x 10 = 40 นิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'newton-laws'), 'newton-laws-connected-masses', 'ระบบมวลหลายก้อนที่เชื่อมกัน (รวมเชือกและรอก)', 'ระบบมวลหลายก้อนที่เชื่อมกัน ให้มองทั้งระบบเพื่อหาความเร่ง แล้วแยกแต่ละก้อนเพื่อหาแรงตึงเชือกหรือแรงสัมผัสระหว่างก้อน', 'senior', 6, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-connected-masses'), 'youtube', 'https://www.youtube.com/watch?v=49kgcKlI6Zg', '49kgcKlI6Zg', '3.3 แรงและกฎการเคลื่อนที่ของนิวตัน (Newton''s Laws of Motion) | ฟิสิกส์ ม.4 เทอม 1 | ฟิสิกส์ ม.ปลาย', 'ปลาอะคาเดมี', 'https://www.youtube.com/channel/UCtTD069k4v4IAHpf708ykeQ', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-connected-masses'), 'youtube', 'https://www.youtube.com/watch?v=6zSI0tYtt98', '6zSI0tYtt98', 'ฟิสิกส์ ม.4 บทที่ 3 แรงและกฎการเคลื่อนที่ ep.5(โจทย์กฎการเคลื่อนที่ของนิวตัน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-connected-masses'), 'แบบทดสอบ: ระบบมวลหลายก้อนที่เชื่อมกัน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-connected-masses')), 'choice', 'มวลสองก้อนติดกันบนพื้นลื่นถูกดึงด้วยแรง F ทั้งระบบมีความเร่งเท่าใด', '["F / (m1 + m2)","F / m1","F / m2","F / (m1 - m2)"]', '0', 'มองทั้งระบบเป็นมวลรวม m1 + m2 ดังนั้น a = F / (m1 + m2)', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-connected-masses')), 'choice', 'สองก้อนผูกเชือกกันบนพื้นลื่นมวลรวม 5 กิโลกรัม มีแรงลัพธ์ 20 นิวตัน ความเร่งร่วมของระบบเป็นเท่าใด', '["5 เมตร/วินาที²","4 เมตร/วินาที²","0.25 เมตร/วินาที²","3 เมตร/วินาที²"]', '1', 'a = F / มวลรวม = 20 / 5 = 4 เมตร/วินาที² ทุกก้อนในระบบมีความเร่งเท่ากัน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-connected-masses')), 'choice', 'สำหรับเชือกที่เบาและไม่ยืด แรงตึงในเชือกเป็นอย่างไรตลอดเส้นเชือก', '["ไม่เท่ากันตลอด","เท่ากันตลอดเส้น","เท่ากับน้ำหนักเสมอ","เป็นศูนย์เสมอ"]', '1', 'เชือกเบาไม่ยืด แรงตึงมีค่าคงที่ตลอดเส้นเชือก จึงใช้แทนค่าเดียวกันได้ทั้งระบบ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-connected-masses')), 'number', 'ระบบมวลรวม 10 กิโลกรัมมีแรงลัพธ์ 50 นิวตัน ความเร่งร่วมเป็นเท่าใด (ตอบเป็นเมตร/วินาที² จำนวนเต็ม)', NULL, '{"value":5,"tolerance":0.5}', 'a = F / มวลรวม = 50 / 10 = 5 เมตร/วินาที²', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-connected-masses')), 'number', 'มวล 3 กิโลกรัมกับ 7 กิโลกรัมผูกติดกันบนพื้นลื่น ถูกดึงด้วยแรง 40 นิวตัน ความเร่งร่วมเป็นเท่าใด (ตอบเป็นเมตร/วินาที² จำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 'มวลรวม = 3 + 7 = 10 กิโลกรัม a = 40 / 10 = 4 เมตร/วินาที²', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'newton-laws'), 'newton-laws-inertia', 'กฎข้อที่ 1 ของนิวตัน (ความเฉื่อย)', 'กฎข้อที่ 1 กล่าวว่า วัตถุรักษาสภาพการเคลื่อนที่เดิมตราบที่ไม่มีแรงลัพธ์มากระทำ ความเฉื่อยคือแนวโน้มต้านการเปลี่ยนสภาพการเคลื่อนที่', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-inertia'), 'youtube', 'https://www.youtube.com/watch?v=49kgcKlI6Zg', '49kgcKlI6Zg', '3.3 แรงและกฎการเคลื่อนที่ของนิวตัน (Newton''s Laws of Motion) | ฟิสิกส์ ม.4 เทอม 1 | ฟิสิกส์ ม.ปลาย', 'ปลาอะคาเดมี', 'https://www.youtube.com/channel/UCtTD069k4v4IAHpf708ykeQ', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-inertia'), 'youtube', 'https://www.youtube.com/watch?v=ILAeMFXXSoQ', 'ILAeMFXXSoQ', 'กฏของนิวตัน สรุปใน 10 นาที | ฟิสิกส์ ม.4 by ideal Physics', 'idealphysics', 'https://www.youtube.com/channel/UCeI4EJhc6yBMps4ZqCOFTnQ', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-inertia'), 'แบบทดสอบ: กฎข้อที่ 1 ของนิวตัน (ความเฉื่อย)', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-inertia')), 'choice', 'กฎข้อที่ 1 ของนิวตันกล่าวว่าอย่างไร', '["วัตถุยังคงอยู่นิ่งหรือเคลื่อนที่ด้วยความเร็วคงที่ ตราบที่ไม่มีแรงลัพธ์มากระทำ","ต้องมีแรงกระทำทุกครั้งที่วัตถุเคลื่อนที่","ความเร่งแปรผันตรงกับแรงลัพธ์","วัตถุทุกก้อนมีน้ำหนักเท่ากัน"]', '0', 'กฎข้อที่ 1 คือกฎความเฉื่อย วัตถุรักษาสภาพเดิม (นิ่งหรือเคลื่อนที่สม่ำเสมอ) เมื่อไม่มีแรงลัพธ์', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-inertia')), 'choice', 'ความเฉื่อยของวัตถุขึ้นอยู่กับปริมาณใด', '["ความเร็ว","มวล","เวลา","อุณหภูมิ"]', '1', 'ความเฉื่อยคือความต้านการเปลี่ยนสภาพการเคลื่อนที่ แปรผันตามมวล ยิ่งมวลมากยิ่งเฉื่อยมาก', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-inertia')), 'choice', 'ผู้โดยสารในรถที่เบรกกะทันหันจะเอนไปทางใด', '["ไปข้างหน้า","ไปข้างหลัง","ไม่ขยับเลย","ขึ้นด้านบน"]', '0', 'ตัวผู้โดยสารยังคงรักษาสภาพเคลื่อนที่ไปข้างหน้า ในขณะที่รถหยุด จึงรู้สึกถูกเหวี่ยงไปข้างหน้า', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-inertia')), 'number', 'มีแรง 8 นิวตันกระทำไปทางขวาอยู่แล้ว ต้องการให้แรงลัพธ์เป็นศูนย์ ต้องมีแรงอีกกี่นิวตันไปทางซ้าย (ตอบเป็นนิวตัน จำนวนเต็ม)', NULL, '{"value":8,"tolerance":0.5}', 'ต้องใช้แรงขนาดเท่ากันแต่ทิศตรงข้ามคือ 8 นิวตันไปทางซ้าย จึงจะหักล้างพอดี', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-inertia')), 'number', 'วัตถุเคลื่อนที่ไปทางขวาด้วยความเร็วคงที่ 5 เมตร/วินาทีโดยไม่มีแรงลัพธ์ หลังจาก 10 วินาทีความเร็วของวัตถุเป็นเท่าใด (ตอบเป็นเมตร/วินาที จำนวนเต็ม)', NULL, '{"value":5,"tolerance":0.5}', 'ไม่มีแรงลัพธ์ วัตถุเคลื่อนที่ด้วยความเร็วคงที่ตลอด ยังคงเป็น 5 เมตร/วินาที', 5);
