INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-second-law')), 'choice', 'กฎข้อที่ 2 ของนิวตันเขียนเป็นสมการได้ดังนี้', '["F = m / v","F = m + a","F = m x g","F = ma"]', '3', 'กฎข้อที่ 2 คือ F = ma หรือแรงลัพธ์เท่ากับมวลคูณความเร่ง นั่นคือ a = F/m', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-second-law')), 'choice', 'ถ้าแรงลัพธ์คงที่แล้วเพิ่มมวลเป็น 2 เท่า ความเร่งของวัตถุเป็นเท่าใดเมื่อเทียบกับเดิม', '["ครึ่งหนึ่งของเดิม","เท่าเดิม","สองเท่าของเดิม","สี่เท่าของเดิม"]', '0', 'a = F/m เมื่อมวลเพิ่มเป็น 2 เท่าด้วยแรงเท่าเดิม ความเร่งจึงลดลงเป็นครึ่งหนึ่ง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-second-law')), 'choice', 'แรงลัพธ์ 10 นิวตันกระทำกับมวล 2 กิโลกรัม ความเร่งเป็นเท่าใด', '["20 เมตร/วินาที²","5 เมตร/วินาที²","0.2 เมตร/วินาที²","12 เมตร/วินาที²"]', '1', 'a = F/m = 10 / 2 = 5 เมตร/วินาที²', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-second-law')), 'number', 'แรงลัพธ์ 30 นิวตันกระทำกับมวล 6 กิโลกรัม ความเร่งเป็นเท่าใด (ตอบเป็นเมตร/วินาที² จำนวนเต็ม)', NULL, '{"value":5,"tolerance":0.5}', 'a = F/m = 30 / 6 = 5 เมตร/วินาที²', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-second-law')), 'number', 'แรงลัพธ์ 45 นิวตันทำให้วัตถุมีความเร่ง 5 เมตร/วินาที² มวลของวัตถุเป็นเท่าใด (ตอบเป็นกิโลกรัม จำนวนเต็ม)', NULL, '{"value":9,"tolerance":0.5}', 'm = F/a = 45 / 5 = 9 กิโลกรัม', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'newton-laws'), 'newton-laws-third-law', 'กฎข้อที่ 3 ของนิวตัน', 'กฎข้อที่ 3 กล่าวว่า ทุกแรงกระทำย่อมมีแรงปฏิกิริยาขนาดเท่ากันทิศตรงข้าม แรงทั้งสองกระทำต่อคนละวัตถุ', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-third-law'), 'youtube', 'https://www.youtube.com/watch?v=49kgcKlI6Zg', '49kgcKlI6Zg', '3.3 แรงและกฎการเคลื่อนที่ของนิวตัน (Newton''s Laws of Motion) | ฟิสิกส์ ม.4 เทอม 1 | ฟิสิกส์ ม.ปลาย', 'ปลาอะคาเดมี', 'https://www.youtube.com/channel/UCtTD069k4v4IAHpf708ykeQ', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-third-law'), 'youtube', 'https://www.youtube.com/watch?v=yZyqRJgeRVU', 'yZyqRJgeRVU', 'ฟิสิกส์ ม.4 บทที่ 3 แรงและกฎการเคลื่อนที่ ep.6(โจทย์กฎการเคลื่อนที่ของนิวตัน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-third-law'), 'แบบทดสอบ: กฎข้อที่ 3 ของนิวตัน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-third-law')), 'choice', 'แรงกระทำและแรงปฏิกิริยาตามกฎข้อที่ 3 มีขนาดและทิศทางเป็นอย่างไร', '["ขนาดไม่เท่ากัน","ขนาดเท่ากันและทิศเดียวกัน","ขนาดเท่ากันและทิศตรงข้ามกัน","ขนาดแปรตามมวลของวัตถุ"]', '2', 'แรงคู่กิริยา-ปฏิกิริยามีขนาดเท่ากันเสมอและทิศตรงข้ามกัน แต่กระทำต่อคนละวัตถุ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-third-law')), 'choice', 'มือผลักกำแพงด้วยแรง 20 นิวตัน กำแพงจะผลักมือด้วยแรงเท่าใด', '["0 นิวตัน","10 นิวตัน","40 นิวตัน","20 นิวตัน"]', '3', 'ตามกฎข้อที่ 3 กำแพงผลักมือกลับด้วยแรงขนาดเท่ากันคือ 20 นิวตันในทิศตรงข้าม', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-third-law')), 'choice', 'แรงคู่กิริยา-ปฏิกิริยากระทำต่อสิ่งใด', '["คนละวัตถุ","วัตถุเดียวกัน","ทั้งคนละวัตถุหรือวัตถุเดียวกันแล้วแต่กรณี","ไม่มีผลต่อวัตถุใดเลย"]', '0', 'แรงทั้งสองกระทำต่อคนละวัตถุ (ตัวหนึ่งทำต่ออีกตัวหนึ่ง และกลับกัน) จึงไม่หักล้างกันในวัตถุเดียว', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-third-law')), 'number', 'มือผลักโต๊ะด้วยแรง 15 นิวตัน โต๊ะจะผลักมือด้วยแรงกี่นิวตัน (ตอบเป็นนิวตัน จำนวนเต็ม)', NULL, '{"value":15,"tolerance":0.5}', 'กฎข้อที่ 3 แรงปฏิกิริยามีขนาดเท่ากับแรงกระทำ คือ 15 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-third-law')), 'number', 'โลกดึงดูดวัตถุก้อนหนึ่งด้วยแรงโน้มถ่วง 50 นิวตัน วัตถุจะดึงดูดโลกด้วยแรงเท่าใด (ตอบเป็นนิวตัน จำนวนเต็ม)', NULL, '{"value":50,"tolerance":0.5}', 'แรงโน้มถ่วงเป็นแรงคู่กิริยา-ปฏิกิริยา วัตถุจึงดึงดูดโลกด้วยแรงเท่ากันคือ 50 นิวตัน แต่ทิศตรงข้าม', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'nuclear'), 'nuclear-elementary-particles', 'อนุภาคมูลฐาน', 'อนุภาคมูลฐานคืออนุภาคที่คิดว่าไม่ประกอบด้วยอนุภาคที่เล็กกว่า ได้แก่ ควาร์กและเลปตอน โปรตอนและนิวตรอนประกอบด้วยควาร์ก และมีการค้นพบปฏิอนุภาคที่มีสมบัติตรงข้าม', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'nuclear-elementary-particles'), 'youtube', 'https://www.youtube.com/watch?v=YaRCcS1g1Yc', 'YaRCcS1g1Yc', 'ฟิสิกส์ ม.6 บทที่ 20 ฟิสิกส์นิวเคลียร์และฟิสิกส์อนุภาค ep.10 (ฟิสิกส์อนุภาค ควาร์ก ปฏิยานุภาค)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'nuclear-elementary-particles'), 'แบบทดสอบ: อนุภาคมูลฐาน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-elementary-particles')), 'choice', 'โปรตอนและนิวตรอนประกอบด้วยอนุภาคที่เล็กกว่าชนิดใด', '["ควาร์ก","เลปตอน","โฟตอน","นิวตริโน"]', '0', 'โปรตอนและนิวตรอน (รวมเรียกว่าฮาดรอน) ประกอบด้วยควาร์ก โปรตอนมีองค์ประกอบ uud และนิวตรอนมี udd ส่วนเลปตอนเป็นอนุภาคมูลฐานอีกกลุ่ม เช่น อิเล็กตรอน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-elementary-particles')), 'choice', 'ปฏิอนุภาค (antiparticle) ของอิเล็กตรอนคืออนุภาคใด', '["ควาร์กอัปลง","โพซิตรอน","โปรตอน","นิวตรอน"]', '1', 'ปฏิอนุภาคของอิเล็กตรอนคือโพซิตรอน ซึ่งมีมวลเท่ากันแต่ประจุตรงข้าม (+1) เมื่ออิเล็กตรอนพบโพซิตรอนจะเกิดการทำลายล้างกันและปล่อยโฟตอน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-elementary-particles')), 'choice', 'อนุภาคใดต่อไปนี้จัดเป็นเลปตอน', '["นิวตรอน","โฟตอน","โปรตอน","อิเล็กตรอน"]', '3', 'เลปตอนคืออนุภาคมูลฐานที่ไม่ได้ประกอบด้วยควาร์ก ได้แก่ อิเล็กตรอน มิวออน เทา และนิวตริโน ส่วนโปรตอนและนิวตรอนเป็นฮาดรอน (ประกอบจากควาร์ก)', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-elementary-particles')), 'number', 'โปรตอนหนึ่งตัวประกอบด้วยควาร์ก 3 ตัว เป็นควาร์กอัพบน 2 ตัวและควาร์กอัปลง 1 ตัว จงหาจำนวนควาร์กในโปรตอน 100 ตัว โดยรวมควาร์กทั้งหมด (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":300,"tolerance":0.5}', 'โปรตอนแต่ละตัวมี 3 ควาร์ก ดังนั้น 100 ตัวมีควาร์ก 100 × 3 = 300 ตัว', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-elementary-particles')), 'number', 'ถ้าอิเล็กตรอนมีประจุ −1 หน่วย และโพซิตรอน (ปฏิอนุภาค) มีประจุตรงข้ามเท่ากัน จงหาผลรวมประจุของอิเล็กตรอนและโพซิตรอนหนึ่งคู่ในหน่วยประจุ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":0,"tolerance":0.5}', 'ประจุรวม = (−1) + (+1) = 0 หน่วยประจุ คู่อนุภาค-ปฏิอนุภาคมีประจุรวมศูนย์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'nuclear'), 'nuclear-fission-fusion', 'ปฏิกิริยานิวเคลียร์ ฟิชชันและฟิวชัน', 'ฟิชชันคือนิวเคลียสหนักแตกเป็นนิวเคลียสเล็กกว่าโดยปล่อยพลังงาน ส่วนฟิวชันคือนิวเคลียสเล็กหลอมรวมเป็นนิวเคลียสใหญ่ ทั้งสองปล่อยพลังงานมหาศาลจากมวลพร่อง', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'nuclear-fission-fusion'), 'youtube', 'https://www.youtube.com/watch?v=_IauthXazQU', '_IauthXazQU', 'ฟิสิกส์ ม.6 บทที่ 20 ฟิสิกส์นิวเคลียร์และฟิสิกส์อนุภาค ep.8 (ปฎิกิริยานิวเคลียร์ ฟิชชัน ฟิวชัน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'nuclear-fission-fusion'), 'แบบทดสอบ: ปฏิกิริยานิวเคลียร์ ฟิชชันและฟิวชัน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-fission-fusion')), 'choice', 'ปฏิกิริยาฟิชชัน (fission) คืออะไร', '["นิวเคลียสหนักแตกออกเป็นนิวเคลียสขนาดกลางโดยปล่อยพลังงาน","โปรตอนกลายเป็นนิวตรอน","อิเล็กตรอนรวมกับโปรตอน","นิวเคลียสเบาหลอมรวมกัน"]', '0', 'ฟิชชันคือนิวเคลียสหนักแตกตัวเป็นนิวเคลียสขนาดกลาง พร้อมปล่อยนิวตรอนและพลังงานมหาศาล เช่น ยูเรเนียม-235 แตกตัวเมื่อดูดซับนิวตรอน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-fission-fusion')), 'choice', 'ปฏิกิริยาฟิวชัน (fusion) คืออะไร', '["นิวตรอนสลาย","นิวเคลียสดูดซับอิเล็กตรอน","นิวเคลียสเบาสองตัวหลอมรวมเป็นนิวเคลียสใหญ่กว่าพร้อมปล่อยพลังงาน","นิวเคลียสแตกเป็นชิ้นเล็ก"]', '2', 'ฟิวชันคือนิวเคลียสเบา เช่น ไฮโดรเจน isotopes หลอมรวมเป็นนิวเคลียสใหญ่กว่า เช่น ฮีเลียม ปล่อยพลังงานมหาศาล เช่น ปฏิกิริยาที่เกิดในดวงอาทิตย์', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-fission-fusion')), 'choice', 'ปฏิกิริยาฟิวชันเป็นแหล่งพลังงานของสิ่งใด', '["แบตเตอรีรถยนต์","เครื่องยนต์ดีเซล","โรงไฟฟ้านิวเคลียร์ส่วนใหญ่","ดวงอาทิตย์และดาวฤกษ์"]', '3', 'ดวงอาทิตย์และดาวฤกษ์สร้างพลังงานจากปฏิกิริยาฟิวชันของไฮโดรเจนเป็นฮีเลียม ส่วนโรงไฟฟ้านิวเคลียร์ส่วนใหญ่ใช้ปฏิกิริยาฟิชชัน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-fission-fusion')), 'number', 'ปฏิกิริยาฟิวชันของไฮโดรเจนหนึ่งครั้งปล่อยพลังงาน 26 เมกะอิเล็กตรอนโวลต์ ถ้าเกิดปฏิกิริยา 5 ครั้ง พลังงานรวมที่ปล่อยเป็นกี่เมกะอิเล็กตรอนโวลต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":130,"tolerance":0.5}', 'พลังงานรวม = 26 × 5 = 130 เมกะอิเล็กตรอนโวลต์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-fission-fusion')), 'number', 'ยูเรเนียม-235 หนึ่งนิวเคลียสสลายตัวปล่อยพลังงาน 200 เมกะอิเล็กตรอนโวลต์ ถ้ามีนิวเคลียสสลายตัว 4 นิวเคลียส พลังงานรวมเป็นกี่เมกะอิเล็กตรอนโวลต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":800,"tolerance":0.5}', 'พลังงานรวม = 200 × 4 = 800 เมกะอิเล็กตรอนโวลต์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'nuclear'), 'nuclear-nucleus-binding-energy', 'โครงสร้างนิวเคลียสและพลังงานยึดเหนี่ยว', 'นิวเคลียสประกอบด้วยโปรตอนและนิวตรอนรวมเรียกว่านิวคลีออน พลังงานยึดเหนี่ยวคือพลังงานที่ยึดนิวคลีออนไว้ด้วยกัน คำนวณจากมวลพร่องตาม E = Δmc²', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'nuclear-nucleus-binding-energy'), 'youtube', 'https://www.youtube.com/watch?v=z6lyBq1VRig', 'z6lyBq1VRig', 'ฟิสิกส์ ม 6 บทที่ 20 ฟิสิกส์นิวเคลียร์และฟิสิกส์อนุภาค ep.1 (องค์ประกอบของนิวเคลียส ไอโซโทป)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'nuclear-nucleus-binding-energy'), 'youtube', 'https://www.youtube.com/watch?v=Si7P5hP_6k4', 'Si7P5hP_6k4', 'ฟิสิกส์ ม.6 บทที่ 20 ฟิสิกส์นิวเคลียร์และฟิสิกส์อนุภาค ep.2 แรงนิวเคลียร์ พลังงานยึดเหนี่ยว มวลพร่อง', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'nuclear-nucleus-binding-energy'), 'แบบทดสอบ: โครงสร้างนิวเคลียสและพลังงานยึดเหนี่ยว', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-nucleus-binding-energy')), 'choice', 'นิวเคลียสของอะตอมประกอบด้วยอนุภาคใด', '["โปรตอนเท่านั้น","โปรตอนและนิวตรอน","อิเล็กตรอนและโปรตอน","อิเล็กตรอนเท่านั้น"]', '1', 'นิวเคลียสประกอบด้วยโปรตอน (ประจุบวก) และนิวตรอน (ไม่มีประจุ) รวมเรียกว่านิวคลีออน ส่วนอิเล็กตรอนโคจรรอบนิวเคลียส', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-nucleus-binding-energy')), 'choice', 'เลขมวล (mass number) ของนิวเคลียส หมายถึงอะไร', '["จำนวนโปรตอน","จำนวนนิวตรอน","จำนวนโปรตอนรวมกับนิวตรอน","จำนวนอิเล็กตรอน"]', '2', 'เลขมวล A = จำนวนโปรตอน (Z) + จำนวนนิวตรอน (N) คือจำนวนนิวคลีออนทั้งหมด ส่วนเลขอะตอม Z คือจำนวนโปรตอน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-nucleus-binding-energy')), 'choice', 'มวลพร่อง (mass defect) ของนิวเคลียสคืออะไร', '["มวลนิวเคลียสจริงมากกว่าผลรวมมวลนิวคลีออน","มวลของนิวตรอนลบมวลโปรตอน","ไม่มีนิยาม","ผลรวมมวลนิวคลีออนมากกว่า มวลนิวเคลียสจริง"]', '3', 'มวลพร่อง = มวลรวมนิวคลีออนที่แยกกัน − มวลนิวเคลียสจริง มวลที่หายไปเปลี่ยนเป็นพลังงานยึดเหนี่ยวตาม E = Δmc² ซึ่งเป็นสาเหตุที่นิวเคลียสเสถียร', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-nucleus-binding-energy')), 'number', 'นิวเคลียสไอโซโทปหนึ่งมีเลขมวล 27 และจำนวนโปรตอน 13 จำนวนนิวตรอนในนิวเคลียสเป็นกี่ตัว (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":14,"tolerance":0.5}', 'จำนวนนิวตรอน = เลขมวล − จำนวนโปรตอน = 27 − 13 = 14 ตัว', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-nucleus-binding-energy')), 'number', 'ไอโซโทปหนึ่งมีนิวตรอน 8 ตัว และเลขมวล 16 จำนวนโปรตอนเท่ากับกี่ตัว (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":8,"tolerance":0.5}', 'จำนวนโปรตอน Z = เลขมวล − จำนวนนิวตรอน = 16 − 8 = 8 โปรตอน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'nuclear'), 'nuclear-radioactivity-half-life', 'กัมมันตภาพรังสีและครึ่งชีวิต', 'ธาตุกัมมันตรังสีสลายตัวปล่อยรังสีแอลฟา บีตา และแกมมา โดยไม่ขึ้นกับสภาวะภายนอก ครึ่งชีวิตคือเวลาที่ปริมาณนิวเคลียสสลายเหลือครึ่งหนึ่ง ใช้คำนวณการสลายตัวแบบเลขชี้กำลัง', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'nuclear-radioactivity-half-life'), 'youtube', 'https://www.youtube.com/watch?v=Zt3rB4sofhA', 'Zt3rB4sofhA', 'ฟิสิกส์ ม.6 บทที่ 20 ฟิสิกส์นิวเคลียร์และฟิสิกส์อนุภาค ep.4 (การสลายตัวให้ รังสีแอลฟา บีต้า แกมมา)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'nuclear-radioactivity-half-life'), 'youtube', 'https://www.youtube.com/watch?v=56ytR_GLABU', '56ytR_GLABU', 'ฟิสิกส์ ม.6 บทที่ 20 ฟิสิกส์นิวเคลียร์และฟิสิกส์อนุภาค ep.5 การสลายตัวของธาตุกัมมันตรังสี ครึ่งชีวิต', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'nuclear-radioactivity-half-life'), 'youtube', 'https://www.youtube.com/watch?v=NCdKvLFzX5c', 'NCdKvLFzX5c', 'ฟิสิกส์ ม.6 บทที่ 20 ฟิสิกส์นิวเคลียร์และฟิสิกส์อนุภาค ep. 7 (อุปมาอุปมัย การทอดลูกเต๋า ครึ่งชีวิต)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 3);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'nuclear-radioactivity-half-life'), 'แบบทดสอบ: กัมมันตภาพรังสีและครึ่งชีวิต', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-radioactivity-half-life')), 'choice', 'รังสีชนิดใดเป็นคลื่นแม่เหล็กไฟฟ้า ไม่มีประจุและไม่มีมวล', '["รังสีแกมมา","รังสีโพซิตรอน","รังสีแอลฟา","รังสีบีตา"]', '0', 'รังสีแกมมาเป็นคลื่นแม่เหล็กไฟฟ้าพลังงานสูง ไม่มีประจุและมวล ส่วนแอลฟาคือนิวเคลียสฮีเลียม (ประจุ +2) และบีตาเป็นอิเล็กตรอนหรือโพซิตรอน (มีมวล)', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-radioactivity-half-life')), 'choice', 'ครึ่งชีวิต (half-life) ของธาตุกัมมันตรังสี หมายถึงอะไร', '["เวลาที่ธาตุสลายตัวหมดพอดี","เวลาที่จำนวนนิวเคลียสสลายเหลือครึ่งหนึ่งของเดิม","เวลาที่ธาตุเพิ่มเป็นครึ่งเท่า","เวลาครึ่งวันเท่านั้น"]', '1', 'ครึ่งชีวิต คือ เวลาที่นิวเคลียสกัมมันตรังสีสลายจนเหลือครึ่งหนึ่งของจำนวนเริ่มต้น ใช้เป็นเอกลักษณ์ของธาตุกัมมันตรังสีแต่ละชนิด', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-radioactivity-half-life')), 'choice', 'อัตราการสลายตัว (ค่า N ที่สลายต่อเวลา) ของธาตุกัมมันตรังสีแปรผันอย่างไรกับจำนวนนิวเคลียสที่เหลือ', '["คงที่เสมอ","ไม่ขึ้นกับจำนวน","แปรผันตรงกับจำนวนนิวเคลียสที่เหลือ","แปรผกผันกับจำนวนที่เหลือ"]', '2', 'อัตราการสลายตัว (−dN/dt) แปรผันตรงกับจำนวนนิวเคลียสที่เหลือ N จึงเป็นกระบวนการเลขชี้กำลัง ยิ่งมีนิวเคลียสมาก อัตราการสลายยิ่งมาก', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-radioactivity-half-life')), 'number', 'ธาตุกัมมันตรังสีมีครึ่งชีวิต 8 ชั่วโมง เริ่มต้นมีสาร 80 กรัม หลังจาก 24 ชั่วโมง เหลือสารกี่กรัม (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":10,"tolerance":0.5}', '24 ชั่วโมง = 3 ครึ่งชีวิต สารเหลือ 80 × (1/2)³ = 80 × 1/8 = 10 กรัม', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-radioactivity-half-life')), 'number', 'ธาตุกัมมันตรังสีมีครึ่งชีวิต 5 ปี ถ้าเริ่มต้น 160 กรัม ต้องใช้เวลากี่ปีจึงเหลือ 20 กรัม (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":15,"tolerance":0.5}', '160 → 80 (5 ปี) → 40 (10 ปี) → 20 (15 ปี) ใช้ 3 ครึ่งชีวิต คือ 15 ปี', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'oscillation-gravity'), 'oscillation-energy', 'พลังงานของการสั่น', 'พลังงานกลรวมของการสั่นคงที่เท่ากับ ½kA² เปลี่ยนไปมาระหว่างพลังงานจลน์สูงสุดที่จุดสมดุลและพลังงานศักย์สูงสุดที่จุดปลาย', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'oscillation-energy'), 'youtube', 'https://www.youtube.com/watch?v=aVL45rAUH14', 'aVL45rAUH14', 'ฟิสิกส์ ม.5 บทที่ 8 การเคลื่อนที่แบบฮาร์มอนิกอย่างง่าย ep.4', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'oscillation-energy'), 'แบบทดสอบ: พลังงานของการสั่น', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'oscillation-energy')), 'choice', 'พลังงานกลรวมของการสั่นของสปริงค่าคงที่ k แอมพลิจูด A มีค่าเท่าใด', '["E = ½kA²","E = kA","E = ½kA","E = kA²"]', '0', 'พลังงานกลรวมของ SHM คงที่เท่ากับ ½kA² ซึ่งคือพลังงานศักย์สูงสุดที่จุดปลายของการแกว่ง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'oscillation-energy')), 'choice', 'วัตถุแกว่งผ่านตำแหน่งสมดุลพอดี ความเร็วมีค่าสูงสุด พลังงานของระบบเป็นอย่างไร', '["เป็นพลังงานจลน์สูงสุดและพลังงานศักย์เป็นศูนย์","เป็นพลังงานศักย์สูงสุด","พลังงานทั้งสองเป็นศูนย์","พลังงานจลน์เป็นศูนย์"]', '1', 'ที่จุดสมดุลความเร็วสูงสุดพลังงานจลน์จึงสูงสุด และการกระจัดเป็นศูนย์พลังงานศักย์จึงเป็นศูนย์', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'oscillation-energy')), 'choice', 'วัตถุอยู่ที่จุดปลายของการแกว่ง (การกระจัด = ±A) พลังงานของระบบเป็นอย่างไร', '["เป็นพลังงานจลน์สูงสุด","เป็นพลังงานศักย์สูงสุด ความเร็วเป็นศูนย์","พลังงานทั้งหมดเป็นศูนย์","เป็นพลังงานความร้อน"]', '0', 'ที่จุดปลายการกระจัดมากสุดพลังงานศักย์จึงสูงสุด ความเร็วเป็นศูนย์พลังงานจลน์จึงเป็นศูนย์', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'oscillation-energy')), 'number', 'สปริงค่าคงที่ 200 นิวตัน/เมตร ยืดออกจากจุดสมดุลสูงสุด 0.1 เมตร พลังงานกลรวมของการสั่นมีค่ากี่จูล', NULL, '{"value":1,"tolerance":0.5}', 'E = ½kA² = ½ × 200 × 0.1² = ½ × 200 × 0.01 = 1 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'oscillation-energy')), 'number', 'สปริงค่าคงที่ 100 นิวตัน/เมตร ยืดออกจากจุดสมดุลสูงสุด 0.1 เมตร พลังงานกลรวมของการสั่นมีค่ากี่จูล', NULL, '{"value":0.5,"tolerance":0.05}', 'E = ½kA² = ½ × 100 × 0.1² = ½ × 100 × 0.01 = 0.5 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'oscillation-gravity'), 'oscillation-spring-pendulum', 'สปริงและลูกตุ้ม', 'คาบของสปริง T = 2π√(m/k) และคาบของลูกตุ้มอย่างง่าย T = 2π√(L/g) โดยคาบลูกตุ้มไม่ขึ้นกับมวล', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'oscillation-spring-pendulum'), 'youtube', 'https://www.youtube.com/watch?v=efuc3Ys664w', 'efuc3Ys664w', 'ฟิสิกส์ ม.5 บทที่ 8 การเคลื่อนที่แบบฮาร์มอนิกอย่างง่าย ep.3', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'oscillation-spring-pendulum'), 'youtube', 'https://www.youtube.com/watch?v=aVL45rAUH14', 'aVL45rAUH14', 'ฟิสิกส์ ม.5 บทที่ 8 การเคลื่อนที่แบบฮาร์มอนิกอย่างง่าย ep.4', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'oscillation-spring-pendulum'), 'แบบทดสอบ: สปริงและลูกตุ้ม', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'oscillation-spring-pendulum')), 'choice', 'คาบการแกว่งของสปริงมวล m ค่าคงที่สปริง k หาได้จากข้อใด', '["T = 2π√(m/k)","T = 2π√(k/m)","T = 2π√(mk)","T = m/k"]', '0', 'คาบสปริง T = 2π√(m/k) คาบเพิ่มขึ้นเมื่อมวลเพิ่มหรือสปริงอ่อนลง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'oscillation-spring-pendulum')), 'choice', 'คาบของลูกตุ้มอย่างง่ายขึ้นกับปริมาณใด', '["มวลของลูกตุ้ม","ความยาวเชือกและความเร่งโน้มถ่วง","แอมพลิจูด","เฉพาะมวลและแอมพลิจูด"]', '1', 'คาบลูกตุ้ม T = 2π√(L/g) ขึ้นกับความยาวเชือกและความเร่งโน้มถ่วง ไม่ขึ้นกับมวลหรือแอมพลิจูด', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'oscillation-spring-pendulum')), 'choice', 'ถ้าเพิ่มมวลที่ห้อยกับสปริงเป็น 4 เท่า (สปริงเดียวกัน) คาบการแกว่งเปลี่ยนเป็นกี่เท่าของเดิม', '["4 เท่า","2 เท่า","เท่าเดิม","ครึ่งหนึ่ง"]', '1', 'T ∝ √m เมื่อ m เป็น 4 เท่า T จึงเป็น √4 = 2 เท่าของเดิม', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'oscillation-spring-pendulum')), 'number', 'ลูกตุ้มอย่างง่ายยาว 2.5 เมตร ในที่ที่มี g = 10 เมตร/วินาที² คาบการแกว่งมีค่ากี่วินาที (ใช้ π ≈ 3.14 ตอบเป็นทศนิยม 2 ตำแหน่ง)', NULL, '{"value":3.14,"tolerance":0.005}', 'T = 2π√(L/g) = 2π√(2.5/10) = 2π×0.5 = π ≈ 3.14 วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'oscillation-spring-pendulum')), 'number', 'สปริงค่าคงที่ 100 นิวตัน/เมตร ห้อยมวล 1 กิโลกรัม คาบการแกว่งมีค่ากี่วินาที (ใช้ π ≈ 3.14 ตอบเป็นทศนิยม 2 ตำแหน่ง)', NULL, '{"value":0.63,"tolerance":0.005}', 'T = 2π√(m/k) = 2π√(1/100) = 2π×0.1 = 0.2π ≈ 0.628 ≈ 0.63 วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'projectile'), 'projectile-application', 'การประยุกต์โพรเจกไทล์', 'นำความรู้โพรเจกไทล์ไปใช้กับสถานการณ์จริง เช่น การยิง การขว้าง และการตกจากที่สูง โดยแยกวิเคราะห์แนวราบกับแนวตั้ง', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
