INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-intro'), 'aim-and-shoot', 'ยิงให้ถูกเป้า', '{"targetDistance":[40,120],"tolerance":3}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-intro'), 'แบบทดสอบ: โพรเจกไทล์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-intro')), 'choice', 'ในการเคลื่อนที่แบบโพรเจกไทล์ (ไม่คิดแรงต้านอากาศ) ความเร็วในแนวราบเปลี่ยนแปลงอย่างไร', '["เพิ่มขึ้นเรื่อยๆ","ลดลงเรื่อยๆ","คงที่","เป็นศูนย์ที่จุดสูงสุด"]', '2', 'ในแนวราบไม่มีแรงกระทำ (เมื่อไม่คิดแรงต้านอากาศ) ความเร่งแนวราบจึงเป็นศูนย์ ความเร็วแนวราบคงที่ตลอดการเคลื่อนที่', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-intro')), 'choice', 'ที่จุดสูงสุดของวิถี ความเร็วในแนวตั้งมีค่าเท่าใด', '["เท่ากับความเร็วต้นในแนวตั้ง","เป็นศูนย์","เท่ากับ g","มากที่สุด"]', '1', 'ที่จุดสูงสุดวัตถุเปลี่ยนจากขึ้นเป็นลง ความเร็วแนวตั้งจึงเป็นศูนย์ แต่ความเร็วแนวราบยังมีอยู่ และความเร่งยังเท่ากับ g ในทิศลง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-intro')), 'choice', 'ถ้าความเร็วต้นเท่ากัน และไม่คิดแรงต้านอากาศ มุมยิงใดทำให้ระยะทางในแนวราบไกลที่สุด', '["30 องศา","45 องศา","60 องศา","90 องศา"]', '1', 'ระยะทางแนวราบ R = v² sin 2θ / g และ sin 2θ มีค่ามากที่สุดเมื่อ 2θ = 90 องศา คือ θ = 45 องศา', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-intro')), 'number', 'ยิงวัตถุด้วยความเร็วต้น 20 เมตร/วินาที ที่มุม 30 องศากับแนวราบ วัตถุอยู่ในอากาศนานกี่วินาที (ใช้ g = 10 เมตร/วินาที²)', NULL, '{"value":2,"tolerance":0.05}', 'เวลาที่ลอย T = 2v sin θ / g = 2 × 20 × 0.5 / 10 = 2 วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-intro')), 'number', 'จากข้อก่อนหน้า วัตถุตกห่างจุดยิงในแนวราบกี่เมตร (ใช้ g = 10 เมตร/วินาที²)', NULL, '{"value":34.6,"tolerance":0.5}', 'R = v cos θ × T = 20 × 0.866 × 2 ≈ 34.6 เมตร (หรือใช้ R = v² sin 2θ / g = 400 × 0.866 / 10)', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'projectile'), 'projectile-range-time', 'ระยะไกลสุดและเวลาบิน', 'เวลาบิน T = 2v sin θ / g และระยะไกลสุด R = v² sin 2θ / g ระยะไกลที่สุดเมื่อยิงมุม 45 องศา', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-range-time'), 'youtube', 'https://www.youtube.com/watch?v=ZrFyxC3x3-w', 'ZrFyxC3x3-w', 'ฟิสิกส์ ม.4 บทที่ 7 การเคลื่อนที่แนวโค้ง ep.2 (การเคลื่อนที่แบบโพรเจกไทล์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-range-time'), 'youtube', 'https://www.youtube.com/watch?v=UTMXSCv2Slo', 'UTMXSCv2Slo', 'ฟิสิกส์ ม.4 บทที่ 7 การเคลื่อนที่แนวโค้ง ep.1 (การเคลื่อนที่แบบโพรเจกไทล์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-range-time'), 'projectile', 'ปรับมุมและความเร็ว แล้วดูระยะไกลและเวลาบิน', '{"angle":{"min":10,"max":80,"default":45},"speed":{"min":10,"max":40,"default":25}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-range-time'), 'aim-and-shoot', 'ยิงให้โดนเป้า: ปรับมุมและความเร็ว', '{"targetDistance":[40,120],"tolerance":3}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-range-time'), 'แบบทดสอบ: ระยะไกลสุดและเวลาบิน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-range-time')), 'choice', 'เมื่อความเร็วต้นเท่ากันและไม่คิดแรงต้านอากาศ มุมยิงใดให้ระยะทางแนวราบไกลที่สุด', '["30 องศา","60 องศา","90 องศา","45 องศา"]', '3', 'R = v² sin 2θ / g มีค่ามากสุดเมื่อ sin 2θ = 1 นั่นคือ 2θ = 90 หรือ θ = 45 องศา', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-range-time')), 'choice', 'ยิงด้วยความเร็วต้นเท่ากันที่มุม 30 องศากับมุม 60 องศา ระยะไกลสุดเป็นอย่างไร', '["เท่ากัน","มุม 30 องศาไกลกว่า","มุม 60 องศาไกลกว่า","มุม 60 องศาไกลเป็นสองเท่า"]', '0', 'sin 2θ ของ 30° คือ sin 60° และของ 60° คือ sin 120° ซึ่งเท่ากัน ระยะไกลจึงเท่ากัน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-range-time')), 'choice', 'เวลาบินของโพรเจกไทล์ขึ้นกับปัจจัยใดเป็นหลัก', '["ระยะทางแนวราบล้วน","ความเร็วเริ่มต้นในแนวตั้ง","มวลของวัตถุ","ความเร็วแนวราบเท่านั้น"]', '1', 'เวลาบิน T = 2v sin θ / g ขึ้นกับความเร็วเริ่มต้นในแนวตั้ง (v sin θ) ไม่ขึ้นกับมวล', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-range-time')), 'number', 'ยิงด้วยความเร็วต้น 20 เมตร/วินาทีที่มุม 30 องศากับแนวราบ เวลาบินเป็นเท่าใด (ใช้ g = 10 เมตร/วินาที² และ sin 30° = 0.5 ตอบเป็นวินาที จำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'T = 2v sin θ / g = 2 x 20 x 0.5 / 10 = 2 วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-range-time')), 'number', 'ยิงด้วยความเร็วต้น 20 เมตร/วินาทีที่มุม 30 องศากับแนวราบ ระยะไกลสุดเป็นเท่าใด (ใช้ g = 10 เมตร/วินาที² และ sin 60° ≈ 0.866 ตอบเป็นเมตร ทศนิยม 1 ตำแหน่ง)', NULL, '{"value":34.6,"tolerance":0.05}', 'R = v² sin 2θ / g = 400 x 0.866 / 10 = 34.64 ≈ 34.6 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'quantum-atom'), 'quantum-atomic-spectrum', 'สเปกตรัมของอะตอม', 'อะตอมดูดกลืนและปล่อยแสงเฉพาะความยาวคลื่นบางค่าเกิดเป็นเส้นสเปกตรัม เส้นสเปกตรัมของไฮโดรเจนคำนวณได้จากสูตรของบัลเมอร์ สเปกตรัมแต่ละเส้นมาจากการเปลี่ยนระดับพลังงานของอิเล็กตรอน', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'quantum-atomic-spectrum'), 'youtube', 'https://www.youtube.com/watch?v=TuZm5WZCPcw', 'TuZm5WZCPcw', 'ฟิสิกส์ ม.6 บทที่ 19 ฟิสิกส์อะตอม ep.8(อนุกรมของสเปกตรัม การแผ่รังสีของวัตถุดำ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'quantum-atomic-spectrum'), 'แบบทดสอบ: สเปกตรัมของอะตอม', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-atomic-spectrum')), 'choice', 'เส้นสเปกตรัมของอะตอมไฮโดรเจนเกิดจากอะไร', '["การเปลี่ยนระดับพลังงานของอิเล็กตรอนระหว่างวงโคจร","การสั่นของนิวตรอน","การหมุนของโปรตอน","การรวมตัวของนิวเคลียส"]', '0', 'เมื่ออิเล็กตรอนเปลี่ยนระหว่างระดับพลังงาน จะปล่อยหรือดูดซับโฟตอนพลังงาน ΔE = hf แต่ละเส้นสเปกตรัมตรงกับความถี่เฉพาะที่มาจากพลังงานระดับคู่หนึ่ง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-atomic-spectrum')), 'choice', 'สเปกตรัมของไฮโดรเจนแบบอนุกรมบัลเมอร์อยู่ในช่วงแสงใด', '["อัลตราไวโอเลต","แสงที่มองเห็น","อินฟราเรด","รังสีเอกซ์"]', '1', 'อนุกรมบัลเมอร์เป็นการเปลี่ยนอิเล็กตรอนมายังระดับ n = 2 โดยส่วนใหญ่อยู่ในช่วงแสงที่มองเห็นได้ ส่วนอนุกรมไลแมน (ไป n=1) อยู่ในช่วงอัลตราไวโอเลต', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-atomic-spectrum')), 'choice', 'สเปกตรัมแบบเส้น (line spectrum) ของธาตุแต่ละธาตุเป็นอย่างไร', '["เป็นสีรุ้งต่อเนื่องเหมือนกัน","ไม่มีสี","เหมือนกันทุกธาตุ","มีความยาวคลื่นเฉพาะตัวต่างกัน"]', '3', 'ธาตุแต่ละชนิดมีระดับพลังงานเฉพาะตัว เส้นสเปกตรัมจึงมีตำแหน่ง/ความยาวคลื่นเฉพาะตัวเช่นกัน ใช้ระบุธาตุได้ (fingerprint ของธาตุ)', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-atomic-spectrum')), 'number', 'อิเล็กตรอนตกจากระดับพลังงาน −0.85 อิเล็กตรอนโวลต์ ไปยัง −1.51 อิเล็กตรอนโวลต์ พลังงานโฟตอนที่ปล่อยออกมาเท่ากับกี่อิเล็กตรอนโวลต์ (ตอบเป็นทศนิยม 2 ตำแหน่ง)', NULL, '{"value":0.66,"tolerance":0.005}', 'ΔE = (−0.85) − (−1.51) = 0.66 อิเล็กตรอนโวลต์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-atomic-spectrum')), 'number', 'อิเล็กตรอนตกจากระดับพลังงาน −0.85 อิเล็กตรอนโวลต์ ไปยังระดับพลังงาน −15.0 อิเล็กตรอนโวลต์ พลังงานโฟตอนที่ปล่อยออกมาเท่ากับกี่อิเล็กตรอนโวลต์ (ตอบเป็นทศนิยม 2 ตำแหน่ง)', NULL, '{"value":14.15,"tolerance":0.005}', 'ΔE = (−0.85) − (−15.0) = 14.15 อิเล็กตรอนโวลต์ พลังงานโฟตอนเท่ากับผลต่างของระดับพลังงานทั้งสอง', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'quantum-atom'), 'quantum-bohr-model', 'แบบจำลองอะตอมของบอร์', 'แบบจำลองของบอร์กล่าวว่าอิเล็กตรอนโคจรรอบนิวเคลียสเฉพาะวงโคจรที่โมเมนตัมเชิงมุมเป็นพหุคูณของ h/2π และเปลี่ยนวงโคจรโดยปล่อยหรือรับโฟตอนตาม ΔE = hf', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
