INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'quantum-bohr-model'), 'youtube', 'https://www.youtube.com/watch?v=NEHvKmJK1qA', 'NEHvKmJK1qA', 'ฟิสิกส์ ม.6 บทที่ 19 ฟิสิกส์อะตอม ep.5(แบบจำลองอะตอมของทอมสันและรัทเอชทอร์ฟอร์ด)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'quantum-bohr-model'), 'แบบทดสอบ: แบบจำลองอะตอมของบอร์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-bohr-model')), 'choice', 'สมมติฐานสำคัญของบอร์เกี่ยวกับวงโคจรของอิเล็กตรอนในอะตอมไฮโดรเจนคือข้อใด', '["อิเล็กตรอนโคจรได้เฉพาะรัศมีที่กำหนดให้เท่านั้น","อิเล็กตรอนอยู่นิ่งที่นิวเคลียส","อิเล็กตรอนไม่มีวงโคจร","อิเล็กตรอนโคจรได้ทุกรัศมี"]', '0', 'บอร์เสนอว่าอิเล็กตรอนโคจรได้เฉพาะวงโคจรที่เสถียรบางวง โดยมีเงื่อนไขโมเมนตัมเชิงมุม mvr = nh/2π รัศมีจึงถูกกำหนดเป็นค่าเฉพาะ (quantized)', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-bohr-model')), 'choice', 'เมื่ออิเล็กตรอนเปลี่ยนจากวงโคจรพลังงานสูงไปวงโคจรพลังงานต่ำ ผลคืออะไร', '["ปล่อยอิเล็กตรอนออกมา","ดูดซับโฟตอน","ปล่อยโฟตอนออกมา","ไม่มีการเปลี่ยนแปลง"]', '2', 'เมื่ออิเล็กตรอนตกจากระดับพลังงานสูงไปต่ำ พลังงานส่วนต่าง ΔE ปล่อยออกมาเป็นโฟตอนตาม ΔE = hf ทำให้เกิดเส้นสเปกตรัมการแผ่รังสี', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-bohr-model')), 'choice', 'พลังงานของอิเล็กตรอนในวงโคจรที่ n ของอะตอมไฮโดรเจนมีค่าเป็นอย่างไรตามแบบจำลองของบอร์', '["เป็นบวกเสมอ","เท่ากันทุกวง","เป็นไปอย่างต่อเนื่อง","มีค่าไม่ต่อเนื่องและเป็นลบ"]', '3', 'พลังงานอิเล็กตรอนในแบบจำลองบอร์มีค่าไม่ต่อเนื่อง (quantized) และเป็นลบ เพราะอิเล็กตรอนถูกยึดเหนี่ยวกับนิวเคลียส E = −13.6/n² อิเล็กตรอนวอลต์ ยิ่ง n มากพลังงานยิ่งสูง (เป็นลบน้อยลง)', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-bohr-model')), 'number', 'อิเล็กตรอนในอะตอมไฮโดรเจนเปลี่ยนจากระดับพลังงาน −1.51 อิเล็กตรอนโวลต์ ไปยังระดับ −3.40 อิเล็กตรอนโวลต์ พลังงานโฟตอนที่ปล่อยออกมาเท่ากับกี่อิเล็กตรอนโวลต์ (ตอบเป็นทศนิยม 2 ตำแหน่ง)', NULL, '{"value":1.89,"tolerance":0.005}', 'ΔE = Eสูง − Eต่ำ = (−1.51) − (−3.40) = 1.89 อิเล็กตรอนโวลต์ พลังงานส่วนนี้ปล่อยเป็นโฟตอน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-bohr-model')), 'number', 'อิเล็กตรอนในอะตอมไฮโดรเจนระดับ n = 2 มีพลังงาน −3.4 อิเล็กตรอนโวลต์ และระดับ n = 1 มีพลังงาน −13.6 อิเล็กตรอนโวลต์ ถ้าอิเล็กตรอนตกจาก n = 2 ไป n = 1 พลังงานโฟตอนที่ปล่อยเท่ากับกี่อิเล็กตรอนโวลต์ (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":10.2,"tolerance":0.05}', 'ΔE = −3.4 − (−13.6) = 10.2 อิเล็กตรอนโวลต์ พลังงานนี้ปล่อยเป็นโฟตอนเมื่ออิเล็กตรอนตกระดับ', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'quantum-atom'), 'quantum-de-broglie', 'สมบัติคลื่นของอนุภาค เดอบรอยล์', 'เดอบรอยล์เสนอว่าอนุภาคทุกชนิดมีความยาวคลื่นที่เกี่ยวข้องกับโมเมนตัมตามสมการ λ = h/p อนุภาคมวลมากจึงมีความยาวคลื่นสั้นมากจนไม่สังเกตเห็นสมบัติคลื่น', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'quantum-de-broglie'), 'youtube', 'https://www.youtube.com/watch?v=vBjPJqRarvs', 'vBjPJqRarvs', 'ฟิสิกส์ ม.6 บทที่ 19 ฟิสิกส์อะตอม ep.14 (ความยาวคลื่นเดอบรอยล์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'quantum-de-broglie'), 'แบบทดสอบ: สมบัติคลื่นของอนุภาค เดอบรอยล์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-de-broglie')), 'choice', 'ความยาวคลื่นเดอบรอยล์ของอนุภาคคำนวณได้จากสูตรใด', '["λ = mv/h","λ = h/p","λ = hf","λ = h c"]', '1', 'λ = h/p โดย p คือโมเมนตัมของอนุภาค (p = mv) และ h คือค่าคงที่ของพลังค์ ความยาวคลื่นแปรผกผันกับโมเมนตัม', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-de-broglie')), 'choice', 'ถ้าเพิ่มโมเมนตัมของอนุภาคเป็น 2 เท่า ความยาวคลื่นเดอบรอยล์จะเปลี่ยนเป็นกี่เท่า', '["เท่าเดิม","2 เท่า","1/2 เท่า","4 เท่า"]', '2', 'λ = h/p แปรผกผันกับโมเมนตัม เมื่อ p เป็น 2 เท่า λ จึงเป็น 1/2 เท่า', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-de-broglie')), 'choice', 'เหตุใดวัตถุมหภาค เช่น ลูกบอล จึงไม่แสดงสมบัติคลื่นให้สังเกตได้ชัดเจน', '["เพราะ h มีค่าเป็นศูนย์","เพราะความเร็วเป็นศูนย์เสมอ","เพราะไม่มีโมเมนตัม","เพราะความยาวคลื่นเดอบรอยล์สั้นมากจนมองไม่เห็น"]', '3', 'วัตถุมหภาคมีมวลมาก ทำให้โมเมนตัม p ใหญ่ ความยาวคลื่น λ = h/p จึงสั้นมากจนเล็กเกินกว่าจะสังเกตสมบัติคลื่นได้ อิเล็กตรอนและอนุภาคขนาดเล็กเท่านั้นที่เห็นสมบัติคลื่นชัด', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-de-broglie')), 'number', 'ความยาวคลื่นเดอบรอยล์ λ = h/p ถ้าอนุภาคมีโมเมนตัม p ความยาวคลื่นคำนวณได้ 4 นาโนเมตร ถ้าเพิ่มโมเมนตัมเป็น 2 เท่า ความยาวคลื่นใหม่เป็นกี่นาโนเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'λ แปรผกผันกับโมเมนตัม เมื่อ p เป็น 2 เท่า λ เหลือครึ่งหนึ่ง = 2 นาโนเมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-de-broglie')), 'number', 'อิเล็กตรอนมีความเร็ว v โมเมนตัม mv ตามสูตรความยาวคลื่นเดอบรอยล์ λ = h/(mv) ถ้าเครื่องเร่งเพิ่มความเร็วเป็น 3 เท่า ความยาวคลื่นลดลงเหลือกี่ส่วนของเดิม (ตอบเป็นจำนวนเต็มในรูปแบบ a ใน b ซึ่งเป็นเศษส่วนง่าย ใช้ตอบ 0.333...)', NULL, '{"value":0.333,"tolerance":0.005}', 'λ แปรผกผันกับ v λ ∝ 1/v เมื่อ v เป็น 3 เท่า λ เหลือ 1/3 ของเดิม ≈ 0.333', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'quantum-atom'), 'quantum-photoelectric-effect', 'ปรากฏการณ์โฟโตอิเล็กทริก', 'แสงมีความถี่สูงกว่าความถี่ขีดเริ่มทำให้โลหะปล่อยอิเล็กตรอนได้ พลังงานโฟตอน hf ใช้เอาชนะฟังก์ชันงาน φ และส่วนที่เหลือเป็นพลังงานจลน์ของอิเล็กตรอน hf = φ + ½mv²', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'quantum-photoelectric-effect'), 'youtube', 'https://www.youtube.com/watch?v=wxOM8flajI8', 'wxOM8flajI8', 'ฟิสิกส์ ม.6 บทที่ 19 ฟิสิกส์อะตอม ep.12 (ปรากฎการณ์โฟโตอิเล็กทริก)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'quantum-photoelectric-effect'), 'แบบทดสอบ: ปรากฏการณ์โฟโตอิเล็กทริก', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-photoelectric-effect')), 'choice', 'สมการของไอน์สไตน์สำหรับปรากฏการณ์โฟโตอิเล็กทริกคือข้อใด', '["hf = φ + ½mv²","hf = ½mv² − φ","E = hλ","hf = φ − ½mv²"]', '0', 'hf = φ + ½mv² พลังงานของโฟตอนใช้เอาชนะฟังก์ชันงาน φ ของโลหะ และส่วนที่เหลือกลายเป็นพลังงานจลน์สูงสุดของอิเล็กตรอน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-photoelectric-effect')), 'choice', 'ปรากฏการณ์โฟโตอิเล็กทริกแสดงว่าแสงมีสมบัติแบบใดเป็นหลัก', '["เป็นคลื่นต่อเนื่อง","เป็นกลุ่มพลังงานหรือโฟตอน","เป็นอนุภาคมวลขนาดใหญ่","ไม่มีพลังงาน"]', '1', 'การที่อิเล็กตรอนปล่อยออกมาทันทีโดยไม่ขึ้นกับความเข้มแสง แสดงว่าแสงประกอบด้วยโฟตอนพลังงาน hf ที่เป็นก้อน จึงสนับสนุนสมบัติอนุภาคของแสง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-photoelectric-effect')), 'choice', 'ความถี่ขีดเริ่มของโลหะคือความถี่ต่ำสุดของแสงที่ทำให้เกิดโฟโตอิเล็กตรอนได้ ที่ความถี่นี้พลังงานจลน์ของอิเล็กตรอนเป็นเท่าใด', '["ลบ","มากที่สุด","เป็นศูนย์","เท่ากับ hf"]', '2', 'ที่ความถี่ขีดเริ่ม hf₀ = φ พลังงานโฟตอนทั้งหมดใช้เอาชนะฟังก์ชันงานพอดี พลังงานจลน์สูงสุดจึงเป็นศูนย์ ความถี่ต่ำกว่านี้ไม่เกิดโฟโตอิเล็กตรอน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-photoelectric-effect')), 'number', 'โฟตอนพลังงาน 3.0 อิเล็กตรอนโวลต์ ตกกระทบโลหะฟังก์ชันงาน 2.2 อิเล็กตรอนโวลต์ พลังงานจลน์สูงสุดของโฟโตอิเล็กตรอนเป็นกี่อิเล็กตรอนโวลต์ (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":0.8,"tolerance":0.05}', 'EKmax = hf − ฟังก์ชันงาน = 3.0 − 2.2 = 0.8 อิเล็กตรอนโวลต์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-photoelectric-effect')), 'number', 'โลหะฟังก์ชันงาน 2.0 อิเล็กตรอนโวลต์ ฉายแสงพลังงานโฟตอน 2.5 อิเล็กตรอนโวลต์ พลังงานจลน์สูงสุดของอิเล็กตรอนเป็นกี่อิเล็กตรอนโวลต์ (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":0.5,"tolerance":0.05}', 'EKmax = 2.5 − 2.0 = 0.5 อิเล็กตรอนโวลต์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'quantum-atom'), 'quantum-wave-particle-duality', 'ทวิภาพของคลื่นและอนุภาค', 'แสงและสสารต่างมีทั้งสมบัติคลื่นและอนุภาค ปรากฏการณ์โฟโตอิเล็กทริกแสดงสมบัติอนุภาคของแสง ส่วนการเลี้ยวเบนและการแทรกสอดแสดงสมบัติคลื่น อนุภาคขนาดเล็กก็มีสมบัติคลื่นตามเดอบรอยล์', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'quantum-wave-particle-duality'), 'youtube', 'https://www.youtube.com/watch?v=vBjPJqRarvs', 'vBjPJqRarvs', 'ฟิสิกส์ ม.6 บทที่ 19 ฟิสิกส์อะตอม ep.14 (ความยาวคลื่นเดอบรอยล์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'quantum-wave-particle-duality'), 'แบบทดสอบ: ทวิภาพของคลื่นและอนุภาค', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-wave-particle-duality')), 'choice', 'ทวิภาพของคลื่นและอนุภาค (wave-particle duality) หมายถึงอะไร', '["แสงและสสารแสดงทั้งสมบัติคลื่นและอนุภาคขึ้นกับสถานการณ์","คลื่นและอนุภาคเป็นสิ่งเดียวกันเสมอโดยไม่ขึ้นกับสถานการณ์","แสงเป็นคลื่นเท่านั้น","สสารเป็นอนุภาคเท่านั้น"]', '0', 'ทวิภาพหมายความว่าแสงและอนุภาคขนาดเล็กแสดงทั้งสมบัติคลื่นและอนุภาค ขึ้นกับว่าทำการทดลองแบบใด เช่น การแทรกสอดแสดงสมบัติคลื่น แต่โฟโตอิเล็กทริกแสดงสมบัติอนุภาค', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-wave-particle-duality')), 'choice', 'การทดลองใดแสดงสมบัติคลื่นของอิเล็กตรอน', '["การแตกตัวของอะตอม","การเลี้ยวเบนผ่านผลึกหรือสลิต","การชนกันของลูกบอล","การโฟโตอิเล็กทริก"]', '1', 'อิเล็กตรอนที่ผ่านสลิตคู่หรือผลึกเกิดการเลี้ยวเบนและแทรกสอด ซึ่งเป็นสมบัติคลื่น สอดคล้องกับความยาวคลื่นเดอบรอยล์ λ = h/p', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-wave-particle-duality')), 'choice', 'แสงแสดงสมบัติอนุภาคชัดเจนที่สุดในปรากฏการณ์ใด', '["การเลี้ยวเบนของแสง","การสะท้อนของแสง","การแทรกสอดของแสง","ปรากฏการณ์โฟโตอิเล็กทริก"]', '3', 'ปรากฏการณ์โฟโตอิเล็กทริกที่แสงเป็นโฟตอนพลังงาน hf กระแทกอิเล็กตรอน แสดงสมบัติอนุภาคของแสงอย่างชัดเจน ต่างจากการแทรกสอดและการเลี้ยวเบนที่แสดงสมบัติคลื่น', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-wave-particle-duality')), 'number', 'โฟตอนพลังงาน 3.1 อิเล็กตรอนโวลต์ ความยาวคลื่นเป็น 400 นาโนเมตร ถ้าโฟตอนพลังงาน 1.55 อิเล็กตรอนโวลต์ ความยาวคลื่นใหม่เป็นกี่นาโนเมตร (ความยาวคลื่นแปรผกผันกับพลังงาน ตอบเป็นจำนวนเต็ม)', NULL, '{"value":800,"tolerance":0.5}', 'λ ∝ 1/E เมื่อพลังงานลดลงครึ่งหนึ่ง ความยาวคลื่นเพิ่มเป็น 2 เท่า → 400×2 = 800 นาโนเมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-wave-particle-duality')), 'number', 'โฟตอนพลังงาน 2.0 อิเล็กตรอนโวลต์ ความยาวคลื่นเป็น 620 นาโนเมตร ถ้าพลังงานเป็น 4.0 อิเล็กตรอนโวลต์ ความยาวคลื่นใหม่เป็นกี่นาโนเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":310,"tolerance":0.5}', 'λ ∝ 1/E เมื่อพลังงานเพิ่ม 2 เท่า ความยาวคลื่นลดครึ่งหนึ่ง → 620/2 = 310 นาโนเมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'reflection-refraction'), 'reflection-refraction-critical-angle', 'ดัชนีหักเหและการสะท้อนกลับหมด', 'การสะท้อนกลับหมดเกิดเมื่อแสงเดินทางจากตัวกลางหนาแน่นไปยังหนาแน่นน้อยด้วยมุมตกกระทบมากกว่ามุมวิกฤต มุมวิกฤตหาได้จาก sin θc = n2/n1 เป็นหลักการของใยแก้วนำแสง', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
