INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-special-postulates')), 'choice', 'สมมติฐานข้อแรกของสัมพัทธภาพพิเศษกล่าวว่าอย่างไร', '["เวลาเท่ากันทุกกรอบ","กฎฟิสิกส์เหมือนกันในกรอบอ้างอิงเฉื่อยทุกกรอบ","อัตราเร็วแสงต่างกันตามกรอบอ้างอิง","มวลคงที่เสมอ"]', '1', 'สมมติฐานข้อแรก (หลักการสัมพัทธภาพ) กล่าวว่ากฎของฟิสิกส์เหมือนกันในกรอบอ้างอิงเฉื่อยทุกกรอบ จึงไม่มีการทดลองใดแยกได้ว่ากรอบไหนอยู่นิ่งจริง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-special-postulates')), 'choice', 'สมมติฐานข้อที่สองของสัมพัทธภาพพิเศษกล่าวว่าอย่างไร', '["อัตราเร็วแสงขึ้นกับผู้สังเกตที่เคลื่อนที่","อัตราเร็วแสงเพิ่มตามความเร็วแหล่งกำเนิด","อัตราเร็วแสงในสุญญากาศคงที่และเท่ากันสำหรับกรอบเฉื่อยทุกกรอบ","อัตราเร็วแสงเท่ากับศูนย์ในสุญญากาศ"]', '2', 'สมมติฐานข้อที่สองกล่าวว่าอัตราเร็วแสงในสุญญากาศ c มีค่าคงที่เท่ากันสำหรับผู้สังเกตในกรอบเฉื่อยทุกกรอบ ไม่ว่าผู้สังเกตหรือแหล่งกำเนิดจะเคลื่อนที่อย่างไร', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-special-postulates')), 'choice', 'กรอบอ้างอิงเฉื่อยคือกรอบแบบใด', '["กรอบที่หมุนได้","กรอบที่ความเร็วเปลี่ยนตลอดเวลา","กรอบที่เคลื่อนที่ด้วยความเร่งคงที่","กรอบที่เคลื่อนที่ด้วยความเร็วคงที่หรือหยุดนิ่ง"]', '3', 'กรอบอ้างอิงเฉื่อยคือกรอบที่อยู่นิ่งหรือเคลื่อนที่ด้วยความเร็วคงที่ (ไม่มีความเร่ง) ในกรอบเช่นนี้กฎของนิวตันใช้ได้ และเป็นกรอบที่พิจารณาในสัมพัทธภาพพิเศษ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-special-postulates')), 'number', 'จากสมมติฐานว่าอัตราเร็วแสงคงที่ ถ้าแหล่งกำเนิดแสงอยู่นิ่งและผู้สังเกตเคลื่อนที่เข้าหาแหล่งด้วยความเร็ว 0.6c อัตราเร็วแสงที่ผู้สังเกตวัดได้เป็นกี่เท่าของ c (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":1,"tolerance":0.5}', 'ตามสมมติฐานข้อที่สอง อัตราเร็วแสงในสุญญากาศคงที่ c สำหรับทุกกรอบเฉื่อย ไม่ขึ้นกับความเร็วผู้สังเกต ผู้สังเกตจึงวัดแสงได้ c เสมอ คือ 1 เท่าของ c', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-special-postulates')), 'number', 'ตามสมมติฐานข้อที่สอง อัตราเร็วแสงในสุญญากาศคงที่เท่ากับ c สำหรับทุกกรอบอ้างอิงเฉื่อย ถ้าแสงเดินทางในสุญญากาศเป็นเวลา 4 วินาที ระยะทางที่แสงเดินทางได้คิดเป็นเท่าใดของระยะที่แสงเดินทางได้ใน 1 วินาที (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.05}', 'ระยะทางแปรผันตรงกับเวลา เมื่อเวลามากขึ้น 4 เท่า ระยะทางจึงเป็น 4 เท่า เนื่องจากอัตราเร็วคงที่', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'relativity'), 'relativity-time-dilation-length-contraction', 'การยืดของเวลาและการหดของความยาว', 'ในสัมพัทธภาพพิเศษ เวลาของผู้สังเกตที่เคลื่อนที่เร็วจะเดินช้ากว่า (การยืดของเวลา) และความยาวตามทิศการเคลื่อนที่จะหดสั้นลง (การหดของความยาว) เมื่อเทียบกับกรอบนิ่ง', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'relativity-time-dilation-length-contraction'), 'youtube', 'https://www.youtube.com/watch?v=GBqmfatFmi0', 'GBqmfatFmi0', 'ทฤษฎีสัมพัทธภาพพิเศษ ตอนที่ 1 การยืดของเวลาและการหดของความยาว', 'Physics Tips', 'https://www.youtube.com/channel/UC8ElpJwdpSGg2HaKe9blUgA', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'relativity-time-dilation-length-contraction'), 'youtube', 'https://www.youtube.com/watch?v=7i2HLKsggfM', '7i2HLKsggfM', 'ทฤษฏีสัมพัทธภาพพิเศษ PART 1 ตอน การหดของความยาวและ การยืดของเวลา', 'One To Many - A Brief Science', 'https://www.youtube.com/channel/UCJ1NapUKndO_3nYB80752nA', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'relativity-time-dilation-length-contraction'), 'แบบทดสอบ: การยืดของเวลาและการหดของความยาว', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-time-dilation-length-contraction')), 'choice', 'การยืดของเวลากล่าวว่าอย่างไร', '["เวลาของกรอบที่เคลื่อนที่เร็วเดินช้ากว่ากรอบที่หยุดนิ่ง","เวลาของกรอบที่เคลื่อนที่เร็วนาเดินเร็วขึ้น","เวลาเท่ากันทุกกรอบ","เวลาหยุดเดินเมื่อเคลื่อนที่"]', '0', 'การยืดของเวลา (time dilation) กล่าวว่าเวลาที่วัดในกรอบที่เคลื่อนที่สัมพัทธ์จะเดินช้ากว่าเวลาที่วัดในกรอบนิ่งในอัตรา t = t₀/√(1 − v²/c²)', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-time-dilation-length-contraction')), 'choice', 'การหดของความยาวเกิดขึ้นในทิศทางใด', '["ทิศตั้งฉากกับการเคลื่อนที่","ทิศขนาน (ตามแนว) กับการเคลื่อนที่","ทุกทิศทางเท่ากัน","ความยาวไม่หดเลย"]', '1', 'ความยาวหดเฉพาะทิศที่ขนานกับทิศการเคลื่อนที่ L = L₀√(1 − v²/c²) ส่วนความยาวที่ตั้งฉากกับทิศการเคลื่อนที่ไม่เปลี่ยนแปลง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-time-dilation-length-contraction')), 'choice', 'ถ้าความเร็วของวัตถุเข้าใกล้ความเร็วแสง ความยาวของวัตถุตามทิศการเคลื่อนที่เมื่อผู้สังเกตนิ่งวัดได้ จะเป็นอย่างไร', '["เป็นศูนย์เสมอ","ยาวขึ้นเรื่อยๆ","สั้นลงเรื่อยๆ","ไม่เปลี่ยนแปลง"]', '2', 'เมื่อ v เข้าใกล้ c ตัวประกอบ γ = 1/√(1 − v²/c²) มีค่ามาก ความยาวหด (L = L₀/γ) จึงสั้นลงเรื่อยๆ จนเข้าใกล้ศูนย์ตามหลักการหดของความยาว', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-time-dilation-length-contraction')), 'number', 'ยานอวกาศเคลื่อนที่ด้วยความเร็ว 0.6c ผู้โดยสารบนยานวัดเวลาบนยานได้ 4 วินาที ผู้สังเกตบนโลกคำนวณว่าช่วงเวลานี้กินเวลากี่วินาที (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":5,"tolerance":0.05}', 'γ = 1/√(1 − 0.36) = 1/√0.64 = 1/0.8 = 1.25 ดังนั้น t = γ·t₀ = 1.25 × 4 = 5 วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-time-dilation-length-contraction')), 'number', 'แท่งยาว 20 เมตร ตามผู้สังเกตที่อยู่นิ่งกับแท่ง ยานอวกาศเคลื่อนที่ผ่านด้วยความเร็ว 0.6c ตามแนวแกนของแท่ง ความยาวของแท่งที่ผู้สังเกตบนยานวัดได้เท่ากับกี่เมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":16,"tolerance":0.5}', 'γ = 1/√(1 − 0.36) = 1.25 ดังนั้น L = L₀/γ = 20/1.25 = 16 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'oscillation-gravity'), 'simple-harmonic-motion', 'การเคลื่อนที่แบบฮาร์มอนิกอย่างง่าย', 'การเคลื่อนที่แบบฮาร์มอนิกอย่างง่ายเกิดจากแรงฟื้นกลับแปรผันตรงกับการกระจัดและมีทิศตรงข้าม คาบไม่ขึ้นกับแอมพลิจูด', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
