INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-beats')), 'choice', 'บีตเกิดจากปรากฏการณ์ใด', '["คลื่นเสียงสองความถี่เท่ากันพอดีซ้อนทับกัน","คลื่นเสียงสองความถี่ที่ใกล้เคียงกันซ้อนทับกัน","เสียงที่มีความดังมากเกินไป","เสียงสะท้อนจากผนัง"]', '1', 'บีตเกิดเมื่อคลื่นเสียงสองความถี่ใกล้เคียงกันซ้อนทับกัน ทำให้แอมพลิจูดลัพธ์แกว่งเป็นจังหวะดัง-เบา', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-beats')), 'choice', 'ความถี่บีต fb หาได้จากความสัมพันธ์ใด เมื่อ f1 และ f2 เป็นความถี่ของเสียงทั้งสอง', '["fb = f1 + f2","fb = f1 × f2","fb = |f1 − f2|","fb = (f1 + f2)/2"]', '2', 'ความถี่บีตเท่ากับผลต่างของความถี่ทั้งสอง fb = |f1 − f2|', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-beats')), 'choice', 'จำนวนครั้งที่เสียงดังและเบาสลับกันต่อวินาทีเท่ากับปริมาณใด', '["ความถี่บีต","ความถี่ของเสียงที่สูงกว่า","ค่าเฉลี่ยของความถี่ทั้งสอง","แอมพลิจูดของคลื่นลัพธ์"]', '0', 'จำนวนจังหวะที่ได้ยินเสียงดัง-เบาต่อวินาทีเท่ากับความถี่บีต fb = |f1 − f2|', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-beats')), 'number', 'แหล่งกำเนิดเสียงสองแหล่งมีความถี่ 256 เฮิรตซ์ และ 260 เฮิรตซ์ ความถี่บีตเท่ากับกี่เฮิรตซ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 'fb = |260 − 256| = 4 เฮิรตซ์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-beats')), 'number', 'ได้ยินเสียงดัง-เบาสลับกัน 6 ครั้งต่อวินาที โดยแหล่งหนึ่งมีความถี่ 440 เฮิรตซ์ แหล่งที่สองมีความถี่สูงกว่าเล็กน้อย ความถี่ของแหล่งที่สองเท่ากับกี่เฮิรตซ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":446,"tolerance":0.5}', 'fb = |f2 − 440| = 6 และ f2 สูงกว่า จึงได้ f2 = 440 + 6 = 446 เฮิรตซ์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'sound'), 'sound-doppler', 'ปรากฏการณ์ดอปเพลอร์', 'ปรากฏการณ์ดอปเพลอร์คือการที่ความถี่เสียงที่ผู้ฟังได้ยินเปลี่ยนไปเมื่อแหล่งกำเนิดหรือผู้ฟังเคลื่อนที่สัมพัทธ์กัน ถ้าเข้าหากันความถี่สูงขึ้น ถ้าห่างกันความถี่ต่ำลง', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-doppler'), 'youtube', 'https://www.youtube.com/watch?v=gf1EjigLlVs', 'gf1EjigLlVs', 'ฟิสิกส์ ม.5 บทที่ 12 เสียง ep.8 (ปรากฎการณ์ดอปเพลอร์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-doppler'), 'youtube', 'https://www.youtube.com/watch?v=VDW1oV_2lo0', 'VDW1oV_2lo0', 'ฟิสิกส์ ม.5 บทที่ 12 เสียง ep.9 (คลื่นกระแทก, sonic boom)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-doppler'), 'แบบทดสอบ: ปรากฏการณ์ดอปเพลอร์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-doppler')), 'choice', 'เมื่อรถพยาบาลที่มีเสียงไซเรนความถี่คงที่เคลื่อนที่เข้าหาผู้ฟังที่ยืนนิ่ง ความถี่ที่ผู้ฟังได้ยินเป็นอย่างไร', '["ต่ำกว่าความถี่จริง","เท่ากับความถี่จริง","สูงกว่าความถี่จริง","เป็นศูนย์"]', '2', 'เมื่อแหล่งกำเนิดเคลื่อนที่เข้าหาผู้ฟัง ความยาวคลื่นถูกบีบสั้นลง ความถี่ที่ได้ยินจึงสูงกว่าความถี่จริง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-doppler')), 'choice', 'เมื่อแหล่งกำเนิดเสียงเคลื่อนที่ออกห่างจากผู้ฟังที่ยืนนิ่ง ความถี่ที่ผู้ฟังได้ยินเป็นอย่างไร', '["สูงกว่าความถี่จริง","ต่ำกว่าความถี่จริง","เท่ากับความถี่จริง","ไม่เปลี่ยนแปลง"]', '1', 'เมื่อแหล่งกำเนิดเคลื่อนที่ออกห่าง ความยาวคลื่นถูกยืดยาวขึ้น ความถี่ที่ได้ยินจึงต่ำกว่าความถี่จริง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-doppler')), 'choice', 'ในสูตรดอปเพลอร์ f'' = f·v/(v − vs) สำหรับแหล่งกำเนิดเคลื่อนที่เข้าหาผู้ฟังนิ่ง ตัวแปร v หมายถึงปริมาณใด', '["อัตราเร็วของแหล่งกำเนิด","อัตราเร็วของผู้ฟัง","อัตราเร็วของเสียงในตัวกลาง","ความถี่จริงของแหล่งกำเนิด"]', '0', 'ในสูตร v คืออัตราเร็วเสียงในตัวกลาง ส่วน vs คืออัตราเร็วของแหล่งกำเนิดเสียง', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-doppler')), 'number', 'แหล่งกำเนิดเสียงความถี่ 600 เฮิรตซ์ เคลื่อนที่เข้าหาผู้ฟังนิ่งด้วยอัตราเร็ว 170 เมตรต่อวินาที อัตราเร็วเสียง 340 เมตรต่อวินาที ความถี่ที่ผู้ฟังได้ยินเท่ากับกี่เฮิรตซ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":1200,"tolerance":0.5}', 'f'' = f·v/(v − vs) = 600 × 340/(340 − 170) = 600 × 340/170 = 1200 เฮิรตซ์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-doppler')), 'number', 'แหล่งกำเนิดเสียงความถี่ 300 เฮิรตซ์ เคลื่อนที่ออกห่างจากผู้ฟังนิ่งด้วยอัตราเร็ว 170 เมตรต่อวินาที อัตราเร็วเสียง 340 เมตรต่อวินาที ความถี่ที่ผู้ฟังได้ยินเท่ากับกี่เฮิรตซ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":200,"tolerance":0.5}', 'f'' = f·v/(v + vs) = 300 × 340/(340 + 170) = 300 × 340/510 = 200 เฮิรตซ์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'sound'), 'sound-intensity-decibel', 'ความเข้มเสียงและระดับความเข้มเสียง', 'ความเข้มเสียงคือกำลังเสียงต่อหน่วยพื้นที่ หน่วย วัตต์ต่อตารางเมตร ระดับความเข้มเสียงวัดเป็นเดซิเบล โดย β = 10 log(I/I0) ทุกครั้งที่ความเข้มเพิ่มขึ้น 10 เท่า ระดับเสียงเพิ่ม 10 เดซิเบล', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-intensity-decibel'), 'youtube', 'https://www.youtube.com/watch?v=p7DRAxZGObA', 'p7DRAxZGObA', 'ฟิสิกส์ ม.5 บทที่ 12 เสียง ep.4 (ความเข้มเสียง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-intensity-decibel'), 'youtube', 'https://www.youtube.com/watch?v=GmzaQqIjBqM', 'GmzaQqIjBqM', 'ฟิสิกส์ ม.5 บทที่ 12 เสียง ep.5 (ระดับเสียง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-intensity-decibel'), 'แบบทดสอบ: ความเข้มเสียงและระดับความเข้มเสียง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-intensity-decibel')), 'choice', 'เมื่อระดับความเข้มเสียงเพิ่มขึ้น 10 เดซิเบล ความเข้มเสียงจะเปลี่ยนเป็นกี่เท่าของเดิม', '["2 เท่า","10 เท่า","100 เท่า","เท่าเดิม"]', '1', 'β = 10 log(I/I0) เมื่อ β เพิ่ม 10 เดซิเบล แสดงว่า I เพิ่มขึ้น 10 เท่า', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-intensity-decibel')), 'choice', 'ความเข้มเสียง I แปรผกผันกับกำลังสองของระยะห่างจากแหล่งกำเนิดจุด ถ้าระยะห่างเพิ่มขึ้นเป็น 2 เท่า ความเข้มเสียงเป็นกี่เท่าของเดิม', '["1/4 เท่า","2 เท่า","4 เท่า","1/2 เท่า"]', '0', 'I ∝ 1/r² เมื่อ r เพิ่มเป็น 2 เท่า I จะเป็น 1/2² = 1/4 เท่า', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-intensity-decibel')), 'choice', 'ข้อใดกล่าวถึงความเข้มเสียงได้ถูกต้อง', '["ความเข้มเสียงคือจำนวนรอบต่อวินาที","ความเข้มเสียงคือพลังงานเสียงทั้งหมดของแหล่งกำเนิด","ความเข้มเสียงคือกำลังเสียงที่ตกตั้งฉากต่อหนึ่งหน่วยพื้นที่","ความเข้มเสียงคือระดับเสียงในหน่วยเดซิเบล"]', '2', 'ความเข้มเสียงคืออัตราการไหลของพลังงานเสียงต่อหนึ่งหน่วยพื้นที่ที่ตั้งฉากกับทิศการแพร่ มีหน่วย วัตต์ต่อตารางเมตร', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-intensity-decibel')), 'number', 'ถ้าความเข้มเสียงเพิ่มขึ้นเป็น 100 เท่าของเดิม ระดับความเข้มเสียงจะเพิ่มขึ้นกี่เดซิเบล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', 'Δβ = 10 log(100) = 10 × 2 = 20 เดซิเบล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-intensity-decibel')), 'number', 'ถ้าความเข้มเสียงเพิ่มขึ้นเป็น 1000 เท่าของเดิม ระดับความเข้มเสียงจะเพิ่มขึ้นกี่เดซิเบล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":30,"tolerance":0.5}', 'Δβ = 10 log(1000) = 10 × 3 = 30 เดซิเบล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'sound'), 'sound-nature-speed', 'ธรรมชาติของเสียงและอัตราเร็วเสียง', 'เสียงเป็นคลื่นตามยาวที่ต้องอาศัยตัวกลาง อัตราเร็วเสียงแปรตามสมบัติของตัวกลางและอุณหภูมิ โดยทั่วไปเสียงเดินทางในของแข็งเร็วที่สุด รองลงมาคือของเหลวและแก๊ส', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
