INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-distance-displacement')), 'choice', 'รถวิ่งไปทางทิศตะวันออก 30 กิโลเมตร แล้วย้อนกลับทางทิศตะวันตก 30 กิโลเมตร การกระจัดมีขนาดเท่าใด', '["0 กิโลเมตร","30 กิโลเมตร","60 กิโลเมตร","90 กิโลเมตร"]', '0', 'กลับมาที่จุดเริ่มต้นพอดี การกระจัดจึงเป็น 0 กิโลเมตร เพราะวัดจากจุดเริ่มต้นถึงจุดสุดท้าย', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-distance-displacement')), 'choice', 'จากข้อก่อน ระยะทางรวมที่รถวิ่งได้เป็นเท่าใด', '["0 กิโลเมตร","60 กิโลเมตร","30 กิโลเมตร","90 กิโลเมตร"]', '1', 'ระยะทางคือความยาวเส้นทางที่วิ่งจริงรวมกัน = 30 + 30 = 60 กิโลเมตร', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-distance-displacement')), 'choice', 'อัตราเร็วเฉลี่ยคำนวณได้จากสูตรใด', '["การกระจัดหารด้วยเวลา","แรงหารด้วยมวล","ระยะทางรวมหารด้วยช่วงเวลาทั้งหมด","ความเร่งคูณด้วยเวลา"]', '2', 'อัตราเร็วเฉลี่ย = ระยะทางรวม / เวลาทั้งหมด ส่วนการกระจัด/เวลา คือความเร็วเฉลี่ย', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-distance-displacement')), 'number', 'คนวิ่งได้การกระจัด 50 เมตรในเวลา 20 วินาที ความเร็วเฉลี่ยเป็นเท่าใด (ตอบเป็นเมตร/วินาที ทศนิยม 1 ตำแหน่ง)', NULL, '{"value":2.5,"tolerance":0.05}', 'ความเร็วเฉลี่ย = การกระจัด / เวลา = 50 / 20 = 2.5 เมตร/วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-distance-displacement')), 'number', 'รถวิ่งได้ระยะทางรวม 300 เมตรในเวลา 60 วินาที อัตราเร็วเฉลี่ยเป็นเท่าใด (ตอบเป็นเมตร/วินาที จำนวนเต็ม)', NULL, '{"value":5,"tolerance":0.5}', 'อัตราเร็วเฉลี่ย = 300 / 60 = 5 เมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'straight-line-motion'), 'straight-line-motion-free-fall', 'การตกอย่างอิสระและการเคลื่อนที่แนวดิ่ง', 'การตกอย่างอิสระเป็นการเคลื่อนที่ด้วยความเร่งคงตัว g ประมาณ 9.8 เมตร/วินาที² วัตถุทุกก้อนตกพร้อมกันถ้าไม่คิดแรงต้านอากาศ', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
