INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-free-fall'), 'youtube', 'https://www.youtube.com/watch?v=8NFA1OoGVwo', '8NFA1OoGVwo', 'ฟิสิกส์ ม.4 บทที่ 2 การเคลื่อนที่แนวตรง ep.5(สมการการเคลื่อนที่ด้วยความเร่งคงตัว,การตกอย่างอิสระ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-free-fall'), 'แบบทดสอบ: การตกอย่างอิสระและการเคลื่อนที่แนวดิ่ง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-free-fall')), 'choice', 'วัตถุตกอย่างอิสระโดยไม่คิดแรงต้านอากาศ มีความเร่งเท่าใด', '["0","แปรตามมวลของวัตถุ","9.8 เมตร/วินาที² ลงพื้น","9.8 เมตร/วินาที² ขึ้นฟ้า"]', '2', 'การตกอย่างอิสระมีความเร่งเท่ากับ g ประมาณ 9.8 เมตร/วินาที² ในทิศลง และไม่ขึ้นกับมวล', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-free-fall')), 'choice', 'โยนวัตถุขึ้นในแนวดิ่ง ที่จุดสูงสุดความเร็วของวัตถุเป็นเท่าใด', '["เท่ากับ g","มากที่สุด","เท่ากับความเร็วต้น","ศูนย์"]', '3', 'ที่จุดสูงสุดวัตถุชะงักชั่วครู่ก่อนเปลี่ยนทิศ ความเร็วจึงเป็นศูนย์ แต่ความเร่งยังเท่ากับ g ในทิศลง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-free-fall')), 'choice', 'ปล่อยวัตถุมวล 1 กิโลกรัมกับ 2 กิโลกรัมจากความสูงเดียวกันพร้อมกันโดยไม่คิดแรงต้านอากาศ ข้อใดถูกต้อง', '["ตกถึงพื้นพร้อมกัน","ก้อน 2 กิโลกรัมถึงพื้นก่อน","ก้อน 1 กิโลกรัมถึงพื้นก่อน","ไม่สามารถเปรียบเทียบได้"]', '0', 'การตกอย่างอิสระไม่ขึ้นกับมวล วัตถุทั้งสองจึงมีความเร่งเท่ากันและตกถึงพื้นพร้อมกัน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-free-fall')), 'number', 'ปล่อยวัตถุจากหยุดนิ่งให้ตกนาน 3 วินาที ความเร็วปลายเป็นเท่าใด (ใช้ g = 10 เมตร/วินาที² ตอบเป็นเมตร/วินาที จำนวนเต็ม)', NULL, '{"value":30,"tolerance":0.5}', 'v = gt = 10 x 3 = 30 เมตร/วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-free-fall')), 'number', 'ปล่อยวัตถุจากหยุดนิ่งให้ตกลงมานาน 2 วินาที ได้ระยะทางเท่าใด (s = ½gt² ใช้ g = 10 เมตร/วินาที² ตอบเป็นเมตร จำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', 's = ½ x 10 x 2² = ½ x 10 x 4 = 20 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'straight-line-motion'), 'straight-line-motion-graphs-ticker', 'กราฟการเคลื่อนที่และเครื่องเคาะสัญญาณเวลา', 'ความชันของกราฟตำแหน่ง-เวลาคือความเร็ว เครื่องเคาะสัญญาณเวลาบันทึกตำแหน่งตามช่วงเวลาที่เท่ากัน ใช้ศึกษาการเคลื่อนที่', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
