INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-graphs-ticker')), 'choice', 'ความชันของกราฟตำแหน่ง-เวลามีความหมายเท่ากับปริมาณใด', '["ความเร่ง","ระยะทางทั้งหมด","เวลาที่ใช้","ความเร็ว"]', '3', 'ความชันของกราฟตำแหน่ง-เวลา คือ การกระจัด/เวลา ซึ่งเท่ากับความเร็ว', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-graphs-ticker')), 'choice', 'กราฟตำแหน่ง-เวลาเป็นเส้นตรงลาดขึ้นคงที่ หมายความว่าวัตถุกำลังทำอะไร', '["เคลื่อนที่ด้วยความเร็วคงที่","หยุดนิ่ง","มีความเร่งที่ไม่เป็นศูนย์","เคลื่อนที่กลับทิศ"]', '0', 'เส้นตรงมีความชันคงที่ จึงมีความเร็วคงที่ ไม่มีความเร่ง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-graphs-ticker')), 'choice', 'จากกราฟตำแหน่ง-เวลา ถ้าเส้นเป็นแนวนอน (ตำแหน่งไม่เปลี่ยนตามเวลา) วัตถุกำลังทำอะไร', '["เคลื่อนที่เร็วขึ้น","หยุดนิ่ง","เคลื่อนที่ช้าลง","เคลื่อนที่ด้วยความเร็วคงที่"]', '1', 'ตำแหน่งไม่เปลี่ยนตามเวลาหมายความว่าวัตถุหยุดนิ่ง ความเร็วเป็นศูนย์', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-graphs-ticker')), 'number', 'เครื่องเคาะสัญญาณเวลาเคาะ 50 ครั้งต่อวินาที ระหว่างจุดสองจุดที่ถัดกันใช้เวลาเท่าใด (ตอบเป็นวินาที ทศนิยม 2 ตำแหน่ง)', NULL, '{"value":0.02,"tolerance":0.005}', '1/50 = 0.02 วินาทีต่อช่วงจุด', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-graphs-ticker')), 'number', 'เครื่องเคาะสัญญาณเวลาเคาะ 50 ครั้งต่อวินาที มีทั้งหมด 10 ช่วงจุด ใช้เวลานานเท่าใด (ตอบเป็นวินาที ทศนิยม 2 ตำแหน่ง)', NULL, '{"value":0.2,"tolerance":0.005}', '10 ช่วงจุด x (1/50) = 10 x 0.02 = 0.2 วินาที', 5);
