INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-equilibrium'), 'แบบทดสอบ: สมดุลความร้อน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-equilibrium')), 'choice', 'วางแก้วน้ำร้อนกับแก้วน้ำเย็นให้สัมผัสกัน ความร้อนจะไหลอย่างไร', '["จากน้ำร้อนไปยังน้ำเย็น","จากน้ำเย็นไปยังน้ำร้อน","ไม่มีการไหลของความร้อน","ไหลทั้งสองทางพร้อมกันเท่ากัน"]', '0', 'ความร้อนไหลจากวัตถุที่มีอุณหภูมิสูงไปยังวัตถุที่มีอุณหภูมิต่ำกว่าเสมอ จนเข้าสู่สมดุลความร้อน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-equilibrium')), 'choice', 'สมดุลความร้อนเกิดขึ้นเมื่อใด', '["เมื่อความร้อนหมดไป","เมื่อมวลทั้งสองเท่ากัน","เมื่ออุณหภูมิของวัตถุทั้งสองเท่ากัน","เมื่อวัตถุทั้งสองเป็นสารชนิดเดียวกัน"]', '2', 'สมดุลความร้อนคือสภาวะที่อุณหภูมิของระบบเท่ากันหมด ไม่มีการไหลของความร้อนสุทธิระหว่างส่วนต่างๆ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-equilibrium')), 'choice', 'ในระบบที่ไม่มีสูญเสียความร้อนออกนอก เมื่อวัตถุร้อนคายความร้อนเข้าสู่สมดุล ความร้อนที่คายควรเป็นเท่าใดเทียบกับความร้อนที่เย็นรับ', '["ร้อนคายมากกว่าเสมอ","เท่ากัน","เย็นรับมากกว่าเสมอ","ครึ่งหนึ่งของที่รับ"]', '1', 'ถ้าไม่สูญเสียความร้อนออกนอกระบบ ความร้อนที่คายจากวัตถุร้อนต้องเท่ากับความร้อนที่วัตถุเย็นรับ โดยกฎการอนุรักษ์พลังงาน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-equilibrium')), 'number', 'น้ำร้อนมวล 1 กิโลกรัม อุณหภูมิ 80 องศาเซลเซียส ผสมกับน้ำเย็นมวล 1 กิโลกรัม อุณหภูมิ 20 องศาเซลเซียส ถ้าไม่สูญเสียความร้อน อุณหภูมิสมดุลเป็นกี่องศาเซลเซียส (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":50,"tolerance":0.5}', 'มวลเท่ากันและสารชนิดเดียวกัน อุณหภูมิสมดุลเป็นค่าเฉลี่ย = (80 + 20)/2 = 50 องศาเซลเซียส', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-equilibrium')), 'number', 'โลหะร้อนมวล 0.2 กิโลกรัม อุณหภูมิ 100 องศาเซลเซียส ความร้อนจำเพาะ 800 จูล/กิโลกรัม·องศาเซลเซียส จุ่มในน้ำเย็นแล้วอุณหภูมิลดลง 50 องศาเซลเซียส โลหะคายความร้อนกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":8000,"tolerance":0.5}', 'Q = mcΔT = 0.2 × 800 × 50 = 8000 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'temperature-heat'), 'temperature-heat-thermal-expansion', 'การขยายตัวทางความร้อน', 'เมื่ออุณหภูมิสูงขึ้น สารส่วนใหญ่ขยายตัว ยาวขึ้น พื้นที่มากขึ้น ปริมาตรเพิ่ม การขยายตัวเชิงเส้นใช้สูตร ΔL = αL₀ΔT และขึ้นกับชนิดของสาร', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-expansion'), 'youtube', 'https://www.youtube.com/watch?v=yXUgSGC7MAg', 'yXUgSGC7MAg', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.1(ความร้อน อุณหภูมิ ความจุความร้อนจำเพาะ ความร้อนแฝงจำเพาะ )', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-expansion'), 'youtube', 'https://www.youtube.com/watch?v=6WBq9Pk5478', '6WBq9Pk5478', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.2 (พลังงานความร้อนที่ทำให้สารเปลี่ยนแปลงอุณหภูมิและสถานะ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-expansion'), 'แบบทดสอบ: การขยายตัวทางความร้อน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-expansion')), 'choice', 'เมื่อให้ความร้อนแก่แท่งโลหะ ความยาวของแท่งโดยทั่วไปเป็นอย่างไร', '["สั้นลง","ยาวขึ้น","เท่าเดิม","ยาวขึ้นก่อนแล้วสั้นลง"]', '1', 'สารส่วนใหญ่เมื่ออุณหภูมิสูงขึ้น อนุภาคสั่นแรงขึ้นทำให้ระยะระหว่างอนุภาคเพิ่ม วัตถุจึงขยายยาวขึ้น', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-expansion')), 'choice', 'การขยายตัวเชิงเส้นของแท่งโลหะแปรผันตรงกับปริมาณใด เมื่อค่าสัมประสิทธิ์การขยายตัวคงที่', '["ผลต่างอุณหภูมิและความยาวเดิม","มวลของแท่งโลหะ","ความหนาแน่นของแท่งโลหะ","ความจุความร้อนของแท่ง"]', '0', 'ΔL = αL0ΔT การขยายตัวแปรผันตรงกับความยาวเดิม L0 และผลต่างอุณหภูมิ ΔT', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-expansion')), 'choice', 'รางรถไฟมีช่องว่างระหว่างรางแต่ละท่อนไว้เพื่อวัตถุประสงค์ใด', '["ลดเสียงของรถไฟ","ระบายน้ำฝน","เผื่อการขยายตัวทางความร้อนของราง","เพิ่มแรงเสียดทานของล้อ"]', '2', 'ช่องว่างนี้เผื่อให้รางขยายตัวเมื่อแดดร้อนจัด ไม่เช่นนั้นรางจะโก่งงอหรือบิดเบี้ยวได้', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-expansion')), 'number', 'แท่งเหล็กยาว 2 เมตร มีค่าสัมประสิทธิ์การขยายตัวเชิงเส้น 0.000012 ต่อองศาเซลเซียส เมื่ออุณหภูมิเพิ่มขึ้น 50 องศาเซลเซียส แท่งยาวเพิ่มขึ้นกี่มิลลิเมตร (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":1.2,"tolerance":0.05}', 'ΔL = αL0ΔT = 0.000012 × 2 × 50 = 0.0012 เมตร = 1.2 มิลลิเมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-expansion')), 'number', 'แท่งทองแดงยาว 1 เมตร อุณหภูมิเพิ่มขึ้น 100 องศาเซลเซียส ถ้าค่าสัมประสิทธิ์การขยายตัวเชิงเส้นเป็น 0.000017 ต่อองศาเซลเซียส แท่งยาวเพิ่มขึ้นกี่มิลลิเมตร (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":1.7,"tolerance":0.05}', 'ΔL = 0.000017 × 1 × 100 = 0.0017 เมตร = 1.7 มิลลิเมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'temperature-heat'), 'temperature-heat-thermometer', 'อุณหภูมิและมาตรวัด', 'อุณหภูมิคือค่าที่บอกระดับความร้อนของวัตถุ วัดด้วยเทอร์โมมิเตอร์ซึ่งอาศัยสมบัติการขยายตัวของสาร เช่น ปรอทหรือแอลกอฮอล์ และมีสเกลเซลเซียส ฟาเรนไฮต์ เคลวิน', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'temperature-heat-thermometer'), 'youtube', 'https://www.youtube.com/watch?v=yXUgSGC7MAg', 'yXUgSGC7MAg', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.1(ความร้อน อุณหภูมิ ความจุความร้อนจำเพาะ ความร้อนแฝงจำเพาะ )', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
