INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-thermometer')), 'choice', 'อุณหภูมิเป็นปริมาณที่บอกอะไรของวัตถุ', '["ปริมาณความร้อนทั้งหมดในวัตถุ","มวลของวัตถุ","ระดับความร้อนของวัตถุ","ความหนาแน่นของวัตถุ"]', '2', 'อุณหภูมิเป็นตัวชี้ระดับความร้อนของวัตถุ ไม่ใช่ปริมาณความร้อนรวม เพราะวัตถุใหญ่กับเล็กอาจมีอุณหภูมิเท่ากันแต่ความร้อนรวมต่างกัน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-thermometer')), 'choice', 'เทอร์โมมิเตอร์ชนิดลำตัววัดอุณหภูมิโดยอาศัยสมบัติใดของของเหลวในหลอด', '["การนำไฟฟ้า","การขยายตัวเมื่อร้อน","การระเหยเมื่อเย็น","การหดตัวเป็นของแข็ง"]', '1', 'ของเหลวเช่นปรอทขยายตัวเมื่อร้อนและหดตัวเมื่อเย็น ระดับในหลอดจึงขึ้นลงตามอุณหภูมิ ใช้สเกลบอกค่าได้', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-thermometer')), 'choice', 'หน่วยอุณหภูมิในระบบเอสไอ (SI) คือหน่วยใด', '["เคลวิน","เซลเซียส","ฟาเรนไฮต์","เรอเมอร์"]', '0', 'หน่วยอุณหภูมิมาตรฐานเอสไอคือเคลวิน ส่วนเซลเซียสและฟาเรนไฮต์เป็นสเกลที่ใช้ในชีวิตประจำวัน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-thermometer')), 'number', 'อุณหภูมิ 300 เคลวินเท่ากับกี่องศาเซลเซียส (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":27,"tolerance":0.5}', 'เปลี่ยนจากเคลวินเป็นเซลเซียสโดยลบ 273 C = 300 − 273 = 27 องศาเซลเซียส', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-thermometer')), 'number', 'จุดเดือดของน้ำที่ความดันบรรยากาศปกติมีค่า 100 องศาเซลเซียส เท่ากับกี่เคลวิน (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":373,"tolerance":0.5}', 'เปลี่ยนจากเซลเซียสเป็นเคลวินโดยบวก 273 K = 100 + 273 = 373 เคลวิน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'thermodynamics'), 'thermodynamics-application', 'การประยุกต์กฎเทอร์โมไดนามิกส์และเครื่องจักรความร้อน', 'การนำกฎข้อที่ 1 ของเทอร์โมไดนามิกส์ไปประยุกต์วิเคราะห์วัฏจักรของแก๊สและหลักการพื้นฐานของเครื่องจักรความร้อนที่เปลี่ยนพลังงานความร้อนเป็นงานกล', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-application'), 'youtube', 'https://www.youtube.com/watch?v=sfPgwsAIDnw', 'sfPgwsAIDnw', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.10 (กฎข้อที่ 1 ทางเทอร์โมไดนามิกส์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-application'), 'youtube', 'https://www.youtube.com/watch?v=MixKfNgltBw', 'MixKfNgltBw', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.9(พลังงานภายใน,งานเนื่องจากากรเปลี่ยนแปลงปริมาตรแก๊ส)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-application'), 'แบบทดสอบ: การประยุกต์กฎเทอร์โมไดนามิกส์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-application')), 'choice', 'เมื่อแก๊สในกระบอกสูบทำงานครบหนึ่งวัฏจักร (Cyclic process) แล้วกลับสู่สภาวะเริ่มต้น ข้อใดถูกต้องเกี่ยวกับพลังงานภายในรวม (ΔU) ของแก๊ส', '["มีค่าเป็นบวกเสมอเพราะแก๊สได้รับความร้อน","มีค่าเป็นศูนย์เนื่องจากอุณหภูมิสุดท้ายเท่ากับอุณหภูมิเริ่มต้น","มีค่าเท่ากับงานทั้งหมดที่แก๊สกระทำ","มีค่าเป็นลบเพราะแก๊สสูญเสียพลังงานในการทำงาน"]', '1', 'เนื่องจากพลังงานภายใน (U) เป็นฟังก์ชันสภาวะ (state function) ที่ขึ้นกับอุณหภูมิ เมื่อทำงานครบวัฏจักรกลับสู่สภาวะเดิม อุณหภูมิย่อมเท่าเดิม ทำให้การเปลี่ยนแปลงพลังงานภายในรวม ΔU = 0 ดังนั้นงานสุทธิ W จึงเท่ากับความร้อนสุทธิ Q', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-application')), 'choice', 'ข้อความใดกล่าวถึงข้อจำกัดตามกฎข้อที่สองของเทอร์โมไดนามิกส์เกี่ยวกับเครื่องจักรความร้อนได้ถูกต้อง', '["เครื่องจักรความร้อนสามารถเปลี่ยนความร้อนทั้งหมดที่ได้รับให้เป็นงานกลได้ 100% หากไม่มีแรงเสียดทาน","เครื่องจักรความร้อนจำเป็นต้องปล่อยความร้อนบางส่วนทิ้งสู่แหล่งกักเก็บความร้อนอุณหภูมิต่ำเสมอ จึงไม่มีประสิทธิภาพ 100%","งานที่ได้จากเครื่องจักรความร้อนมีค่ามากกว่าความร้อนที่รับเข้ามาเสมอ","ความร้อนสามารถถ่ายโอนจากวัตถุอุณหภูมิต่ำไปยังวัตถุอุณหภูมิสูงได้เองโดยไม่ต้องทำงานภายนอก"]', '1', 'ตามกฎข้อที่สองของเทอร์โมไดนามิกส์ (ข้อความของเคลวิน-พลังค์) เครื่องจักรความร้อนที่ทำงานเป็นวัฏจักรไม่สามารถเปลี่ยนความร้อนที่ดูดเข้ามาทั้งหมดให้เป็นงานกลได้โดยสมบูรณ์ จะต้องคายความร้อนบางส่วนสู่แหล่งอุณหภูมิต่ำเสมอ ประสิทธิภาพจึงไม่มีทางถึง 100%', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-application')), 'choice', 'ในกราฟความดัน-ปริมาตร (P-V diagram) ของวัฏจักรการทำงาน หากทิศทางของกระบวนการวนตามเข็มนาฬิกา (clockwise) ข้อใดกล่าวถูกต้อง', '["งานสุทธิที่แก๊สกระทำมีค่าเป็นบวก (เครื่องจักรความร้อนทำงานออกสู่ภายนอก)","งานสุทธิที่แก๊สกระทำมีค่าเป็นลบ (เป็นการทำงานของเครื่องทำความเย็น)","ความร้อนสุทธิที่เข้าสู่ระบบมีค่าเป็นศูนย์","พื้นที่ที่ล้อมรอบในกราฟ P-V แทนพลังงานภายในรวมของแก๊ส"]', '0', 'ในกราฟ P-V วัฏจักรที่วนตามเข็มนาฬิกา งานในช่วงขยายตัว (P สูง) จะมากกว่างานในช่วงบีบอัด (P ต่ำ) ทำให้งานสุทธิเป็นบวก (W > 0) ซึ่งแสดงถึงการทำงานของเครื่องจักรความร้อน และพื้นที่ปิดภายในลูปคือค่างานสุทธิ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-application')), 'number', 'เครื่องจักรความร้อนเครื่องหนึ่ง ดูดกลืนความร้อนจากแหล่งความร้อนสูง 2,000 จูล และปล่อยความร้อนทิ้งสู่แหล่งความเย็น 1,400 จูล ในแต่ละรอบ งานกลที่เครื่องจักรนี้ผลิตได้ต่อรอบมีค่ากี่จูล', NULL, '{"value":600,"tolerance":1}', 'จากหลักการอนุรักษ์พลังงานของเครื่องจักรความร้อน งานที่ได้ W = Q_H - Q_C = 2,000 - 1,400 = 600 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-application')), 'number', 'จากเครื่องจักรความร้อนในข้อก่อนหน้า (รับความร้อน 2,000 จูล และผลิตงานกลได้ 600 จูล) ประสิทธิภาพเชิงความร้อนของเครื่องจักรนี้คิดเป็นร้อยละเท่าใด (ตอบเป็นตัวเลขเปอร์เซ็นต์)', NULL, '{"value":30,"tolerance":0.5}', 'ประสิทธิภาพเชิงความร้อน e = (W / Q_H) × 100% = (600 / 2,000) × 100% = 30%', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'thermodynamics'), 'thermodynamics-first-law', 'กฎข้อที่ 1 ของเทอร์โมไดนามิกส์', 'กฎข้อที่ 1 คือหลักการอนุรักษ์พลังงานของระบบแก๊ส ความร้อนที่ให้ระบบเท่ากับพลังงานภายในที่เปลี่ยนบวกงานที่ระบบกระทำ สูตร Q = ΔU + W', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-first-law'), 'youtube', 'https://www.youtube.com/watch?v=sfPgwsAIDnw', 'sfPgwsAIDnw', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.10 (กฎข้อที่ 1 ทางเทอร์โมไดนามิกส์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-first-law'), 'youtube', 'https://www.youtube.com/watch?v=MixKfNgltBw', 'MixKfNgltBw', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.9(พลังงานภายใน,งานเนื่องจากากรเปลี่ยนแปลงปริมาตรแก๊ส)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-first-law'), 'แบบทดสอบ: กฎข้อที่ 1 ของเทอร์โมไดนามิกส์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-first-law')), 'choice', 'กฎข้อที่ 1 ของเทอร์โมไดนามิกส์คือหลักการใด', '["การอนุรักษ์พลังงานของระบบ","เอนโทรปีต้องเพิ่มเสมอ","ความร้อนไหลจากเย็นไปร้อนเองได้","พลังงานสร้างได้และทำลายได้"]', '0', 'กฎข้อที่ 1 กล่าวว่า Q = ΔU + W เป็นการอนุรักษ์พลังงาน ความร้อนที่ให้ระบบเปลี่ยนเป็นพลังงานภายในและงาน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-first-law')), 'choice', 'ในสมการ Q = ΔU + W สำหรับแก๊สในกระบอกสูบ ตัว W คืออะไร', '["งานจากภายนอกกระทำต่อแก๊ส","งานที่แก๊สกระทำต่อภายนอก","กำลังของแก๊ส","น้ำหนักของแก๊ส"]', '1', 'W ในสมการนี้เป็นงานที่ระบบ(แก๊ส)กระทำต่อสิ่งแวดล้อม เช่น ผลักฝาสูบออก ซึ่งเป็นผลของปริมาตรเปลี่ยน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-first-law')), 'choice', 'กระบวนการที่ Q = 0 เรียกว่ากระบวนการใด', '["อุณหภูมิคงตัว (isothermal)","ความดันคงตัว (isobaric)","อะเดียแบติก","ปริมาตรคงตัว (isochoric)"]', '2', 'กระบวนการอะเดียแบติกคือกระบวนการที่ไม่มีการแลกเปลี่ยนความร้อนกับภายนอก Q = 0', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-first-law')), 'number', 'แก๊สได้รับความร้อน 1000 จูล และพลังงานภายในเพิ่มขึ้น 400 จูล งานที่แก๊สกระทำเป็นกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":600,"tolerance":0.5}', 'Q = ΔU + W → W = Q − ΔU = 1000 − 400 = 600 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-first-law')), 'number', 'แก๊สคายความร้อน 300 จูล (Q = −300) และมีงานจากภายนอกสู่แก๊ส 200 จูล (W = −200) พลังงานภายในเปลี่ยนไปกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":-100,"tolerance":0.5}', 'ΔU = Q − W = (−300) − (−200) = −100 จูล พลังงานภายในลดลง 100 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'thermodynamics'), 'thermodynamics-gas-processes', 'กระบวนการของแก๊ส', 'กระบวนการของแก๊สมีแบบความดันคงตัว ปริมาตรคงตัว อุณหภูมิคงตัว และอะเดียแบติก แต่ละแบบมีเงื่อนไขต่างกัน เช่น กระบวนการอุณหภูมิคงตัว ΔU = 0', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes'), 'youtube', 'https://www.youtube.com/watch?v=sfPgwsAIDnw', 'sfPgwsAIDnw', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.10 (กฎข้อที่ 1 ทางเทอร์โมไดนามิกส์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes'), 'youtube', 'https://www.youtube.com/watch?v=MixKfNgltBw', 'MixKfNgltBw', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.9(พลังงานภายใน,งานเนื่องจากากรเปลี่ยนแปลงปริมาตรแก๊ส)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes'), 'แบบทดสอบ: กระบวนการของแก๊ส', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes')), 'choice', 'กระบวนการอุณหภูมิคงตัวของแก๊สอุดมคติมีสมบัติใด', '["ความดันคงที่","พลังงานภายในคงที่","ปริมาตรคงที่","งานเป็นศูนย์"]', '1', 'กระบวนการอุณหภูมิคงตัว (isothermal) T คงที่ จึง ΔU = 0 ความร้อนที่ให้เท่ากับงานที่แก๊สกระทำ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes')), 'choice', 'กระบวนการปริมาตรคงตัวของแก๊สมีลักษณะใด', '["อุณหภูมิคงที่","ความดันคงที่","งานที่แก๊สกระทำเป็นศูนย์","ความร้อนไม่มีการแลกเปลี่ยน"]', '2', 'กระบวนการปริมาตรคงตัว (isochoric) ΔV = 0 จึง W = 0 ความร้อนทั้งหมดเปลี่ยนเป็นพลังงานภายใน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes')), 'choice', 'กระบวนการอะเดียแบติกคือกระบวนการแบบใด', '["ไม่มีการแลกเปลี่ยนความร้อนกับภายนอก","อุณหภูมิคงที่","ความดันคงที่","ปริมาตรคงที่"]', '0', 'กระบวนการอะเดียแบติกคือ Q = 0 ไม่มีการแลกเปลี่ยนความร้อนกับสิ่งแวดล้อม งานทำได้จากพลังงานภายใน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes')), 'number', 'ในกระบวนการอุณหภูมิคงตัว แก๊สได้รับความร้อน 500 จูล พลังงานภายในไม่เปลี่ยน งานที่แก๊สกระทำเป็นกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":500,"tolerance":0.5}', 'กระบวนการ isothermal ΔU = 0 จาก Q = ΔU + W → W = Q = 500 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes')), 'number', 'ในกระบวนการปริมาตรคงตัว แก๊สได้รับความร้อน 300 จูล งานเป็นศูนย์ พลังงานภายในเพิ่มขึ้นกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":300,"tolerance":0.5}', 'Q = ΔU + W และ W = 0 → ΔU = Q = 300 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'thermodynamics'), 'thermodynamics-internal-energy', 'พลังงานภายในของแก๊ส', 'พลังงานภายในของแก๊สคือพลังงานรวมของโมเลกุลทั้งหมด สำหรับแก๊สอะตอมเดี่ยว U = 1.5nRT และขึ้นกับอุณหภูมิโดยตรง เมื่ออุณหภูมิคงที่พลังงานภายในคงที่', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
