INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy'), 'youtube', 'https://www.youtube.com/watch?v=sfPgwsAIDnw', 'sfPgwsAIDnw', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.10 (กฎข้อที่ 1 ทางเทอร์โมไดนามิกส์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy'), 'แบบทดสอบ: พลังงานภายในของแก๊ส', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy')), 'choice', 'พลังงานภายในของแก๊สอุดมคติในภาชนะขึ้นอยู่กับปริมาณใดเป็นหลัก', '["ปริมาตรเท่านั้น","ความดันเท่านั้น","อุณหภูมิ","ขนาดภาชนะ"]', '2', 'พลังงานภายในเป็นพลังงานจลน์รวมของโมเลกุล ซึ่งขึ้นกับอุณหภูมิสัมบูรณ์ สำหรับแก๊สอุดมคติ U = 1.5nRT', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy')), 'choice', 'ในกระบวนการอุณหภูมิคงตัว (isothermal) สำหรับแก๊สอุดมคติ พลังงานภายในเปลี่ยนอย่างไร', '["คงที่","เพิ่มขึ้น","ลดลง","เพิ่มแล้วลดลง"]', '0', 'เมื่ออุณหภูมิคงที่ พลังงานภายในคงที่ เพราะ U ขึ้นกับ T เท่านั้น การยุบตัวหรือขยายจึงไม่เปลี่ยน U', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy')), 'choice', 'แก๊สอะตอมเดี่ยวมีสูตรพลังงานภายในตามข้อใด', '["U = nRT","U = 1.5nRT","U = 0.5nRT","U = 2nRT"]', '1', 'แก๊สอะตอมเดี่ยวมี 3 องศาอิสระการเคลื่อนที่ จึงมี U = 1.5nRT', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy')), 'number', 'แก๊สอะตอมเดี่ยว 2 โมล อุณหภูมิ 300 เคลวิน R = 8.3 จูล/โมล·เคลวิน มีพลังงานภายในกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":7470,"tolerance":0.5}', 'U = 1.5nRT = 1.5 × 2 × 8.3 × 300 = 7470 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy')), 'number', 'แก๊สอุดมคติ 1 โมล อุณหภูมิเพิ่มจาก 300 เคลวินเป็น 600 เคลวิน พลังงานภายในเพิ่มขึ้นกี่เท่าของเดิม (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.05}', 'U แปรผันตรงกับ T 600/300 = 2 เท่า', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'thermodynamics'), 'thermodynamics-work-by-gas', 'งานที่แก๊สกระทำ', 'งานที่แก๊สกระทำเกิดจากการเปลี่ยนแปลงปริมาตร เท่ากับความดันคูณปริมาตรที่เปลี่ยน (W = PΔV) เมื่อความดันคงตัว และเท่ากับพื้นที่ใต้กราฟ PV', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-work-by-gas'), 'youtube', 'https://www.youtube.com/watch?v=MixKfNgltBw', 'MixKfNgltBw', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.9(พลังงานภายใน,งานเนื่องจากากรเปลี่ยนแปลงปริมาตรแก๊ส)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-work-by-gas'), 'youtube', 'https://www.youtube.com/watch?v=sfPgwsAIDnw', 'sfPgwsAIDnw', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.10 (กฎข้อที่ 1 ทางเทอร์โมไดนามิกส์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-work-by-gas'), 'แบบทดสอบ: งานที่แก๊สกระทำ', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-work-by-gas')), 'choice', 'งานที่แก๊สกระทำเมื่อขยายตัวที่ความดันคงตัวคำนวณได้จากสูตรใด', '["W = PΔV","W = P/T","W = V/ΔP","W = nRT + V"]', '0', 'ที่ความดันคงตัว งานเท่ากับความดันคูณปริมาตรที่เปลี่ยน W = PΔV', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-work-by-gas')), 'choice', 'งานที่แก๊สกระทำในกราฟความดันกับปริมาตร (PV) เท่ากับสิ่งใด', '["ความชันของกราฟ","ความยาวของกราฟ","พื้นที่ใต้กราฟ","ค่าแกนตั้ง"]', '2', 'พื้นที่ใต้กราฟ PV เท่ากับงานที่แก๊สกระทำหรือได้รับ ขึ้นกับทิศทางของกระบวนการ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-work-by-gas')), 'choice', 'แก๊สอัดตัวและปริมาตรลดลง งานระหว่างกระบวนการนี้เป็นอย่างไร', '["งานจากแก๊สออกสู่ภายนอก","งานจากภายนอกเข้าสู่แก๊ส","งานเป็นศูนย์เสมอ","งานไม่มีความหมาย"]', '1', 'เมื่อแก๊สถูกอัด ปริมาตรลดลง งานจากภายนอก(PΔV เป็นลบ)เข้าสู่แก๊ส W มีค่าน้อยกว่าศูนย์', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-work-by-gas')), 'number', 'แก๊สขยายตัวที่ความดันคงตัว 200000 พาสคัล ปริมาตรเพิ่มจาก 0.02 เป็น 0.05 ลูกบาศก์เมตร งานที่แก๊สกระทำเป็นกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":6000,"tolerance":0.5}', 'W = PΔV = 200000 × (0.05 − 0.02) = 200000 × 0.03 = 6000 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-work-by-gas')), 'number', 'แก๊สที่ความดัน 100000 พาสคัล มีปริมาตรเพิ่มขึ้น 0.01 ลูกบาศก์เมตร งานที่แก๊สกระทำเป็นกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":1000,"tolerance":0.5}', 'W = PΔV = 100000 × 0.01 = 1000 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'units-measurement'), 'units-measurement-measuring-instruments', 'เครื่องมือวัดและความคลาดเคลื่อน', 'เครื่องมือวัดแต่ละชนิดมีหน่วยวัดเล็กสุดต่างกัน เช่น ไม้บรรทัด เวอร์เนียร์ ไมโครมิเตอร์ ความคลาดเคลื่อนเกิดจากเครื่องมือและวิธีวัด', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'units-measurement-measuring-instruments'), 'youtube', 'https://www.youtube.com/watch?v=L-k6gJlQDpM', 'L-k6gJlQDpM', 'ฟิสิกส์ ม.4 เทอม 1 : Ep 4 Part 2 เรื่องเครื่องมือวัดและการวิเคราะห์การทดลอง', 'ล็อกคอฟิสิกส์ ครูพี่ตอง', 'https://www.youtube.com/channel/UCisT538gzjCGHH1ko4r9uEQ', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'units-measurement-measuring-instruments'), 'youtube', 'https://www.youtube.com/watch?v=Wc9gxVHQ9qI', 'Wc9gxVHQ9qI', 'ฟิสิกส์ ม.4 เทอม 1 : Ep.5 Part 2 : การใช้เครื่องมือวัดอย่างละเอียด (Micrometer)', 'ล็อกคอฟิสิกส์ ครูพี่ตอง', 'https://www.youtube.com/channel/UCisT538gzjCGHH1ko4r9uEQ', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'units-measurement-measuring-instruments'), 'แบบทดสอบ: เครื่องมือวัดและความคลาดเคลื่อน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-measuring-instruments')), 'choice', 'หน่วยวัดเล็กสุดของไม้บรรทัดทั่วไปคือเท่าใด', '["1 เมตร","1 เซนติเมตร","1 ไมโครเมตร","1 มิลลิเมตร"]', '3', 'ไม้บรรทัดทั่วไปมีขีดเล็กสุดทุก 1 มิลลิเมตร จึงวัดได้ละเอียดสุดที่ 1 มิลลิเมตร', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-measuring-instruments')), 'choice', 'ข้อใดเป็นสาเหตุที่ทำให้เกิดความคลาดเคลื่อนในการวัด', '["อ่านสเกลของเครื่องมือคลาดเคลื่อน","ใช้เครื่องมือที่มีความแม่นยำสูง","วัดซ้ำหลายครั้งแล้วหาค่าเฉลี่ย","เครื่องมือวัดไม่มีวันคลาดเคลื่อน"]', '0', 'การอ่านตาด้วยสายตาที่คลาดเคลื่อนและข้อจำกัดของเครื่องมือเป็นสาเหตุของความคลาดเคลื่อน ส่วนการวัดซ้ำช่วยลดได้', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-measuring-instruments')), 'choice', 'เครื่องมือใดเหมาะกับวัดความยาวที่ละเอียดถึงหลัก 0.01 มิลลิเมตร', '["ไม้บรรทัด","ไมโครมิเตอร์","ตลับเมตร","เทปวัดระยะ"]', '1', 'ไมโครมิเตอร์วัดได้ละเอียดถึงหลัก 0.01 มิลลิเมตร ละเอียดกว่าไม้บรรทัดและตลับเมตร', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-measuring-instruments')), 'number', 'ไม้บรรทัดมีหน่วยเล็กสุด 1 มิลลิเมตร ค่าความคลาดเคลื่อนโดยประมาณเท่ากับครึ่งหนึ่งของหน่วยเล็กสุด เท่ากับกี่มิลลิเมตร (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":0.5,"tolerance":0.05}', 'ความคลาดเคลื่อนโดยประมาณ = ครึ่งของหน่วยเล็กสุด = 0.5 x 1 = 0.5 มิลลิเมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-measuring-instruments')), 'number', 'เวอร์เนียร์คาลิปเปอร์มีหน่วยเล็กสุด 0.1 มิลลิเมตร ค่าความคลาดเคลื่อนโดยประมาณ (ครึ่งหนึ่งของหน่วยเล็กสุด) เป็นกี่มิลลิเมตร (ตอบเป็นทศนิยม 2 ตำแหน่ง)', NULL, '{"value":0.05,"tolerance":0.005}', 'ความคลาดเคลื่อนโดยประมาณ = 0.5 x 0.1 = 0.05 มิลลิเมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'units-measurement'), 'units-measurement-physical-quantities', 'ปริมาณทางฟิสิกส์และระบบหน่วย', 'ปริมาณทางฟิสิกส์มีทั้งปริมาณพื้นฐานและปริมาณอนุพันธ์ ระบบหน่วยเอสไอใช้เมตร กิโลกรัม วินาที เป็นหน่วยพื้นฐาน', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
