INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-unit-conversion')), 'choice', '1 กิโลเมตรมีค่าเท่ากับเท่าใด', '["100 เมตร","1000 เมตร","10000 เมตร","10 เมตร"]', '1', 'คำนำหน้า กิโล มีค่า 1000 จึงได้ 1 กิโลเมตร = 1000 เมตร', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-unit-conversion')), 'choice', 'ความเร็ว 72 กิโลเมตร/ชั่วโมงคิดเป็นกี่เมตร/วินาที', '["72 เมตร/วินาที","2 เมตร/วินาที","20 เมตร/วินาที","7200 เมตร/วินาที"]', '2', '(72 x 1000)/3600 = 20 เมตร/วินาที เพราะ 1 กม. = 1000 ม. และ 1 ชม. = 3600 วินาที', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-unit-conversion')), 'choice', 'ความยาว 500 เซนติเมตรคิดเป็นกี่เมตร', '["5000 เมตร","0.05 เมตร","50 เมตร","5 เมตร"]', '3', '1 เมตร = 100 เซนติเมตร จึงได้ 500 / 100 = 5 เมตร', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-unit-conversion')), 'number', 'ระยะทาง 2.5 กิโลเมตรเป็นกี่เมตร (ตอบเป็นเมตร จำนวนเต็ม)', NULL, '{"value":2500,"tolerance":0.5}', '2.5 x 1000 = 2500 เมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-unit-conversion')), 'number', 'ความเร็ว 54 กิโลเมตร/ชั่วโมงคิดเป็นกี่เมตร/วินาที (ตอบเป็นเมตร/วินาที จำนวนเต็ม)', NULL, '{"value":15,"tolerance":0.5}', '(54 x 1000)/3600 = 15 เมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'vectors'), 'vectors-component-arithmetic', 'การบวกลบเวกเตอร์ด้วยองค์ประกอบ', 'การบวกลบเวกเตอร์ด้วยองค์ประกอบทำโดยแยกเวกเตอร์เป็นแกน x และ y แล้วบวกลบองค์ประกอบแกนเดียวกัน จากนั้นรวมเป็นเวกเตอร์ลัพธ์', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
