INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-scalar-vector')), 'choice', 'ข้อใดเป็นปริมาณเวกเตอร์', '["ความเร็ว","มวล","ระยะทาง","อุณหภูมิ"]', '0', 'ความเร็วมีทั้งขนาดและทิศทางจึงเป็นเวกเตอร์ ส่วนมวล ระยะทาง และอุณหภูมิมีเพียงขนาดจึงเป็นสเกลาร์', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-scalar-vector')), 'choice', 'ข้อใดเป็นปริมาณสเกลาร์', '["แรง","ระยะทาง","ความเร็ว","การกระจัด"]', '1', 'ระยะทางมีเพียงขนาดจึงเป็นสเกลาร์ ส่วนแรง ความเร็ว และการกระจัดมีทิศทางจึงเป็นเวกเตอร์', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-scalar-vector')), 'choice', 'ข้อใดต่างจากข้ออื่นในเรื่องการเป็นเวกเตอร์หรือสเกลาร์', '["แรง","ความเร่ง","ระยะทาง","ความเร็ว"]', '2', 'แรง ความเร่ง และความเร็วเป็นเวกเตอร์ ส่วนระยะทางเป็นสเกลาร์ จึงเป็นข้อที่ต่างจากข้ออื่น', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-scalar-vector')), 'number', 'เวกเตอร์ขนาด 3 หน่วยกับ 4 หน่วยตั้งฉากกัน เวกเตอร์ลัพธ์มีขนาดกี่หน่วย (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":5,"tolerance":0.5}', 'เวกเตอร์ลัพธ์ = √(3² + 4²) = √25 = 5 หน่วย ตามทฤษฎีบทพีทาโกรัส', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-scalar-vector')), 'number', 'วัตถุเคลื่อนที่ไปทางทิศตะวันออก 6 เมตร แล้วไปทางทิศเหนือ 8 เมตร การกระจัดมีขนาดกี่เมตร (ตอบเป็นเมตร จำนวนเต็ม)', NULL, '{"value":10,"tolerance":0.5}', 'การกระจัด = √(6² + 8²) = √100 = 10 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'vectors'), 'vectors-vector-addition', 'การรวมเวกเตอร์', 'การรวมเวกเตอร์หาลัพธ์ได้ด้วยวิธีหัวต่อหางหรือกฎสี่เหลี่ยมด้านขนาน เวกเตอร์ลัพธ์คือเวกเตอร์จากจุดเริ่มต้นถึงจุดสุดท้าย', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'vectors-vector-addition'), 'youtube', 'https://www.youtube.com/watch?v=_a7euaF-53c', '_a7euaF-53c', 'ฟิสิกส์ ม.4 | การรวมเวกเตอร์ การหาเวกเตอร์ลัพธ์ #ฟิสิกส์ #อยากสอนอะไรก็สอน', 'ฟิสิกส์หัวจะปวด', 'https://www.youtube.com/channel/UCG8F3u-tHbes5AuEYC5TIJw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'vectors-vector-addition'), 'youtube', 'https://www.youtube.com/watch?v=V28CGU0vpZ8', 'V28CGU0vpZ8', 'สรุป ฟิสิกส์ ม.4 - แรงและกฎการเคลื่อนที่ ปริมาณเวกเตอร์ รวมเวกเตอร์ แตกเวกเตอร์', 'TUENONG', 'https://www.youtube.com/channel/UCq63wrwUoM4akEr09e9USQQ', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'vectors-vector-addition'), 'แบบทดสอบ: การรวมเวกเตอร์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-vector-addition')), 'choice', 'เวกเตอร์สองตัวไปทางเดียวกันขนาด 3 และ 5 หน่วย เวกเตอร์ลัพธ์มีขนาดเท่าใด', '["2 หน่วย","8 หน่วย","15 หน่วย","รากที่สองของ 34 หน่วย"]', '1', 'เวกเตอร์ไปทิศเดียวกันรวมขนาดกันตรงๆ = 3 + 5 = 8 หน่วย', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-vector-addition')), 'choice', 'เวกเตอร์สองตัวตรงข้ามกันขนาด 7 และ 4 หน่วย เวกเตอร์ลัพธ์มีขนาดเท่าใด', '["11 หน่วย","28 หน่วย","3 หน่วย","รากที่สองของ 65 หน่วย"]', '2', 'เวกเตอร์ตรงข้ามกันหักล้าง = 7 - 4 = 3 หน่วย ไปทางด้านของเวกเตอร์ที่ใหญ่กว่า', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-vector-addition')), 'choice', 'เวกเตอร์สองตัวตั้งฉากกันขนาด 6 และ 8 หน่วย เวกเตอร์ลัพธ์มีขนาดเท่าใด', '["2 หน่วย","14 หน่วย","48 หน่วย","10 หน่วย"]', '3', 'เวกเตอร์ตั้งฉากหาลัพธ์ด้วยพีทาโกรัส = √(6² + 8²) = √100 = 10 หน่วย', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-vector-addition')), 'number', 'เวกเตอร์ขนาด 5 หน่วยกับ 12 หน่วยตั้งฉากกัน เวกเตอร์ลัพธ์มีขนาดกี่หน่วย (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":13,"tolerance":0.5}', '√(5² + 12²) = √169 = 13 หน่วย', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-vector-addition')), 'number', 'เวกเตอร์ขนาด 30 หน่วยกับ 40 หน่วยตั้งฉากกัน เวกเตอร์ลัพธ์มีขนาดกี่หน่วย (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":50,"tolerance":0.5}', '√(30² + 40²) = √2500 = 50 หน่วย', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'vectors'), 'vectors-vector-components', 'การแตกเวกเตอร์', 'การแตกเวกเตอร์คือการแยกเวกเตอร์ออกเป็นองค์ประกอบในแนวแกนตั้งฉาก เช่น แกน x และแกน y โดยใช้ตรีโกณมิติ', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
