INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'vectors-vector-components'), 'youtube', 'https://www.youtube.com/watch?v=0nltg8benaA', '0nltg8benaA', 'เวกเตอร์ (Vector) [ฟิสิกส์ ม.ต้น/ฟิสิกส์ ม.4] | Physics by ครูพี่เต้ย ออนดิมานด์', 'ติวฟิสิกส์ by Kruptoey', 'https://www.youtube.com/channel/UCBz_bPL0mKbx6uGD55iW90A', 2);
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'vectors-vector-components'), 'แบบทดสอบ: การแตกเวกเตอร์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-vector-components')), 'choice', 'เวกเตอร์ F ทำมุม θ กับแกน x องค์ประกอบในแนวแกน x คือข้อใด', '["F sin θ","F","F cos θ","F / sin θ"]', '2', 'องค์ประกอบในแนวแกนที่เวกเตอร์ทำมุมด้วยใช้ cos เป็น F cos θ ส่วนแนวตั้งฉากใช้ F sin θ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-vector-components')), 'choice', 'เวกเตอร์ F ทำมุม θ กับแกน x องค์ประกอบในแนวแกน y คือข้อใด', '["F cos θ","F","F / cos θ","F sin θ"]', '3', 'องค์ประกอบแนวแกน y (แกนที่ตั้งฉากกับมุม) ใช้ F sin θ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-vector-components')), 'choice', 'เวกเตอร์ที่ขนานกับแกน x ล้วน ไม่มีองค์ประกอบในแนวใด', '["แกน y","แกน x","ทั้งแกน x และแกน y","ทุกแกน"]', '0', 'เวกเตอร์ขนานแกน x มีองค์ประกอบในแนวแกน x เต็มขนาด และไม่มีองค์ประกอบในแนวแกน y เลย', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-vector-components')), 'number', 'แตกแรง 10 นิวตันซึ่งทำมุม 60 องศากับแกน x องค์ประกอบในแนวแกน x เป็นกี่นิวตัน (กำหนด cos 60° = 0.5 ตอบเป็นจำนวนเต็ม)', NULL, '{"value":5,"tolerance":0.5}', 'F x = F cos θ = 10 x 0.5 = 5 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-vector-components')), 'number', 'จากแรง 10 นิวตันทำมุม 60 องศากับแกน x องค์ประกอบในแนวแกน y เป็นกี่นิวตัน (กำหนด sin 60° ≈ 0.866 ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":8.7,"tolerance":0.05}', 'F y = F sin θ = 10 x 0.866 = 8.66 ≈ 8.7 นิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'wave-properties'), 'wave-properties-diffraction', 'การเลี้ยวเบนของคลื่น', 'การเลี้ยวเบนคือการที่คลื่นแผ่อ้อมสิ่งกีดขวางหรือผ่านช่องแคบแล้วกระจายออกไป การเลี้ยวเบนเด่นชัดเมื่อขนาดช่องแคบหรือสิ่งกีดขวางใกล้เคียงกับความยาวคลื่น', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
