INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-interference')), 'choice', 'การแทรกสอดแบบเสริม (constructive interference) เกิดเมื่อใด', '["หุบคลื่นพบกับหุบคลื่นพอดีที่จุดเดียวกัน","ยอดคลื่นกับยอดคลื่น หรือหุบกับหุบมาถึงจุดเดียวกันพอดี","ยอดคลื่นพบกับหุบคลื่นพอดี","คลื่นเคลื่อนที่ช้าลงในตัวกลาง"]', '1', 'การแทรกสอดแบบเสริมเกิดเมื่อคลื่นทั้งสองมีเฟสเดียวกัน เช่น ยอดพบยอด ทำให้แอมพลิจูดลัพธ์ใหญ่สุด', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-interference')), 'choice', 'การแทรกสอดแบบหักล้าง (destructive interference) มีผลต่อคลื่นลัพธ์อย่างไร', '["แอมพลิจูดเพิ่มขึ้นเป็นสองเท่า","ความถี่เพิ่มขึ้น","แอมพลิจูดลดลง และอาจเป็นศูนย์ถ้าแอมพลิจูดเท่ากัน","อัตราเร็วเพิ่มขึ้น"]', '2', 'การแทรกสอดแบบหักล้างเกิดเมื่อคลื่นเฟสตรงข้ามกัน แอมพลิจูดลัพธ์ลดลง และเป็นศูนย์ถ้าแอมพลิจูดเท่ากัน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-interference')), 'choice', 'จากแหล่งกำเนิดที่เฟสเดียวกันสองแหล่ง ณ จุดที่คลื่นสองขบวนเดินทางมามีผลต่างของระยะทางเท่ากับหนึ่งความยาวคลื่นพอดี เกิดการแทรกสอดแบบใด', '["แบบเสริม","แบบหักล้าง","ไม่เกิดการแทรกสอด","แบบสะท้อน"]', '0', 'ผลต่างระยะทางเป็นจำนวนเต็มเท่าของความยาวคลื่น ทำให้คลื่นเฟสเดียวกัน เกิดการแทรกสอดแบบเสริม', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-interference')), 'number', 'คลื่น A มีแอมพลิจูด 2 เซนติเมตร และคลื่น B มีแอมพลิจูด 3 เซนติเมตร มาถึงจุดเดียวกันแบบเฟสเดียวกันพอดี แอมพลิจูดคลื่นลัพธ์เท่ากับกี่เซนติเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":5,"tolerance":0.5}', 'แทรกสอดแบบเสริม แอมพลิจูดลัพธ์ = 2 + 3 = 5 เซนติเมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-interference')), 'number', 'คลื่น A มีแอมพลิจูด 3 เซนติเมตร และคลื่น B มีแอมพลิจูด 2 เซนติเมตร มาถึงจุดเดียวกันแบบเฟสตรงข้ามกันพอดี แอมพลิจูดคลื่นลัพธ์เท่ากับกี่เซนติเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":1,"tolerance":0.5}', 'แทรกสอดแบบหักล้าง แอมพลิจูดลัพธ์ = |3 − 2| = 1 เซนติเมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'wave-properties'), 'wave-properties-reflection', 'การสะท้อนของคลื่น', 'เมื่อคลื่นสะท้อนจากผิว มุมสะท้อนเท่ากับมุมตกกระทบ ถ้าสะท้อนจากปลายตรึงเฟสจะกลับ 180 องศา แต่ถ้าจากปลายอิสระเฟสไม่เปลี่ยน ความถี่และอัตราเร็วคงเดิม', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
